import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastReader in = new FastReader(inputStream);
            PrintWriter out = new PrintWriter(outputStream);
            DCleaningThePhone solver = new DCleaningThePhone();
            int testCount = Integer.parseInt(in.next());
            for (int i = 1; i <= testCount; i++)
                solver.solve(i, in, out);
            out.close();
        }
    }

    static class DCleaningThePhone {
        public void solve(int testNumber, FastReader s, PrintWriter w) {
            int n = s.nextInt(), m = s.nextInt();
            long sum = 0;
//        ArrayList<Integer>[] mem = new ArrayList[2];
//        mem[0] = new ArrayList<>();
//        mem[1] = new ArrayList<>();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = s.nextInt();
                sum += a[i];
            }
            int[] b = new int[n], f = new int[2];
            for (int i = 0; i < n; i++) {
                b[i] = s.nextInt() - 1;
                f[b[i]]++;
            }
            if (sum < m) {
                w.println(-1);
                return;
            }
            long[][] mem = new long[2][];
            mem[0] = new long[f[0] + 1];
            mem[1] = new long[f[1] + 1];
            int[] ptr = new int[2];
            ptr[0] = ptr[1] = 1;
            for (int i = 0; i < n; i++) mem[b[i]][ptr[b[i]]++] = a[i];
            mem[0][0] = mem[1][0] = Integer.MAX_VALUE;
            func.sort(mem[0]);
            func.sort(mem[1]);
            for (int i = 0; i <= f[0] >> 1; i++) {
                long tm = mem[0][i];
                mem[0][i] = mem[0][f[0] - i];
                mem[0][f[0] - i] = tm;
            }
            for (int i = 0; i <= f[1] >> 1; i++) {
                long tm = mem[1][i];
                mem[1][i] = mem[1][f[1] - i];
                mem[1][f[1] - i] = tm;
            }
            mem[0][0] = mem[1][0] = 0;
            for (int i = 0; i < 2; i++)
                for (int j = 2; j <= f[i]; j++)
                    mem[i][j] += mem[i][j - 1];
            int res = f[0] + 2 * f[1];
//        if (n == 5 && m == 10) {
//            for (int i = 0; i <= f[0]; i++) w.print(mem[0][i] + " ");
//            w.println();
//            for (int i = 0; i <= f[1]; i++) w.print(mem[1][i] + " ");
//            w.println();
//        }
            for (int i = 0; i <= f[0]; i++) {
                long req = m - mem[0][i];
                int tot = func.bing(mem[1], 0, f[1], req);
                if (tot <= f[1]) res = Math.min(res, i + tot * 2);
            }
            w.println(res);
        }

    }

    static class func {
        public static int bing(long[] a, int l, int r, long val) {
            int mid;
            while (l <= r) {
                mid = l + r >> 1;
                if (a[mid] >= val) r = mid - 1;
                else l = mid + 1;
            }
            return ++r;
        }

        public static void sort(long[] arr) {
            int n = arr.length, mid, h, s, l, i, j, k;
            long[] res = new long[n];
            n--;
            for (s = 1; s <= n; s <<= 1) {
                for (l = 0; l < n; l += (s << 1)) {
                    h = Math.min(l + (s << 1) - 1, n);
                    mid = Math.min(l + s - 1, n);
                    i = l;
                    j = mid + 1;
                    k = l;
                    while (i <= mid && j <= h)
                        res[k++] = arr[i] <= arr[j] ? arr[i++] : arr[j++];
                    while (i <= mid) res[k++] = arr[i++];
                    while (j <= h) res[k++] = arr[j++];
                    for (k = l; k <= h; k++) arr[k] = res[k];
                }
            }
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {

            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {

                curChar = 0;

                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }

            return buf[curChar++];
        }

        public int nextInt() {

            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public String next() {

            int c = read();

            while (isSpaceChar(c))
                c = read();

            StringBuilder res = new StringBuilder();

            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {

            if (filter != null)
                return filter.isSpaceChar(c);

            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

