import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
// import java.math.BigInteger;
import java.util.*;

public class d {
    public static void main(String[] args) {
        int T = in.nextInt();
TEST:   while (T-- > 0) {
            int n = in.nextInt();
            long m = in.nextLong();
            int[] a = in.readIntArray(n);
            List<Long> p1 = new ArrayList<>();
            List<Long> p2 = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (in.nextInt() == 1) {
                    p1.add(1l*a[i]);
                } else {
                    p2.add(1l*a[i]);
                }
            }
            Collections.sort(p1, Collections.reverseOrder());
            Collections.sort(p2, Collections.reverseOrder());
            for (int i = 1; i < p1.size(); i++) {
                p1.set(i, p1.get(i) + p1.get(i-1));
            }
            long ans = Long.MAX_VALUE;
            long sum = 0l;
            for (int i = -1; i < p2.size(); i++) {
                if (i >= 0) {
                    sum += p2.get(i);
                }
                if (sum >= m) {
                    ans = Math.min(2*(i+1), ans);
                } else {
                    int j = search(p1, m-sum);
                    if (j < p1.size() && sum + p1.get(j) >= m) {
                        ans = Math.min(2*(i+1) + j+1, ans);
                    }
                }
                //out.println(ans);
            }
            out.println((ans == Long.MAX_VALUE)? -1 : ans);
        }
        out.flush();
        out.close();
    }

    // Change Array type as necessary.
    static void printArray(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            out.print(arr[i] + " ");
        }
        out.println();
    }

    static int search(List<Long> arr, long target) {
        // ~ [lower_bound] & [upper_bound -> search for 1+target]
        int lo = 0, hi = arr.size() - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (arr.get(mid) >= target) {
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        // Ensure existence for exact matches
        // if (lo == arr.length || arr[lo] != target)
        // {
        //     return -1;
        // }
        return lo;
    }

    static void sort(int[] arr) {
        // Random Shuffle guarantees O(nlogn) WCTC for Quick Sort.
        Random rnd = new Random();
        for (int i = arr.length - 1; i > 0; i--) {
            swap(arr, i, rnd.nextInt(i));
        }
        // Dual-Pivot Quicksort Implementation
        Arrays.sort(arr);
    }

    static boolean[] sieve(int n) {
        boolean[] primes = new boolean[n + 1];
        primes[2] = true;
        for (int i = 3; i <= n; i += 2) {
            primes[i] = true;
        }
        for (int p = 3; 1l * p * p <= n; p += 2) {
            if (primes[p]) {
                for (int k = p * p; k <= n; k += p) {
                    primes[k] = false;
                }
            }
        }
        return primes;
    }

    // MLE -> Use BitSet
    static BitSet bitsieve(int n) {
        BitSet primes = new BitSet(n + 1);
        primes.set(2);
        for (int i = 3; i <= n; i += 2) {
            primes.set(i);
        }
        for (int p = 3; 1l * p * p <= n; p += 2) {
            if (primes.get(p)) {
                for (int k = p * p; k <= n; k += p) {
                    primes.set(k, false);
                }
            }
        }
        return primes;
    }

    static void swap(int[] arr, int i, int j) {
        arr[i] = arr[i] ^ arr[j];
        arr[j] = arr[i] ^ arr[j];
        arr[i] = arr[i] ^ arr[j];
    }

    static void swap(int x, int y) {
        x = x ^ y;
        y = x ^ y;
        x = x ^ y;
    }

    // Precompute before running testcases
    static long[] fact;
    static void factorial(int lim) {
        fact = new long[lim];
        fact[0] = 1;
        for (int i = 1; i < lim; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
    }

    static long modInv(long x) {
        return pow(x, MOD - 2, MOD);
    }

    static long modInv(long x, int MOD) {
        return pow(x, MOD - 2, MOD);
    }

    static long perm(int n, int r) {
        // assert(fact != null);
        if (n < r) {
            return 0;
        }
        return (fact[n] * (modInv(fact[n - r]) % MOD)) % MOD;
    }

    static long comb(int n, int r) {
        // assert(fact != null);
        if (n < r) {
            return 0;
        }
        if (n == r) {
            return 1;
        }
        return (fact[n] * (((fact[r] % MOD) * (fact[n - r] % MOD)) % MOD)) % MOD;
    }

    static long pow(long x, long y) {
        // assert(y >= 0);
        if (x == 0) {
            return 0;
        }
        if (x == 1 || y == 0) {
            return 1;
        }
        long res = 1l;
        while (y > 1) {
            if ((y & 1) == 1) {
                res *= x;
            }
            x *= x;
            y >>= 1;
        }
        return res * x;
    }

    static long pow(long x, long y, int MOD) {
        // assert(y >= 0);
        if (x == 0) {
            return 0;
        }
        if (x == 1 || y == 0) {
            return 1;
        }
        // Use Math.floorMod or (MOD + res)%MOD
        // for handling negative x if necessary.
        x %= MOD;
        long res = 1l;
        while (y > 1) {
            if ((y & 1) == 1) {
                res = (res * x) % MOD;
            }
            x = (x * x) % MOD;
            y >>= 1;
        }
        return (res * x) % MOD;
    }

    // Handle I/O
    static int MOD = (int) (1e9 + 7);
    static FastScanner in = new FastScanner();
    static PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = null;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] readIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] readLongArray(int size) {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] readDoubleArray(int size) {
            double[] arr = new double[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextDouble();
            }
            return arr;
        }
    }
}

