  for a,b in zip(memories,convenience):
    if b==1: X.append(a)
    else: Y.append(a)
  X.sort(reverse=True)
  Y.sort()
  i, j = 0, 0
  suma = sum(Y)
  puntos = float("inf")
  while i<=len(X):
    while j<len(Y) and suma-Y[j]>=m:
      suma-=Y[j]
      j+=1
    if suma>=m:
      puntos=min(puntos,i+2*(len(Y)-j))
    if i<len(X):
      suma+=X[i]
    i+=1
  if suma<m:
    print(-1)
    continue
  print(puntos)

