static void testcase() {

	int N = s.nextInt();
	long M = s.nextLong();
	long[] A = s.nextlongArray(N);
	int[] B = s.nextIntArray(N);

	PriorityQueue<Long> ones = 
			new PriorityQueue<Long>(Collections.reverseOrder()), 
			twos = new PriorityQueue<Long>(Collections.reverseOrder());

	for(int i = 0; i < N; i++) {
		if(B[i] == 1) ones.add(A[i]);
		else twos.add(A[i]);
	}

	long curFree = 0;
	int curLost = 0;
	boolean ok = false;

	while(curFree < M) {

		if(ones.size() >= 1 && curFree + ones.peek() >= M) {
			curFree += ones.poll();
			curLost++;
			ok = true;
			break;
		}

		else {

			// I have to lose at least two points

			if(ones.size() >= 2 && twos.size() >= 1) {

				long op1 = ones.poll(), op2 = ones.poll(), tp1 = twos.poll();

				if(op1 + op2 <= tp1) {
					curFree += tp1;
					ones.add(op1);
					ones.add(op2);
					curLost += 2;
				}

				else {
					curFree += op1;
					ones.add(op2);
					twos.add(tp1);
					curLost++;
				}

			}

			else if(ones.size() >= 2) {
				curFree += ones.poll();
				curLost++;
			}

			else if(twos.size() >= 1) {
				curFree += twos.poll();
				curLost += 2;
			}

			else {
				out.println("-1");
				return;
			}

		}

//		out.println("curFree = " + curFree + " curLost = " + curLost);


	}

	out.println(curLost);

}








