import java.io.*;
import java.util.*;

public class Main {
    static ArrayList<Integer> twos;
    public static int lowerBound(int target){
        int l = 0; int r = twos.size()-1;
        while(l < r){
            int mid = l + (r-l)/2;

            if(twos.get(mid) >= target) r = mid;
            else l = mid+1;
        }

        return r;
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        int tc = sc.nextInt();
        while(tc --> 0) {
            int n = sc.nextInt(), m = sc.nextInt();
            int[] w = sc.nextIntArr(n);
            int[] c = sc.nextIntArr(n);
            ArrayList<Integer> ones = new ArrayList<>(); twos = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if(c[i] == 1) ones.add(w[i]);
                else twos.add(w[i]);
            }
            Collections.sort(ones, Collections.reverseOrder());
            Collections.sort(twos, Collections.reverseOrder());
            for (int i = 1; i < ones.size(); i++) {
                ones.set(i, ones.get(i-1) + ones.get(i));
            }
            for (int i = 1; i < twos.size(); i++) {
                twos.set(i, twos.get(i-1) + twos.get(i));
            }

//            pw.println(ones); pw.println(twos);

            int bestC = Integer.MAX_VALUE;
            for (int i = 0; i < twos.size(); i++) {
                if(twos.get(i) >= m){
                    bestC = Math.min(bestC, (i+1)*2);
                    break;
                }
            }

            for (int i = 0; i < ones.size(); i++) {
                int onesW = ones.get(i);
                if(onesW >= m) bestC = Math.min(bestC, i+1);
                else{
                    int idx = lowerBound(m-onesW);
                    if(idx == -1) continue;
                    int twosW = twos.get(idx);
                    int cost1 = i+1, cost2 = (idx+1)*2;
                    if(onesW + twosW >= m) bestC = Math.min(cost1+cost2, bestC);
                }
            }
            pw.println(bestC == Integer.MAX_VALUE ? -1 : bestC);
        }

        pw.close();
    }

    public static void pairSort(Pair[] arr) {
        ArrayList<Pair> l = new ArrayList<>();
        Collections.addAll(l, arr);
        Collections.sort(l);
        for (int i = 0; i < arr.length; i++) {
            arr[i] = l.get(i);
        }
    }
    public static void longSort(long[] arr) {
        ArrayList<Long> l = new ArrayList<>();
        for (long i : arr) l.add(i);
        Collections.sort(l);
        for (int i = 0; i < arr.length; i++) {
            arr[i] = l.get(i);
        }
    }
    public static void intSort(int[] arr) {
        ArrayList<Integer> l = new ArrayList<>();
        for (int i : arr) l.add(i);
        Collections.sort(l);
        for (int i = 0; i < arr.length; i++) {
            arr[i] = l.get(i);
        }
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            String x = next();
            StringBuilder sb = new StringBuilder("0");
            double res = 0, f = 1;
            boolean dec = false, neg = false;
            int start = 0;
            if (x.charAt(0) == '-') {
                neg = true;
                start++;
            }
            for (int i = start; i < x.length(); i++)
                if (x.charAt(i) == '.') {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                } else {
                    sb.append(x.charAt(i));
                    if (dec)
                        f *= 10;
                }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg ? -1 : 1);
        }

        public boolean ready() throws IOException {
            return br.ready();
        }

        public int[] nextIntArr(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = Integer.parseInt(next());
            }
            return arr;
        }

        public long[] nextLongArr(int n) throws IOException {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = Long.parseLong(next());
            }
            return arr;
        }

    }
    static class Pair implements Comparable<Pair>{
        long first; long second;
        public Pair(long first, long second){
            this.first = first; this.second = second;
        }

        @Override
        public int compareTo(Pair p2) {
            if(second == p2.second) return (int) (p2.first - first);
            else return (int) (second - p2.second);
        }

        @Override
        public String toString() { return "("+ first + "," + second + ')'; }
    }
    static class Triple implements Comparable<Triple> {
        double x, y, z, sum;

        Triple(double a, double b, double c) { x = a; y = b; z = c; sum = x + y + z; }


        public int compareTo(Triple t)
        {
            if(Math.abs(sum - t.sum) < 1e-9) return x > t.x ? 1 : -1;
            return sum > t.sum ? 1 : -1;
        }
        public String toString()
        {
            return x + " " + y  + " " + z;
        }
    }

    static PrintWriter pw = new PrintWriter(System.out);
    static Scanner sc = new Scanner(System.in);
    static Random random = new Random();
    static final long MOD = 1073741824;
}

