import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Contest690 {

    public static final int MOD = 1000000007;
    public static void main(String[] args)throws Exception{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int t = Integer.parseInt(br.readLine());

        while(t-->0) {
            String s = br.readLine();
            String[] str = s.split(" ");

            int n = Integer.parseInt(str[0]);
            int m = Integer.parseInt(str[1]);

            ArrayList<Long> memory1 = new ArrayList<>();
            ArrayList<Long> memory2 = new ArrayList<>();
            int[] memory = new int[n];
            int[] points = new int[n];

            s = br.readLine();
            str = s.split(" ");
            for (int i = 0; i < n; i++) {
                memory[i] = Integer.parseInt(str[i]);
            }

            s = br.readLine();
            str = s.split(" ");
            for (int i = 0; i < n; i++) {
                points[i] = Integer.parseInt(str[i]);
            }

            for (int i = 0; i < n; i++) {
                if(points[i]==1) {
                    memory1.add((long)memory[i]);
                }
                else {
                    memory2.add((long)memory[i]);
                }
            }
            Collections.sort(memory1,Collections.reverseOrder());
            Collections.sort(memory2,Collections.reverseOrder());

            long sum = 0;
            for (int i = 0; i < memory1.size(); i++) {
                sum+=memory1.get(i);
                memory1.set(i,sum);
            }

            int pos = Integer.MAX_VALUE;
            if(sum>=m) {
                pos = Collections.binarySearch(memory1, (long)m);
                if (pos < 0) {
                    pos = Math.abs(pos)-1;
                }
                pos++;
            }

            long sum1 = 0;
            for (int i = 0; i < memory2.size(); i++) {
                sum1+=memory2.get(i);
                if(sum1>=m){
                    pos = Math.min(pos,(i+1)*2);
                    break;
                }
                int pos1 = Collections.binarySearch(memory1, m - sum1);
                if (pos1 < 0) {
                    pos1 = Math.abs(pos1) - 1;
                }
                if (pos1 == memory1.size()) {
                    continue;
                }
                pos1++;
                pos = Math.min(pos, (i + 1) * 2 + pos1);
            }

            if(sum+sum1<m){
                System.out.println(-1);
                continue;
            }

            System.out.println(pos);

        }

    }

}

