import java.io.*;
import java.util.*;

final public class D {

    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int tst = Integer.parseInt(br.readLine());
        while(tst-->0){
            String[] str = br.readLine().split(" ");
            int n = Integer.parseInt(str[0]), m = Integer.parseInt(str[1]);
            StringTokenizer st1 = new StringTokenizer(br.readLine());
            StringTokenizer st2 = new StringTokenizer(br.readLine());
            ArrayList<Integer> lst1 = new ArrayList<>();
            ArrayList<Integer> lst2 = new ArrayList<>();
            int b = 0, a = 0;
            for(int i = 0; i<n; i++){
                a = Integer.parseInt(st1.nextToken());
                b = Integer.parseInt(st2.nextToken());
                if(b == 1) lst1.add(a);
                else lst2.add(a);
            }
            lst1.sort(Collections.reverseOrder());
            lst2.sort(Collections.reverseOrder());
            int l1 = lst1.size(), l2 = lst2.size();
            long[] pref1 = new long[l1+1];
            long[] pref2 = new long[l2+1];
            for(int i = 1; i<=l1; i++){
                pref1[i] = pref1[i-1] + lst1.get(i-1);
            }
            for(int i = 1; i<=l2; i++){
                pref2[i] = pref2[i-1] + lst2.get(i-1);
            }
            int ans = Integer.MAX_VALUE, p2 = 0;
            while(p2+1<=l2 && pref2[p2]<m) p2++;
            if(pref2[p2]>=m)
            ans = 2*p2;
            for(int i = 1; i<=l1; i++){
                int l = -1, r = l2+1;
                while(l+1<r){
                    int mid = (l+r)/2;
                    if(pref1[i]+pref2[mid]>=m) r = mid;
                    else l = mid;
                }
                if(r!=l2+1){
                    ans = Math.min(ans, i + 2*r);
                }
            }
            if(ans == Integer.MAX_VALUE) sb.append(-1).append('\n');
            else sb.append(ans).append('\n');
        }
        System.out.println(sb);
    }
}

