        assert(n - j - 1 < 2000005);
        long long v1 = (h1[j + l0] - h1[j] + (long long)1000000009) %
                       (long long)1000000009 * pow1[n - j - 1] %
                       (long long)1000000009;
        long long v2 = (h2[j + l0] - h2[j] + (long long)1000000007) %
                       (long long)1000000007 * pow2[n - j - 1] %
                       (long long)1000000007;
        if (ha0 == make_pair(-1LL, -1LL)) {
          ha0 = {v1, v2};
        } else if (make_pair(v1, v2) != ha0)
          break;
        j += l0;
      } else {
        if (j + l1 > n) break;
        assert(j < n);
        assert(j + l1 < h1.size());
        assert(j >= 0);
        assert(l1 > 0);
        assert(l1 < n);
        assert(n - j - 1 >= 0);
        assert(n - j - 1 < 2000005);
        long long v1 = (h1[j + l1] - h1[j] + (long long)1000000009) %
                       (long long)1000000009 * pow1[n - j - 1] %
                       (long long)1000000009;
        long long v2 = (h2[j + l1] - h2[j] + (long long)1000000007) %
                       (long long)1000000007 * pow2[n - j - 1] %
                       (long long)1000000007;
        if (ha1 == make_pair(-1LL, -1LL)) {
          ha1 = {v1, v2};
        } else if (make_pair(v1, v2) != ha1)
          break;
        j += l1;
      }
      i++;
    }
    if (i == m && j == n && ha0 != ha1) count++;
  }
  printf("%lld\n", count);
  return 0;
}

