#include <bits/stdc++.h>
using namespace std;
unsigned long long h1[1000100], h2[1000100], deg1[1000100], deg2[1000100];
string s1, s2;
int n1, n2, k0, k1, ans, f0, f1;
long long getHash1(int l, int r) { return h1[r + 1] - h1[l] * deg1[r - l + 1]; }
long long getHash2(int l, int r) { return h2[r + 1] - h2[l] * deg2[r - l + 1]; }
bool checkHash(int l1, int r1, int l2, int r2) {
  return ((getHash1(l1, r1) == getHash1(l2, r2)) &&
          (getHash2(l1, r1) == getHash2(l2, r2)));
}
bool check(int l0, int l1) {
  if ((l0 == 0) || (l1 == 0)) return 0;
  int p1 = f0 * l1;
  int p2 = p1 + l0;
  for (int i = f0 + 1; i < n1; i++)
    if (s1[i] == '1') {
      p2 += l1;
    } else {
      if (!checkHash(p1, p1 + l0 - 1, p2, p2 + l0 - 1)) return 0;
      p2 += l0;
    }
  p1 = f1 * l0;
  p2 = p1 + l1;
  for (int i = f1 + 1; i < n1; i++)
    if (s1[i] == '0') {
      p2 += l0;
    } else {
      if (!checkHash(p1, p1 + l1 - 1, p2, p2 + l1 - 1)) return 0;
      p2 += l1;
    }
  if (l1 != l0) return 1;
  if (!checkHash(f0 * l1, f0 * l1 + l0 - 1, f1 * l0, f1 * l0 + l0 - 1))
    return 1;
  return 0;
}
int main() {
  getline(cin, s1);
  n1 = s1.length();
  f0 = -1;
  f1 = -1;
  for (int i = 0; i < n1; i++) {
    if (s1[i] == '0') {
      k0++;
      if (f0 == -1) f0 = i;
    } else {
      k1++;
      if (f1 == -1) f1 = i;
    }
  }
  getline(cin, s2);
  n2 = s2.length();
  long long p1 = 1000 * 1000 * 1000 + 7;
  long long p2 = rand() % 10000 + 1000 * 1000 * 1000 + 11;
  deg1[0] = 1;
  deg2[0] = 1;
  for (int i = 0; i < n2; i++) {
    h1[i + 1] = h1[i] * p1 + s2[i];
    h2[i + 1] = h2[i] * p2 + s2[i];
    deg1[i + 1] = deg1[i] * p1;
    deg2[i + 1] = deg2[i] * p2;
  }
  for (int i = 1; i <= n2 / k0; i++)
    if ((n2 - k0 * i) % k1 == 0)
      if (check(i, (n2 - k0 * i) / k1)) ans++;
  printf("%d\n", ans);
  return 0;
}

