#include <bits/stdc++.h>
using namespace std;
const int rbase[] = {29, 31, 33, 39, 41, 43, 101};
long long Rand(long long l, long long r) {
  return ((long long)rand() * (RAND_MAX + 1) * (RAND_MAX + 1) * (RAND_MAX + 1) +
          (long long)rand() * (RAND_MAX + 1) * (RAND_MAX + 1) +
          (long long)rand() * (RAND_MAX + 1) + (long long)rand()) %
             (r - l + 1) +
         l;
}
long long base[2];
string s, t;
long long Hash[2][1010100], POW[2][1010100];
const long long MOD = 1e9 + 7;
int n, m, a;
void Init() {
  for (int j = 0; j < (2); ++j) {
    Hash[j][0] = 0;
    POW[j][0] = 1;
    for (int i = (1); i <= (m); ++i) {
      POW[j][i] = POW[j][i - 1] * base[j] % MOD;
      Hash[j][i] = (Hash[j][i - 1] * base[j] + (t[i - 1] - 'a' + 1)) % MOD;
    }
  }
}
pair<long long, long long> Get(int l, int r) {
  return pair<long long, long long>(
      (Hash[0][r] - Hash[0][l - 1] * POW[0][r - l + 1] + MOD * MOD) % MOD,
      (Hash[1][r] - Hash[1][l - 1] * POW[1][r - l + 1] + MOD * MOD) % MOD);
}
int Ok(int x, int y) {
  int l = 1;
  pair<long long, long long> h0, h1;
  int ok0 = 0, ok1 = 0;
  for (char c : s) {
    if (c == '0') {
      if (ok0) {
        if (Get(l, l + x - 1) != h0) return 0;
      } else {
        ok0 = 1;
        h0 = Get(l, l + x - 1);
      }
      l += x;
    } else {
      if (ok1) {
        if (Get(l, l + y - 1) != h1) return 0;
      } else {
        ok1 = 1;
        h1 = Get(l, l + y - 1);
      }
      l += y;
    }
  }
  return x != y || h0 != h1;
}
int main() {
  srand(time(NULL));
  ios::sync_with_stdio(false);
  cin.tie(NULL);
  cout.tie(NULL);
  base[0] = Rand(0, 5);
  base[1] = Rand(base[0] + 1, 6);
  base[0] = rbase[base[0]];
  base[1] = rbase[base[1]];
  cin >> s >> t;
  int a = 0;
  for (char c : s)
    if (c == '0') ++a;
  n = s.size();
  m = t.size();
  Init();
  int cnt = 0;
  for (int x = (1); x <= (m); ++x) {
    long long y = m - 1ll * x * a;
    if (y < n - a) continue;
    if (y % (n - a)) continue;
    y /= (n - a);
    if (Ok(x, y)) cnt++;
  }
  cout << cnt;
}

solution_6:
#include <bits/stdc++.h>
using namespace std;
const int N = 1000005;
const int base = 17215;
const int mod = 1000000123;
int n, m;
int cnt[2];
int hs[N], pw[N];
string s, t;
int get(int l, int r) {
  return (hs[r] - 1LL * pw[r - l + 1] * hs[l - 1] % mod + mod) % mod;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin >> s >> t;
  n = s.size(), m = t.size();
  s = '~' + s;
  t = '~' + t;
  hs[0] = 0, pw[0] = 1;
  for (int i = 1; i <= m; ++i) {
    hs[i] = (1LL * hs[i - 1] * base % mod + (t[i] - 'a' + 5)) % mod;
    pw[i] = 1LL * pw[i - 1] * base % mod;
  }
  if (s[1] == '1') {
    for (int i = 1; i <= n; ++i) s[i] = '0' + '1' - s[i];
  }
  for (int i = 1; i <= n; ++i) cnt[s[i] - '0']++;
  int ans = 0;
  for (int len_r0 = 1; len_r0 <= m; ++len_r0) {
    long long all_r0 = (long long)cnt[0] * len_r0;
    long long all_r1 = (long long)m - all_r0;
    if (all_r1 <= 0 || all_r1 % cnt[1]) continue;
    int len_r1 = all_r1 / cnt[1];
    int hs0 = get(1, len_r0);
    int hs1 = -1;
    int ptr = 1;
    bool flag = true;
    for (int i = 1; i <= n; ++i) {
      if (s[i] == '0') {
        if (get(ptr, ptr + len_r0 - 1) != hs0) {
          flag = false;
          break;
        }
        ptr += len_r0;
      } else {
        if (hs1 == -1) hs1 = get(ptr, ptr + len_r1 - 1);
        if (get(ptr, ptr + len_r1 - 1) != hs1) {
          flag = false;
          break;
        }
        ptr += len_r1;
      }
    }
    if (hs0 == hs1) flag = false;
    ans += flag;
  }
  cout << ans << '\n';
}

solution_7:
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ld = long double;
struct Hasher {
  vector<ll> power = {1}, pref = {0};
  ll mod, q;
  char c;
  Hasher(const string& s, ll m, ll _q, char _c) : mod(m), q(_q), c(_c) {
    for (char x : s) {
      power.push_back(power.back() * q % mod);
      pref.push_back((pref.back() * q % mod + (x - c)) % mod);
    }
  }
  ll hash(int l, int r) {
    return (pref[r] - power[r - l] * pref[l] % mod + mod) % mod;
  }
};
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  string a, b;
  cin >> a >> b;
  Hasher hash(b, 1700000009, 29, 'a');
  vector<ll> count(2);
  vector<ll> pos(2, 0x3FFFFFFFFFFll);
  for (ll i = 0; i < (int)(a).size(); i++) {
    count[a[i] - '0']++;
    pos[a[i] - '0'] = min(i, pos[a[i] - '0']);
  }
  ll res = 0;
  for (ll i = 1; ((int)(b).size() - count[0] * i) > 0; i++) {
    if (((int)(b).size() - count[0] * i) % count[1] == 0) {
      ll j = ((int)(b).size() - count[0] * i) / count[1];
      bool ok = true;
      vector<ll> length = {i, j};
      vector<ll> compPos = {j * pos[0], i * pos[1]};
      vector<ll> comp = {hash.hash(j * pos[0], j * pos[0] + length[0]),
                         hash.hash(i * pos[1], i * pos[1] + length[1])};
      if (comp[0] == comp[1] && i == j) continue;
      for (ll c = 0, d = 0; c < (int)(a).size() && ok; c++) {
        ll cur = a[c] - '0';
        ok = hash.hash(d, d + length[cur]) == comp[cur];
        d += length[cur];
      }
      if (ok) res++;
    }
  }
  cout << res << endl;
}

