#include <bits/stdc++.h>
using namespace std;
string S, T;
long long ans, HS[10000002], lt[10000002];
long long geths(long long x, long long y) {
  return (HS[y + 1] - ((HS[x] * lt[y - x + 1]) % 1000000007) + 1000000007) %
         1000000007;
}
void input() { cin >> S >> T; }
void output() { cout << ans; }
signed main() {
  if (fopen("GHour"
            ".inp",
            "r")) {
    freopen(
        "GHour"
        ".inp",
        "r", stdin);
    freopen(
        "GHour"
        ".out",
        "w", stdout);
  }
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  input();
  lt[0] = 1;
  for (long long i = 1; i <= T.size(); i++) {
    lt[i] = (lt[i - 1] * 29) % 1000000007;
  }
  HS[0] = 0;
  for (long long i = 0; i < T.size(); i++) {
    HS[i + 1] =
        (((HS[i] * 29) % 1000000007) + (long long)T[i] - 96) % 1000000007;
  }
  long long num0 = 0;
  long long num1 = 0;
  for (long long i = 0; i < S.size(); i++) {
    if (S[i] == '0') {
      num0++;
    } else if (S[i] == '1') {
      num1++;
    }
  }
  for (long long i = 1; i <= T.size(); i++) {
    if ((((T.size() - (num0 * i)) % num1) || ((num0 * i) > T.size()))) continue;
    long long x = i;
    long long y = (T.size() - (num0 * i)) / num1;
    if (y == 0) continue;
    long long runS = 0;
    long long runT = 0;
    long long check0 = 0;
    long long check1 = 0;
    long long check = 0;
    long long str0 = 0;
    long long str1 = 0;
    while (runS < S.size() && runT < T.size()) {
      if (S[runS] == '0') {
        if (check0 == 0) {
          str0 = geths(runT, runT + x - 1);
          check0 = 1;
        } else {
          if (geths(runT, runT + x - 1) != str0) {
            check = 1;
            break;
          }
        }
        runT += x;
      } else if (S[runS] == '1') {
        if (check1 == 0) {
          str1 = geths(runT, runT + y - 1);
          check1 = 1;
        } else {
          if (geths(runT, runT + y - 1) != str1) {
            check = 1;
            break;
          }
        }
        runT += y;
      }
      runS++;
    }
    if (check == 1 || str0 == str1) continue;
    ans++;
  }
  output();
  return 0;
}

solution_9:
#include <bits/stdc++.h>
using namespace std;
int prime = 31;
int maxn = 1000000 + 1;
vector<unsigned long long> powers;
vector<int> pos;
vector<unsigned long long> h;
unsigned long long MOD = 1000000000 + 7;
string t;
int m;
unsigned long long calc(int i, int j) {
  if (i == 0) return h[j];
  unsigned long long result = h[j] - h[i - 1];
  if (h[j] < h[i - 1]) result = h[j] + MOD - h[i - 1];
  return result % MOD;
}
int main() {
  powers.push_back(1);
  unsigned long long last = 1;
  for (int i = 1; i <= maxn; ++i) {
    last = (last * prime) % MOD;
    powers.push_back(last);
  }
  std::ios::sync_with_stdio(false);
  string s;
  cin >> s;
  int cnt0 = 0, cnt1 = 0;
  bool revert = false;
  if (s[0] == '1') revert = true;
  int n = s.length();
  pos.resize(n);
  for (int i = 0; i < n; ++i) {
    int k = (s[i] == '0') ? 0 : 1;
    if (revert) k = 1 - k;
    if (k == 0) {
      cnt0++;
      pos[i] = 0;
    } else {
      cnt1++;
      pos[i] = 1;
    }
  }
  cin >> t;
  m = t.length();
  h.resize(m, 0);
  h[0] = t[0] - 'a' + 1;
  for (int i = 1; i < m; ++i) {
    unsigned long long lll = powers[i] * (t[i] - 'a' + 1);
    lll = lll % MOD;
    h[i] = (h[i - 1] + lll) % MOD;
  }
  int total = 0;
  for (int len0 = 1; len0 < m; ++len0) {
    if (((long long)len0 * cnt0) > m) continue;
    int len1 = (m - len0 * cnt0) / cnt1;
    if ((long long)len0 * cnt0 + (long long)len1 * cnt1 != m) continue;
    if (len1 <= 0) continue;
    bool good = true;
    int left = 0;
    unsigned long long h0 = 0, h1 = 0;
    bool first0 = true, first1 = true;
    int p0 = 0, p1 = 0;
    for (int j = 0; j < n; ++j) {
      if (pos[j] == 0) {
        int right = left + len0 - 1;
        unsigned long long hh = calc(left, right);
        if (first0) {
          h0 = hh;
          p0 = right;
          first0 = false;
        } else {
          if (((h0 * powers[right]) % MOD) != ((hh * powers[p0]) % MOD)) {
            good = false;
            break;
          }
        }
        left += len0;
      } else {
        int right = left + len1 - 1;
        unsigned long long hh = calc(left, right);
        if (first1) {
          h1 = hh;
          p1 = right;
          first1 = false;
        } else {
          if (((h1 * powers[right]) % MOD) != ((hh * powers[p1]) % MOD)) {
            good = false;
            break;
          }
        }
        left += len1;
      }
    }
    if (good && ((h1 * powers[p0] % MOD) != (h0 * powers[p1]) % MOD)) {
      total++;
    }
  }
  cout << total << endl;
  return 0;
}

solution_10:
#include <bits/stdc++.h>
#pragma GCC optimize("O3")
using namespace std;
const double EPS = 1e-8;
const int mod = 1e9 + 7;
const int N = 1e6 + 10;
const long long INF = 1e18;
long long power(long long x, long long y) {
  long long t = 1;
  while (y > 0) {
    if (y % 2)
      y -= 1, t = t * x % mod;
    else
      y /= 2, x = x * x % mod;
  }
  return t;
}
char s[N], t[N];
long long pow26[N], thash[N], inv[N];
long long strhash(int st, int end) {
  long long sub;
  if (st)
    sub = thash[st - 1];
  else
    sub = 0;
  return ((thash[end - 1] - (sub * pow26[end - st]) % mod + mod)) % mod;
}
int main() {
  pow26[0] = 1, inv[0] = 1;
  for (int i = 1; i < N; ++i) {
    pow26[i] = (pow26[i - 1] * 27) % mod;
    inv[i] = (power(27, mod - 2) * inv[i - 1]) % mod;
  }
  int firstzero = -1, firstone = -1, numzeroes = 0, numones = 0, n, m,
      pairs = 0;
  long long ans = 0;
  scanf("%s%s", s, t);
  n = strlen(s), m = strlen(t);
  for (int i = 0; i < m; i++) {
    thash[i] = (27 * ans + t[i] - 'a' + 1) % mod;
    ans = thash[i];
  }
  for (int i = 0; i < n; ++i) {
    if (s[i] == '0') {
      if (firstzero == -1) firstzero = i;
      numzeroes++;
    } else {
      if (firstone == -1) firstone = i;
      numones++;
    }
  }
  for (int i = 1; i * numzeroes < m; i++) {
    if ((m - i * numzeroes) % numones == 0) {
      int j = (m - i * numzeroes) / numones;
      long long zhash = strhash(j * firstzero, j * firstzero + i);
      long long ohash = strhash(i * firstone, i * firstone + j);
      if (zhash == ohash) continue;
      long long rethash = 0;
      for (int pos = 0; pos < n; ++pos) {
        if (s[pos] == '0') {
          rethash = (pow26[i] * rethash + zhash);
        } else {
          rethash = (pow26[j] * rethash + ohash);
        }
        if (rethash > mod) rethash %= mod;
      }
      if (rethash == thash[m - 1]) pairs++;
    }
  }
  printf("%d\n", pairs);
  return 0;
}

solution_11:
import java.util.*;

public class CheckTranscription {

    public static class Pair {
        int a, b;

        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }

    public static final int prime = 31;
    public static final int mod = (int) 1E9 + 7;

    public static long mod(long a) {
        if (a < 0) {
            return mod + a % mod;
        }
        return a % mod;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        String s = in.next();
        String t = in.next();

        long[] H = new long[t.length()];
        long[] P = new long[t.length()];
        H[0] = t.charAt(0) - 'a' + 1;
        P[0] = 1;
        for (int i = 1; i < t.length(); i++) {
            P[i] = P[i - 1] * prime;
            P[i] %= mod;
            H[i] = H[i - 1] + (t.charAt(i) - 'a' + 1) * P[i];
            H[i] %= mod;
        }

        int n0 = 0, n1 = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '0') {
                n0++;
            } else {
                n1++;
            }
        }

        List<Pair> pairs = new ArrayList<>();
        for (int i = 1; i * n0 < t.length(); i++) {
            if ((t.length() - i * n0) % n1 == 0) {
                pairs.add(new Pair(i, (t.length() - i * n0) / n1));
            }
        }

        int nPairs = 0;
        for (Pair p : pairs) {
            HashSet<Long> set0 = new HashSet<>();
            HashSet<Long> set1 = new HashSet<>();
            int p0 = 0, p1 = 0, j = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == '0') {
                    p0 = j;
                    j += p.a;
                } else {
                    p1 = j;
                    j += p.b;
                }
            }
            j = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == '0') {
                    if (j == 0) {
                        set0.add((H[p.a - 1] * P[p0]) % mod);
                    } else {
                        set0.add(mod((H[j + p.a - 1] - H[j - 1]) * P[p0 - j]));
                    }
                    j += p.a;
                } else {
                    if (j == 0) {
                        set1.add((H[p.b - 1] * P[p1]) % mod);
                    } else {
                        set1.add(mod((H[j + p.b - 1] - H[j - 1]) *  P[p1 - j]));
                    }
                    j += p.b;
                }
            }
            if (set0.size() == 1 && set1.size() == 1) {
                if ((p0 < p1 && (set0.iterator().next() * P[p1 - p0]) % mod == set1.iterator().next()) ||
                        (p0 >= p1 && set0.iterator().next() == (set1.iterator().next() * P[p0 - p1]) % mod)) {
                    continue;
                }
                nPairs++;
            }
        }

        System.out.println(nPairs);
    }
}

