            if (l1 % ones.size() != 0)
                continue;
            l1 /= ones.size();

            if (1L * zeros.get(0) * l1 + l0 > n)
                continue;
            if (1L * ones.get(0) * l0 + l1 > n)
                continue;

            long val0 = h.getHash(zeros.get(0) * l1, l0);
