import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.util.Random;
import java.math.BigInteger;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskE solver = new TaskE();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskE {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			char[] s = in.next().toCharArray();
			char[] t = in.next().toCharArray();
			int[] before0 = new int[s.length];
			int[] before1 = new int[s.length];
			int num0 = 0;
			int num1 = 0;
			int[] pos0 = new int[s.length];
			int[] pos1 = new int[s.length];
			for (int i = 0; i < s.length; i++) {
				before0[i] = num0;
				before1[i] = num1;
				if (s[i] == '0') {
					pos0[num0++] = i;
				} else {
					pos1[num1++] = i;
				}
			}
			pos0 = Arrays.copyOf(pos0, num0);
			pos1 = Arrays.copyOf(pos1, num1);
			StringHasher hasher = new StringHasher(t);
			int ans = 0;
			outer:
			for (int len0 = 1; len0 < t.length; len0++) {
				int len1 = t.length - len0 * num0;
				if (len1 < 0) {
					break;
				}
				if (len1 % num1 != 0) {
					continue;
				}
				if (len1 == 0) {
					continue;
				}
				len1 /= num1;

				// Either num0 or len0 is small.
				long h0, h1;
				{
					int i;
					i = getPosT(pos0[0], before0, len0, before1, len1);
					h0 = hasher.get(i, i + len0 - 1);
					i = getPosT(pos1[0], before0, len0, before1, len1);
					h1 = hasher.get(i, i + len1 - 1);
				}
				if (len0 == len1 && h0 == h1) {
					continue;
				}

				for (int p : pos0) {
					int i = getPosT(p, before0, len0, before1, len1);
					if (hasher.get(i, i + len0 - 1) != h0) {
						continue outer;
					}
				}
				for (int p : pos1) {
					int i = getPosT(p, before0, len0, before1, len1);
					if (hasher.get(i, i + len1 - 1) != h1) {
						continue outer;
					}
				}
				++ans;
			}
			out.println(ans);
		}

		private int getPosT(int i, int[] before0, int len0, int[] before1, int len1) {
			return before0[i] * len0 + before1[i] * len1;
		}

		class StringHasher {
			Random random = new Random();
			long MOD;
			long X;
			long[] h;
			long[] pow;

			StringHasher(char[] s) {
				MOD = (long) 1e9 + random.nextInt((int) 1e8);
				while (!BigInteger.valueOf(MOD).isProbablePrime(100)) {
					++MOD;
				}
				X = 1 + random.nextInt((int) (MOD - 1));

				int n = s.length;
				h = new long[n + 1];
				pow = new long[n + 1];
				pow[0] = 1;
				for (int i = 1; i < pow.length; i++) {
					pow[i] = X * pow[i - 1] % MOD;
				}

				for (int i = 0; i < n; i++) {
					h[i + 1] = (X * h[i] + s[i]) % MOD;
				}
			}

			long get(int l, int r) {
				long res = (h[r + 1] - pow[r - l + 1] * h[l]) % MOD;
				if (res < 0) {
					res += MOD;
				}
				return res;
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

	}
}

