import java.util.*;
import java.io.*; 
import java.text.*;
//Solution Credits: Taranpreet Singh
public class Main{
    //SOLUTION BEGIN
    void solve(int TC) throws Exception{
        String s = n(), t = n();
        long[] pow = new long[MAX], ipow = new long[MAX];
        pow[0] = 1;
        for(int i = 1; i< MAX; i++)pow[i] = mul(pow[i-1],31);
        for(int i = MAX-1; i>=0; i--)ipow[i] = pow(pow[i], mod-2);
        long[] h = new long[t.length()+1];
        for(int i = t.length()-1; i>=0; i--)
            h[i] = add(mul(h[i+1], 31), t.charAt(i)-'a');
        int c1 = 0, c2= 0, fp = -1;
        for(int i = 0; i< s.length(); i++)if(s.charAt(i)==s.charAt(0))c1++;else {
            c2++;if(fp==-1)fp = i;
        }
        int ans = 0;
        for(int l1 = 1; l1*c1 < t.length(); l1++){
            if((t.length()-l1*c1)%c2!=0)continue;
            int l2 = (t.length()-l1*c1)/c2;
            long H = 0;
            long h1 = hash(0, l1-1, h, pow), h2 = hash(fp*l1, fp*l1+l2-1, h, pow);
            if(l1==l2 && h1==h2)continue;
            for(int i = s.length()-1; i>= 0; i--){
                if(s.charAt(i)==s.charAt(0)){
                    H = add(mul(H, pow[l1]), h1);
                }else H = add(mul(H, pow[l2]), h2);
            }
            if(H==h[0])ans++;
        }
        pn(ans);
    }
    long hash(int l, int r, long[] h, long[] pow){
        return (mod+h[l]-mul(h[r+1], pow[r-l+1]))%mod;
    }
    String print(int len, long h, long base){
        StringBuilder ans = new StringBuilder("");
        while(len-->0){
            ans.append((char)('a'+(h%base)));
//            p((char)('a'+h%base));
            h/=base;
        }
        return ans.toString();
//        pn(ans.reverse().toString());
    }
    long mul(long a, long b){
        if(a>=mod)a%=mod;
        if(b>=mod)b%=mod;
        a*=b;
        if(a>=mod)a%=mod;
        return a;
    }
    long add(long a, long b){
        if(Math.abs(a)>=mod)a%=mod;
        if(a<0)a+=mod;
        if(Math.abs(b)>=mod)b%=mod;
        if(b<0)b+=mod;
        a+=b;
        if(Math.abs(a)>=mod)a%=mod;
        return a;
    }
    long pow(long a, long p){
        long o = 1;
        while(p>0){
            if(p%2==1)o = (a*o)%mod;
            a = (a*a)%mod;
            p>>=1;
        }
        return o;
    }
    //SOLUTION END
    long mod = (long)1e9+7, IINF = (long)5e18;
    final int MAX = (int)1e6+1, INF = (int)2e9, root = 3;
    DecimalFormat df = new DecimalFormat("0.000000000");
    double PI = 3.1415926535897932384626433832792884197169399375105820974944, eps = 1e-8;
    static boolean multipleTC = false, memory = false;
    FastReader in;PrintWriter out;
    void run() throws Exception{
        in = new FastReader();
        out = new PrintWriter(System.out);
        int T = (multipleTC)?ni():1;
        //Solution Credits: Taranpreet Singh
        for(int i = 1; i<= T; i++)solve(i);
        out.flush();
        out.close();
    }
    public static void main(String[] args) throws Exception{
        if(memory)new Thread(null, new Runnable() {public void run(){try{new Main().run();}catch(Exception e){e.printStackTrace();}}}, "1", 1 << 28).start();
        else new Main().run();
    }
    long gcd(long a, long b){return (b==0)?a:gcd(b,a%b);}
    int gcd(int a, int b){return (b==0)?a:gcd(b,a%b);}
    int bit(long n){return (n==0)?0:(1+bit(n&(n-1)));}
    void p(Object o){out.print(o);}
    void pn(Object o){out.println(o);}
    void pni(Object o){out.println(o);out.flush();}
    String n(){return in.next();}
    String nln(){return in.nextLine();}
    int ni(){return Integer.parseInt(in.next());}
    long nl(){return Long.parseLong(in.next());}
    double nd(){return Double.parseDouble(in.next());}

    class FastReader{
        BufferedReader br;
        StringTokenizer st;
        public FastReader(){
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastReader(String s) throws Exception{
            br = new BufferedReader(new FileReader(s));
        }

        String next(){
            while (st == null || !st.hasMoreElements()){
                try{
                    st = new StringTokenizer(br.readLine());
                }catch (IOException  e){
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        String nextLine(){
            String str = "";
            try{    
                str = br.readLine();
            }catch (IOException e){
                e.printStackTrace();
            }   
            return str;
        }
    }
}

