t = list(map(ord,minp()))
h = [0]*(len(t)+1)
pp = [1]*(len(t)+1)
for i in range(len(t)):
	h[i+1] = add(mul(h[i], p), t[i])
	pp[i+1] = mul(pp[i], p)

def cmp(a, b, l):
	if a > b:
		a, b = b, a
	h1 = sub(h[a+l], mul(h[a], pp[l]))
	h2 = sub(h[b+l], mul(h[b], pp[l]))
	return h2 == h1

