mi = (Mi^1)
lt = len(t)
sp = [0,0]
res = 0
for k in range(1,lt//Mv+1):
	l = [0,0]
	x = (lt-k*Mv)//mv
	if x > 0 and x*mv + k*Mv == lt:
		l[Mi] = k
		l[mi] = x
		if idx[0] < idx[1]:
			sp[0] = 0
			sp[1] = idx[1]*l[0]
		else:
			sp[1] = 0
			sp[0] = idx[0]*l[1]
		ok = True
		j = 0
		for i in range(len(s)):
			if not cmp(sp[s[i]], j, l[s[i]]):
				ok = False
				break
			j += l[s[i]]
