#include <bits/stdc++.h>
using namespace std;
long long hs[1000010], aoi[1000010] = {1};
inline long long sana(long long l, long long r) {
  return (hs[r] - hs[l - 1] * aoi[r - l + 1] % 100000007 + 100000007) %
         100000007;
}
inline bool check(long long a, long long b, string &s) {
  long long x, y, i;
  x = y = -1;
  i = 1;
  for (char c : s) {
    if (c == '0') {
      if (x == -1)
        x = sana(i, i + a - 1);
      else if (sana(i, i + a - 1) != x)
        return 0;
      i += a;
    } else {
      if (y == -1)
        y = sana(i, i + b - 1);
      else if (sana(i, i + b - 1) != y)
        return 0;
      i += b;
    }
  }
  return !(x == y);
}
signed main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  long long a, b, i, ans;
  a = b = ans = 0;
  string s, t;
  cin >> s;
  cin >> t;
  for (char c : s) {
    if (c == '0')
      a++;
    else
      b++;
  }
  for (i = 1; i <= t.size(); i++) {
    hs[i] = (hs[i - 1] * 29 + t[i - 1] - 'a' + 1) % 100000007;
    aoi[i] = aoi[i - 1] * 29 % 100000007;
  }
  for (i = 1; a * i < t.size(); i++) {
    if ((t.size() - a * i) % b == 0) {
      if (check(i, (t.size() - a * i) / b, s)) {
        ans++;
      }
    }
  }
  cout << ans << '\n';
  return 0;
}

solution_19:
#include <bits/stdc++.h>
using namespace std;
const int MOD[] = {1000000007, 1000000009};
const int BASE[] = {283, 293};
pair<long long, long long> SFT[1000010 + 1];
void prepare() {
  SFT[0] = make_pair(1, 1);
  for (int i = 1; i <= 1000010; ++i)
    SFT[i] = make_pair((SFT[i - 1].first * BASE[0]) % MOD[0],
                       (SFT[i - 1].second * BASE[1]) % MOD[1]);
}
pair<long long, long long> add(const pair<long long, long long>& a,
                               const pair<long long, long long>& b) {
  pair<long long, long long> ret(a.first + b.first, a.second + b.second);
  if (ret.first >= MOD[0]) ret.first -= MOD[0];
  if (ret.second >= MOD[1]) ret.second -= MOD[1];
  return ret;
}
pair<long long, long long> sub(const pair<long long, long long>& a,
                               const pair<long long, long long>& b) {
  pair<long long, long long> ret(a.first - b.first, a.second - b.second);
  if (ret.first < 0) ret.first += MOD[0];
  if (ret.second < 0) ret.second += MOD[1];
  return ret;
}
pair<long long, long long> shift(const pair<long long, long long>& a, int how) {
  return make_pair((a.first * SFT[how].first) % MOD[0],
                   (a.second * SFT[how].second) % MOD[1]);
}
struct HASH {
  vector<pair<long long, long long> > hc;
  void load(const string& w) {
    hc.resize(((int)(w).size()));
    pair<long long, long long> old(0, 0);
    for (int i = 0; i < ((int)(w).size()); ++i)
      old = add(shift(old, 1), make_pair(w[i], w[i])), hc[i] = old;
  }
  pair<long long, long long> code(int l, int r) {
    if (l > r) return make_pair(0, 0);
    if (l == 0) return hc[r];
    return sub(hc[r], shift(hc[l - 1], r - l + 1));
  }
};
void Write(const pair<long long, long long>& w) {
  cout << w.first << ' ' << w.second << endl;
}
HASH h;
char s[1000010];
char t[1000010];
int n, m;
int lo[1000010], hi[1000010];
bool Same(int a1, int b1, int a2, int b2) {
  if (b1 - a1 != b2 - a2) return false;
  return h.code(a1, b1) == h.code(a2, b2);
}
int main() {
  prepare();
  scanf("%s", &s[0]);
  scanf("%s", &t[0]);
  n = strlen(s);
  m = strlen(t);
  h.load(string(t));
  if (count(s, s + n, '0') < count(s, s + n, '1')) {
    for (int i = 0; i < n; ++i) {
      if (s[i] == '0')
        s[i] = '1';
      else
        s[i] = '0';
    }
  }
  long long c0 = count(s, s + n, '0');
  long long c1 = n - c0;
  int p0, p1;
  for (int i = 0; i < n; ++i)
    if (s[i] == '0')
      p0 = i;
    else
      p1 = i;
  int answer = 0;
  for (long long take0 = 1; take0 <= m; ++take0) {
    if (take0 * c0 > m) break;
    long long left = m - take0 * c0;
    if (left % c1 != 0) continue;
    long long take1 = left / c1;
    if (take1 < 1) continue;
    int pos = 0;
    for (int i = 0; i < n; ++i) {
      int dist;
      if (s[i] == '0')
        dist = take0;
      else
        dist = take1;
      lo[i] = pos;
      hi[i] = pos + dist - 1;
      pos += dist;
    }
    if (!Same(lo[p0], hi[p0], lo[p1], hi[p1])) {
      bool fine = true;
      for (int i = 0; i < n; ++i) {
        if (s[i] == '0' && !Same(lo[i], hi[i], lo[p0], hi[p0])) {
          fine = false;
          break;
        }
        if (s[i] == '1' && !Same(lo[i], hi[i], lo[p1], hi[p1])) {
          fine = false;
          break;
        }
      }
      if (fine) ++answer;
    }
  }
  printf("%d\n", answer);
  return 0;
}

solution_20:
#include <bits/stdc++.h>
using namespace std;
const int MAXL = 1000111;
char s[MAXL];
char t[MAXL];
int n, m;
const int P = 101;
const int MOD1 = 1E9 + 7, MOD2 = 1E9 + 9;
int p1[MAXL], p2[MAXL];
int hash1[MAXL], hash2[MAXL];
void makeMemLim() {
  vector<int> x;
  for (int i = 0; i < 1000000000; i++) {
    x.push_back(i);
  }
}
inline int mod(int x, int md) {
  while (x < 0) x += md;
  while (x >= md) x -= md;
  return x;
}
inline pair<int, int> getNormedHash(int l, int r) {
  if (l < 0 || l >= m) {
    makeMemLim();
  }
  if (r < 0 || r >= m) {
    makeMemLim();
  }
  int st1 = l == 0 ? 0 : hash1[l - 1];
  int st2 = l == 0 ? 0 : hash2[l - 1];
  int fin1 = hash1[r];
  int fin2 = hash2[r];
  int diff1 = mod(fin1 - st1, MOD1);
  int diff2 = mod(fin2 - st2, MOD2);
  int norm1 = (long long)diff1 * p1[MAXL - 10 - l] % MOD1;
  int norm2 = (long long)diff2 * p2[MAXL - 10 - l] % MOD2;
  return {norm1, norm2};
}
int main() {
  p1[0] = p2[0] = 1;
  for (int i = 1; i < MAXL; i++) {
    p1[i] = (long long)p1[i - 1] * P % MOD1;
    p2[i] = (long long)p2[i - 1] * P % MOD2;
  }
  scanf("%s", s);
  scanf("%s", t);
  n = strlen(s);
  m = strlen(t);
  for (int i = 0; i < m; i++) {
    if (i >= MAXL) {
      makeMemLim();
    }
    int prev1;
    if (i == 0) {
      prev1 = 0;
    } else {
      prev1 = hash1[i - 1];
    }
    int prev2;
    if (i == 0) {
      prev2 = 0;
    } else {
      prev2 = hash2[i - 1];
    }
    hash1[i] = ((long long)prev1 + (long long)t[i] * p1[i]) % MOD1;
    hash2[i] = ((long long)prev2 + (long long)t[i] * p2[i]) % MOD2;
  }
  if (m > MAXL - 1) {
    makeMemLim();
  }
  int cnt0 = 0, cnt1 = 0;
  int first0 = 1E9, first1 = 1E9;
  for (int i = 0; i < n; i++) {
    if (s[i] == '0') {
      cnt0++;
      first0 = min(first0, i);
    } else {
      cnt1++;
      first1 = min(first1, i);
    }
  }
  int answer = 0;
  for (int len0 = 1; len0 <= m; len0++) {
    int len1 = (m - (long long)len0 * cnt0) / cnt1;
    if (len1 <= 0) {
      break;
    }
    if ((long long)len0 * cnt0 + (long long)len1 * cnt1 != (long long)m) {
      continue;
    }
    pair<int, int> example0, example1;
    int pos = 0;
    bool ok = true;
    for (int i = 0; i < n; i++) {
      if (pos < 0 || pos >= m) {
        makeMemLim();
      }
      pair<int, int> cur;
      if (s[i] == '0') {
        cur = getNormedHash(pos, pos + len0 - 1);
        if (i == first0) {
          example0 = cur;
        } else {
          if (cur != example0) {
            ok = false;
          }
        }
        pos += len0;
      } else {
        cur = getNormedHash(pos, pos + len1 - 1);
        if (i == first1) {
          example1 = cur;
        } else {
          if (cur != example1) {
            ok = false;
          }
        }
        pos += len1;
      }
    }
    if (example0 != example1 && ok) {
      answer++;
    }
  }
  cout << answer << endl;
  return 0;
}

