#include <bits/stdc++.h>
using namespace std;
const int N = 5e2 + 20;
int n, m, star;
char a[N][N];
int dx[] = {+1, -1, 0, 0};
int dy[] = {0, 0, +1, -1};
bool invalid(int x, int y) {
  return min(x, y) < 0 or x >= n or y >= m or a[x][y] == '.';
}
int main() {
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; i++) scanf(" %s", a[i]);
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) star += (a[i][j] == '*');
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (a[i][j] == '.') continue;
      int cnt = star - 1, dir[4] = {};
      for (int k = 0; k < 4; k++)
        for (int l = 1; not invalid(i + dx[k] * l, j + dy[k] * l);
             l++, dir[k] = 1)
          cnt--;
      if (cnt == 0 and *min_element(dir, dir + 4) == 1)
        return 0 * printf("YES");
    }
  }
  printf("NO");
}

