import java.io.*;
import java.util.*;

public class B {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    static FastReader s = new FastReader();
    static PrintWriter out = new PrintWriter(System.out);

    private static int[] rai(int n) {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextInt();
        }
        return arr;
    }

    private static int[][] rai(int n, int m) {
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = s.nextInt();
            }
        }
        return arr;
    }

    private static long[] ral(int n) {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextLong();
        }
        return arr;
    }

    private static long[][] ral(int n, int m) {
        long[][] arr = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = s.nextLong();
            }
        }
        return arr;
    }

    private static int ri() {
        return s.nextInt();
    }

    private static long rl() {
        return s.nextLong();
    }

    private static String rs() {
        return s.next();
    }

    static int gcd(int a,int b)
    {
        if(b==0)
        {
            return a;
        }
        return gcd(b,a%b);
    }

    static boolean isPrime(int n) {
        //check if n is a multiple of 2
        if (n % 2 == 0) return false;
        //if not, then just check the odds
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            if (n % i == 0)
                return false;
        }
        return true;
    }
    public static void main(String[] args) {
        StringBuilder ans = new StringBuilder();
//        int t = ri();
        int t=1;
        while (t-- > 0)
        {
            int n = ri(), m = ri();
            char[][] map = new char[n][m];
            for(int i=0;i<n;i++)
            {
                map[i]=rs().toCharArray();
            }
            int argr = -1;
            {
                int max = 0;
                for(int i = 0;i < n;i++) {
                    int f = 0;
                    for(int j = 0;j < m;j++) {
                        if(map[i][j] == '*') {
                            f++;
                        }
                    }
                    if(f > max) {
                        max = f;
                        argr = i;
                    }
                }
            }
            int argc = -1;
            {
                int max = 0;
                for(int i = 0;i < m;i++) {
                    int f = 0;
                    for(int j = 0;j < n;j++) {
                        if(map[j][i] == '*') {
                            f++;
                        }
                    }
                    if(f > max) {
                        max = f;
                        argc = i;
                    }
                }
            }
            if(argr == -1) {
                out.println("NO");
                out.flush();
                return;
            }
            if(map[argr][argc] != '*') {
                out.println("NO");
                out.flush();
                return;
            }
            map[argr][argc] = '@';

            int[] dr = { 1, 0, -1, 0 };
            int[] dc = { 0, 1, 0, -1 };
            for(int k = 0;k < 4;k++) {
                int h = 0;
                for(int r = argr + dr[k], c = argc + dc[k];r >= 0 && r < n && c >= 0 && c < m;r += dr[k], c += dc[k]) {
                    if(map[r][c] == '*') {
                        map[r][c] = '@';
                        h++;
                    }else {
                        break;
                    }
                }
                if(h == 0) {
                    out.println("NO");
                    out.flush();
                    return;
                }
            }
            for(int i = 0;i < n;i++) {
                for(int j = 0;j < m;j++) {
                    if(map[i][j] == '*') {
                        out.println("NO");
                        out.flush();
                        return;
                    }
                }
            }
            out.println("YES");
        }

//        out.print(ans.toString());
        out.flush();

    }

}

