int main() {
  int r, c, i, j, ansr, ansc;
  bool yes = false;
  cin >> r >> c;
  char s[r + 1][c + 1];
  for (i = 0; i < r; i++) scanf("%s", s[i]);
  for (i = 1; i < r - 1; i++) {
    for (j = 1; j < c - 1; j++) {
      if (s[i][j] == '*' and s[i][j + 1] == '*' and s[i][j - 1] == '*' and
          s[i - 1][j] == '*' and s[i + 1][j] == '*') {
        ansr = i, ansc = j;
        yes = true;
        break;
      }
    }
  }
  if (yes == false) {
    cout << "NO" << endl;
    exit(0);
  }
  for (i = ansc; i < c; i++) {
    if (s[ansr][i] == '*')
      s[ansr][i] = '.';
    else
      break;
  }
  for (i = ansc - 1; i >= 0; i--) {
    if (s[ansr][i] == '*')
      s[ansr][i] = '.';
    else
      break;
  }
  for (i = ansr + 1; i < r; i++) {
    if (s[i][ansc] == '*')
      s[i][ansc] = '.';
    else
      break;
  }
  for (i = ansr - 1; i >= 0; i--) {
    if (s[i][ansc] == '*')
      s[i][ansc] = '.';
    else
      break;
  }
  for (i = 0; i < r; i++) {
    for (j = 0; j < c; j++) {
      if (s[i][j] == '*') {
        cout << "NO" << endl;
        exit(0);
      }
    }
  }
  cout << "YES" << endl;
}

