import java.util.*;
import java.io.*;

public class Main{
     public static void main(String []args){
         Scanner sc=new Scanner(System.in);
         int h,w;
         h=sc.nextInt();
         w=sc.nextInt();
         sc.nextLine();
         int total=0;
         int[][] arr=new int[h][w];
         for(int i=0;i<h;i++){
             String s=sc.nextLine();
             for(int j=0;j<w;j++){
                 if(Character.toString(s.charAt(j)).equals("*")){
                     arr[i][j]=1;
                     total++;
                 }
                 else{
                     arr[i][j]=0;
                 }
             }
         }
         int row=-1,col=-1;
         for(int i=1;i<h-1;i++){
             for(int j=1;j<w-1;j++){
                 if(arr[i][j]==1){
                     if(arr[i-1][j]==1 && arr[i+1][j]==1 &&
                     arr[i][j+1]==1 && arr[i][j-1]==1){
                         row=i;
                         col=j;
                         break;
                     }
                 }
             }
         }
         int count=0;
        if(row!=-1 && col!=-1){
            boolean started=false,istheregap=false,fromback=false;
            for(int i=0;i<w;i++){
                if(arr[row][i]==1){
                    started=true;
                    if(fromback){ istheregap=true; break;}
                    count++;
                }
                else{
                    if(started) fromback=true;
                }
            }
            if(istheregap){
                System.out.println("NO");
            }
            else{
                started=false; istheregap=false; fromback=false;
                for(int i=0;i<h;i++){
                    if(arr[i][col]==1){
                        started=true;
                        count++;
                        if(fromback){istheregap=true; break;}
                    }
                    else{
                        if(started) fromback=true;
                    }
                }

            if(istheregap || count-1!=total){
                System.out.println("NO");
            }
            else{
                System.out.println("YES");
            }
            }
        }
        else{
            System.out.println("NO");
        }
     }
}

