H, W = map(int, input().split())
TABLE = [['' for i in range(W)] for j in range(H)]


for i in range(H):
    TABLE[i] = list(input())

def find_center():
    global stars_in_common
    for i in range(H):
        for j in range(W):
            if TABLE[i][j] == '*':
                stars_in_common += 1
                if (i == 0) or (j == 0) or (i + 1 == H) or (j + 1 == W):
                    continue
                if (TABLE[i][j - 1] != '*') or (TABLE[i + 1][j] != '*') or (TABLE[i - 1][j] != '*') or (TABLE[i][j + 1] != '*'):
                    continue
                centers.append({'x': j, 'y': i})


def count_stars():
    stars_in_cross = 1
    x = centers[0]['x'] - 1
    while (TABLE[centers[0]['y']][x] == "*")and (x >= 0) and (x < W):
        x -= 1
        stars_in_cross += 1
        if x < 0 or x == W:
            break

    x = centers[0]['x'] + 1
    while (TABLE[centers[0]['y']][x] == "*")and (x >= 0) and (x < W):
        x += 1
        stars_in_cross += 1
        if x < 0 or x == W:
            break

    y = centers[0]['y'] - 1
    while (TABLE[y][centers[0]['x']] == "*") and (y >= 0) and (y < H):
        y -= 1
        stars_in_cross += 1
        if y < 0 or y == H:
            break

    y = centers[0]['y'] + 1
    while (TABLE[y][centers[0]['x']] == "*") and (y >= 0) and (y < H):
        y += 1
        stars_in_cross += 1
        if y < 0 or y == H:
            break
    return stars_in_cross


find_center()
if (len(centers) != 1):
    print('NO')

elif (count_stars() != stars_in_common):
    print('NO')
else:
    print('YES')

