def dfs(i, j, lst):
    used[i][j] = True
    if mp[i][j] == '*':
        flags[i][j] = 1
    if i > 0 and (not used[i - 1][j]) and lst[0] > 0 and mp[i - 1][j] == '*':
        dfs(i - 1, j, [1, 0, 0, 0])
    if i + 1 < n and (not used[i + 1][j]) and lst[1] > 0 and mp[i + 1][j] == '*':
        dfs(i + 1, j, [0, 1, 0, 0])
    if j > 0 and (not used[i][j - 1]) and lst[2] > 0 and mp[i][j - 1] == '*':
        dfs(i, j - 1, [0, 0, 1, 0])
    if j + 1 < m and (not used[i][j + 1]) and lst[3] > 0 and mp[i][j + 1] == '*':
        dfs(i, j + 1, [0, 0, 0, 1])

n, m = map(int, input().split())
