        if (mp[i][j] == mp[i + 1][j] == mp[i - 1][j]
            == mp[i][j + 1] == mp[i][j - 1] == '*') and ans == 0:
            dfs(i, j, [1, 1, 1, 1])
            ans = 1
end = (ans > 0)
for i in range(n):
    for j in range(m):
        if flags[i][j] == 0 and mp[i][j] == '*':
            end = False
if end:
    print("YES")
else:
    print('NO')

