def check_matrix(matrix):
    four_neighbors = 0
    three_neighbors = 0
    one_neighbor = 0
    no_neighbors = 0
    eles = 0
    for i in range(1, filas + 1):
        for j in range(1, cols + 1):
            if matrix[i][j]:
                # Sin elementos de la orilla
                vecinos = matrix[i - 1][j] + matrix[i + 1][j]
                vecinos += matrix[i][j - 1] + matrix[i][j + 1]
                if (matrix[i - 1][j] and matrix[i][j - 1]) or (
                        matrix[i - 1][j] and matrix[i][j + 1]) or (
                        matrix[i + 1][j] and matrix[i][j - 1]) or (
                        matrix[i + 1][j] and matrix[i][j + 1]):
                    eles += 1
                if vecinos == 4:
                    four_neighbors += 1
                elif vecinos == 3:
                    three_neighbors += 1
                elif vecinos == 1:
                    one_neighbor += 1
                elif vecinos == 0:
                    no_neighbors += 1
            if three_neighbors + no_neighbors >= 1:
                # No puede ser
                return False
    if four_neighbors != 1 or one_neighbor != 4 or eles != 1:
        return False
    return True


if check_matrix(matriz):
    print("YES")
else:
    print("NO")

