#include <bits/stdc++.h>
using namespace std;
const int maxn = 512;
char arr[maxn][maxn];
int a[maxn][maxn];
int main() {
  int n, m;
  while (~scanf("%d%d", &n, &m)) {
    for (int i = 0; i < n; i++) scanf("%s", arr[i]);
    int t1 = 0, t2 = 0;
    for (int i = 0; i < n; i++) {
      int res = 0;
      for (int j = 0; j < m; j++) res += (arr[i][j] == '*');
      if (res > t1) {
        t1 = res;
        t2 = i;
      }
    }
    int t3 = 0, t4 = 0;
    for (int i = 0; i < m; i++) {
      int res = 0;
      for (int j = 0; j < n; j++) res += (arr[j][i] == '*');
      if (res > t3) {
        t3 = res;
        t4 = i;
      }
    }
    if (arr[t2][t4] == '.') {
      puts("NO");
      continue;
    } else {
      if (t2 + 1 >= n || arr[t2 + 1][t4] == '.' || t2 - 1 < 0 ||
          arr[t2 - 1][t4] == '.' || t4 + 1 >= m || arr[t2][t4 + 1] == '.' ||
          t4 - 1 < 0 || arr[t2][t4 - 1] == '.') {
        puts("NO");
        continue;
      }
      memset(a, 0, sizeof a);
      a[t2][t4] = 1;
      for (int i = 1; t4 + i < m && arr[t2][t4 + i] == '*'; i++)
        a[t2][t4 + i] = 1;
      for (int i = 1; t4 - i >= 0 && arr[t2][t4 - i] == '*'; i++)
        a[t2][t4 - i] = 1;
      for (int i = 1; t2 + i < n && arr[t2 + i][t4] == '*'; i++)
        a[t2 + i][t4] = 1;
      for (int i = 1; t2 - i >= 0 && arr[t2 - i][t4] == '*'; i++)
        a[t2 - i][t4] = 1;
      int flg = 0;
      for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
          if (arr[i][j] == '*' && a[i][j] == 0) flg = 1;
        }
      puts(flg ? "NO" : "YES");
    }
  }
  return 0;
}

