#include <bits/stdc++.h>
using namespace std;
const int inf = 0x3f3f3f3f;
int mod = 1000000007;
bool remender(long long a, long long b) { return a % b; }
int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
int n, m;
bool check(int i, int j) { return (i > -1 && j > -1 && i < n && j < m); }
void solve() {
  cin >> n >> m;
  char arr[n][m];
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) cin >> arr[i][j];
  }
  int cnt = 0, x, y;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (arr[i][j] == '*') {
        int s = 0;
        for (int k = 0; k < 4; k++) {
          if (check(i + dx[k], j + dy[k]) && arr[i + dx[k]][j + dy[k]] == '*') {
            s++;
          }
        }
        if (s == 0) {
          cout << "NO\n";
          return;
        }
        if (s == 3) {
          cout << "NO\n";
          return;
        }
        if (s == 4) {
          cnt++;
          x = i;
          y = j;
        }
      }
    }
  }
  if (cnt != 1) {
    cout << "NO\n";
    return;
  }
  bool vis[n][m];
  memset(vis, 0, sizeof vis);
  int i = x;
  while (i > -1 && arr[i][y] == '*') {
    vis[i][y] = 1;
    i--;
  }
  i = x;
  while (i < n && arr[i][y] == '*') {
    vis[i][y] = 1;
    i++;
  }
  int j = y;
  while (j > -1 && arr[x][j] == '*') {
    vis[x][j] = 1;
    j--;
  }
  j = y;
  while (j < m && arr[x][j] == '*') {
    vis[x][j] = 1;
    j++;
  }
  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      if (!vis[i][j] && arr[i][j] == '*') {
        cout << "NO\n";
        return;
      }
    }
  }
  cout << "YES\n";
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  solve();
  return 0;
}

