char s[300001];
int main() {
  int n, m;
  cin >> n >> m;
  scanf("%s", s);
  int ans = 0;
  for (int i = 0; i < n; i++) {
    if (s[i] == '.' && s[i - 1] == '.') ans++;
  }
  for (int i = 0; i < m; i++) {
    int p;
    char c;
    cin >> p >> c;
    p--;
    if (s[p] == '.' && c != '.') {
      s[p] = c;
      if (s[p - 1] == '.') ans--;
      if (s[p + 1] == '.') ans--;
      cout << ans << endl;
      continue;
    }
    if (s[p] != '.' && c != '.') {
      s[p] = c;
      cout << ans << endl;
      continue;
    }
    if (s[p] != '.' && c == '.') {
      s[p] = c;
      if (s[p - 1] == '.') ans++;
      if (s[p + 1] == '.') ans++;
      cout << ans << endl;
      continue;
    }
    cout << ans << endl;
  }
  return 0;
}

