public class c1 {
	public static void main(String[] args) throws FileNotFoundException {
		Scanner in = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int n = in.nextInt();
		int m = in.nextInt();

		String s = in.next();
		char s1[] = new char[n];

		int ans = 0;

		for (int i = 0; i < n; i++) {
			s1[i] = s.charAt(i);
		}

		for (int i = 0; i < n - 1; i++) {
			if (s.charAt(i) == '.' && s.charAt(i + 1) == '.') {
				ans++;
			}
		}

		for (int i = 0; i < m; i++) {
			int x = in.nextInt() - 1;

			char q = in.next().charAt(0);

			if (q != s1[x]) {
				if (q == '.') {
					if (x >= 1 && s1[x - 1] == '.'){
						ans++;
					}
					if (x <= n - 2 && s1[x + 1] == '.'){
						ans++;
					}
				} else {
					if (s1[x] == '.'){
						if (x >= 1 && s1[x - 1] == '.'){
							ans--;
						}
						if (x <= n - 2 && s1[x + 1] == '.'){
							ans--;
						}
					}
				}
			}

			s1[x] = q;

			out.println(ans);
		}
		out.close();
	}
}

