import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Map;
import java.util.TreeSet;

public class Main {

    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        InputReader inputReader = new InputReader(in);
        PrintWriter out = new PrintWriter(System.out);

        int n = inputReader.getNextInt();
        int m = inputReader.getNextInt();
        String str = inputReader.getNextToken();

        TreeSet<Integer> occupied = new TreeSet<>();
        occupied.add(0);
        occupied.add(n+1);
        int current = 0;
        int solution = 0;

        for(int i = 0; i < str.length(); i++) {
            if(str.charAt(i) != '.') {
                occupied.add(i+1);
                solution = solution + Math.max(0, current-1);
                current = 0;
            } else {
                current++;
            }
        }
        solution = solution + Math.max(0, current-1);

        for(int i = 0; i < m; i++) {
            int pos = inputReader.getNextInt();
            String value = inputReader.getNextToken();

            Integer lower = occupied.lower(pos);
            Integer upper = occupied.higher(pos);

            if(value.equals(".")) {
                if(occupied.contains(pos)) {
                    solution = solution - Math.max(0, pos - lower - 2);
                    solution = solution - Math.max(0, upper - pos - 2);
                    solution = solution + Math.max(0, upper - lower - 2);
                }
                occupied.remove(pos);
            } else {
                if(occupied.contains(pos) == false) {
                    solution = solution - Math.max(0, upper - lower - 2);
                    solution = solution + Math.max(0, pos - lower - 2);
                    solution = solution + Math.max(0, upper - pos - 2);
                }
                occupied.add(pos);
            }

            out.println(solution);
        }

        in.close();
        out.close();
    }

    public static long getPairsFromMap(Map<Integer, Integer> map) {
        long res = 0;
        for(Map.Entry<Integer, Integer> entry: map.entrySet()) {
            res = res + (1L * entry.getValue() * (entry.getValue()-1)) / 2L;
        }

        return res;
    }

    public static class InputReader {

        static final String SEPARATOR = " ";

        String[] split;
        int head = 0;
        BufferedReader in;

        public InputReader(BufferedReader in) {
            this.in = in;
        }

        private void fillBuffer() throws IOException {
            if(split == null || head >= split.length) {
                head = 0;
                split = in.readLine().split(SEPARATOR);
            }
        }

        public String getNextToken() throws IOException {
            fillBuffer();
            return split[head++];

        }

        public int getNextInt() throws IOException {
            return Integer.parseInt(getNextToken());
        }

        public long getNextLong() throws IOException {
            return Long.parseLong(getNextToken());
        }
    }

}

