    for (j = x[2]; j <= 300; ++j) {
      u = i - y[2], v = y[1] - j;
      temp = (i - x[1]) * h[1] + (j - x[2]) * h[2];
      if (v > 0) {
        hp = x[0];
        a = (y[0] - 1) / u + 1, b = (x[0] - 1) / v + 1;
