//package codeforces;

import java.util.Scanner;

public class Solution {

	private static int coins;

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int hero_hp = sc.nextInt();
		int hero_atk = sc.nextInt();
		int hero_def = sc.nextInt();

		int monster_hp = sc.nextInt();
		int monster_atk = sc.nextInt();
		int monster_def = sc.nextInt();

		int h = sc.nextInt();
		int a = sc.nextInt();
		int d = sc.nextInt();

		coins = Integer.MAX_VALUE;

		for (int i = 0; i <= 200; i++) {
			for (int j = 0; j <= 200; j++) {
				int hero_hp_loss = Math.max(0, monster_atk - hero_def - j);
				int monster_hp_loss = Math.max(0, hero_atk + i - monster_def);
				if (monster_hp_loss > 0) {
					int time = (monster_hp + monster_hp_loss -1)/ monster_hp_loss;
					int remaining_hero_hp = Math.max(0,(hero_hp_loss)*time - hero_hp+1);
					int tmp_coins = remaining_hero_hp*h + i*a + j*d; 
					if (coins > tmp_coins)
						coins = tmp_coins;

				}
			}
		}

		System.out.println(coins);

	}



}

