#include <bits/stdc++.h>
using namespace std;
void solve() {
  long long MH, MA, MD, H, A, D, h, a, d;
  cin >> H >> A >> D >> MH >> MA >> MD >> h >> a >> d;
  long long mn = 1e9;
  for (int i = A; i <= 300; i++) {
    for (int j = D; j <= 300; j++) {
      if (i <= MD) continue;
      if (MA <= j) {
        mn = min(mn, ((j - D) * d) + (i - A) * a);
        continue;
      }
      long long tA = (i - MD);
      long long sec = MH / tA + (MH % tA != 0);
      long long mA = (MA - j);
      long long add = mA * sec + 1 - H;
      long long ans;
      if (add < 0)
        ans = ((i - A) * a) + ((j - D) * d);
      else
        ans = (add * h) + ((i - A) * a) + ((j - D) * d);
      mn = min(mn, ans);
    }
  }
  cout << mn;
}
int main() {
  int t = 1;
  while (t--) {
    solve();
    cout << "\n";
  }
  return 0;
}

