#include <bits/stdc++.h>
using namespace std;
int MH, MA, MD;
int priceH, priceA, priceD;
int dp[351][351];
int YH, YA, YD;
int solve(int attack, int defense) {
  if (defense >= 300 || attack >= 300) return (1 << 30);
  if (dp[attack][defense] != -1) return dp[attack][defense];
  int ans = (1 << 30);
  int AY = max(0, MA - defense);
  int AM = max(0, attack - MD);
  if (AM == 0)
    return dp[attack][defense] = min(solve(attack, defense + 1) + priceD,
                                     solve(attack + 1, defense) + priceA);
  else {
    if (AY == 0) return 0;
    if (AY != 0) {
      for (int i = 0; i <= 20000; ++i) {
        int healthActual = YH + i;
        if ((healthActual - 1 + AY) / AY > (MH - 1 + AM) / AM) {
          ans = min(ans, i * priceH);
          break;
        }
      }
    }
  }
  ans = min(ans, solve(attack, defense + 1) + priceD);
  ans = min(ans, solve(attack + 1, defense) + priceA);
  return dp[attack][defense] = ans;
}
int main() {
  memset(dp, -1, sizeof(dp));
  cin >> YH >> YA >> YD;
  cin >> MH >> MA >> MD;
  cin >> priceH >> priceA >> priceD;
  cout << solve(YA, YD) << endl;
  return 0;
}

