#include <bits/stdc++.h>
using namespace std;
long long qpow(long long a, long long b) {
  long long res = 1, base = a;
  while (b) {
    if (b % 2) res = res * base;
    base = base * base;
    b /= 2;
  }
  return res;
}
long long powmod(long long a, long long b) {
  long long res = 1, base = a;
  while (b) {
    if (b % 2) res = res * base % 1000000007;
    base = base * base % 1000000007;
    b /= 2;
  }
  return res;
}
void scanf(int &__x) {
  __x = 0;
  char __ch = getchar();
  while (__ch == ' ' || __ch == '\n') __ch = getchar();
  while (__ch >= '0' && __ch <= '9')
    __x = __x * 10 + __ch - '0', __ch = getchar();
}
long long gcd(long long _a, long long _b) {
  if (!_b)
    return _a;
  else
    return gcd(_b, _a % _b);
}
int h1, a1, d1;
int h2, a2, d2;
int t1, t2, t3;
void read(void) {
  scanf("%d%d%d", &h1, &a1, &d1);
  scanf("%d%d%d", &h2, &a2, &d2);
  scanf("%d%d%d", &t1, &t2, &t3);
}
void work(void) {
  int ans = 0x3f3f3f3f;
  for (int i = 0; i <= 200; i++) {
    for (int j = 0; j <= 200; j++) {
      if (a1 + i <= d2) continue;
      if (a2 <= d1 + j) {
        ans = min(ans, t2 * i + t3 * j);
        continue;
      } else {
        int t = h2 / (a1 + i - d2);
        if (h2 % (a1 + i - d2) != 0) t++;
        t = t * (a2 - d1 - j);
        if (t < h1)
          ans = min(ans, t2 * i + t3 * j);
        else
          ans = min(ans, t2 * i + t3 * j + (t - h1 + 1) * t1);
      }
    }
  }
  printf("%d\n", ans);
}
int main(void) {
  read();
  work();
  return 0;
}

