		long atkm = in.nextInt();
		long defm = in.nextInt();
		long h = in.nextInt();
		long a = in.nextInt();
		long d = in.nextInt();
		long min = Long.MAX_VALUE;
		for(int def = 0; true;def++){
			long dps = Math.max(0, atkm-defy-def);
			for(int atk = 0; true;atk++){
				long mydps = Math.max(0, atky+atk-defm);
				if(mydps==0)continue;
				long secondsToKill = (hpm+mydps-1)/mydps;
				long hpneeded = Math.max(0,(secondsToKill)*dps+1-hpy);
				long cost = h*hpneeded+a*atk+d*def;
				if(cost<min){
					min = cost;
				}
				if(secondsToKill==1)break;
			}
			if(dps==0)break;
		}
		System.out.println(min);
	}
}

