import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigInteger;
import java.util.StringTokenizer;

/**
 * Created by yujiahao on 7/13/16.
 */
public class cf_278_c {
    private FastScanner in;
    private PrintWriter out;

    public void solve() throws IOException {
        int[] hp = new int[2], atk = new int[2], def = new int[2];
        int h, a, d;

        hp[0] = in.nextInt();
        atk[0] = in.nextInt();
        def[0] = in.nextInt();

        hp[1] = in.nextInt();
        atk[1] = in.nextInt();
        def[1] = in.nextInt();

        h = in.nextInt();
        a = in.nextInt();
        d = in.nextInt();

        int ans = Integer.MAX_VALUE;
        for (int i = Math.max(atk[0], def[1] + 1); i <= 200; i++) {
            for (int j = def[0]; j <= 100; j++) {
                int time_beat = (hp[1] + i - def[1] - 1) / (i - def[1]);
                int rate = Math.max(atk[1] - j, 0);
                if (rate == 0) {
                    ans = Math.min(ans, a * (i - atk[0]) + d * (j - def[0]));
                } else {
                    int min_hp = time_beat * rate + 1;
                    int k = Math.max(0, min_hp - hp[0]);
                    ans = Math.min(ans, a * (i - atk[0]) + d * (j - def[0]) + h * k);
                }
            }
        }
        out.println(ans);
    }


    public void run() {
        try {
            in = new FastScanner();
            out = new PrintWriter(System.out);
            solve();
            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public BigInteger nextBigInteger() { return new BigInteger(next());}

    }

    public static void main(String[] arg) {
        new cf_278_c().run();
    }
}

