#include <bits/stdc++.h>
using namespace std;
const int inf = 0x7fffffff;
int s[3][3];
int h, a, d, ans;
void judge(int cost, int aa, int dd) {
  s[2][1] = s[0][1] + aa;
  s[2][2] = s[0][2] + dd;
  if (s[2][1] <= s[1][2]) return;
  int u1 = s[2][1] - s[1][2];
  u1 = s[1][0] / u1 + (s[1][0] % u1 ? 1 : 0);
  int d2 = s[1][1] - s[2][2];
  if (d2 <= 0) {
    ans = min(ans, cost);
    return;
  }
  int hh = u1 * d2 + 1;
  ans = min(ans, cost + h * max(0, hh - s[0][0]));
}
int main() {
  for (int i = 0; i < 2; i++) {
    for (int j = 0; j < 3; j++) scanf("%d", &s[i][j]);
  }
  scanf("%d %d %d", &h, &a, &d);
  ans = inf;
  int A, B, C;
  for (int i = 0; i <= 200; i++) {
    A = i * a;
    if (A >= ans) break;
    for (int j = 0; j <= 100; j++) {
      B = A + j * d;
      if (B >= ans) break;
      judge(B, i, j);
    }
  }
  printf("%d\n", ans);
  return 0;
}

