#include <bits/stdc++.h>
using namespace std;
int ay, dy, hpy, am, dm, hpm;
int ap, dp, hpp;
int main() {
  scanf("%d%d%d%d%d%d%d%d%d", &hpy, &ay, &dy, &hpm, &am, &dm, &hpp, &ap, &dp);
  int hhm, hhy, ddy, aay, tot = 0, mini = 1e9;
  for (int i = 0; i <= 5000; i++) {
    for (int j = 0; j <= 5000; j++) {
      hhm = hpm;
      hhy = hpy;
      aay = ay + j, ddy = dy + i;
      tot = i * dp + j * ap;
      if (aay - dm < 1)
        continue;
      else {
        int stps = hhm / (aay - dm);
        hhm -= stps * (aay - dm);
        if (hhm) {
          stps++;
          hhm -= (aay - dm);
        }
        hhy -= stps * (am - ddy);
      }
      if (hhy < 1) tot += (abs(hhy) + 1) * hpp;
      if (hhm < 1 && tot < mini) {
        mini = tot;
      }
    }
  }
  printf("%d\n", mini);
  return 0;
}

solution_19:
import java.util.Scanner;

/**
 * Created by mostafa on 10/7/17.
 */
public class FightMonster {
    static int inf = (int) 1e9;

    static boolean canwin(int hpy, int atky, int defy, int hpm, int atkm, int defm) {
        if(atky <= defm)
            return false;
        if(atkm <= defy)
            return true;

        int dmg1 = atky - defm;
        int moves1 = (hpm + dmg1 - 1) / dmg1;

        int dmg2 = atkm - defy;
        int moves2 = (hpy + dmg2 - 1) / dmg2;

        return moves1 < moves2;
    }

    static int hp(int hpy, int atky, int defy, int hpm, int atkm, int defm) {
        if(atky <= defm)
            return inf;
        if(atkm <= defy)
            return 0;

        int ans = inf;
        int low = 0, high = inf;
        while(low <= high) {
            int mid = (low + high) / 2;
            if (canwin(hpy + mid, atky, defy, hpm, atkm, defm)) {
                ans = mid;
                high = mid - 1;
            }
            else
                low = mid + 1;
        }

        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int hpy = sc.nextInt(), atky = sc.nextInt(), defy = sc.nextInt();
        int hpm = sc.nextInt(), atkm = sc.nextInt(), defm = sc.nextInt();
        int h = sc.nextInt(), a = sc.nextInt(), d = sc.nextInt();
        int ans = (int) 1e9;

        for(int atk = 0; atk <= 7000; atk++)
            for(int def = 0; def <= 7000; def++) {
                int hp = hp(hpy, atky + atk, defy + def, hpm, atkm, defm);
                if(hp == inf)
                    continue;
                ans = Math.min(ans, atk * a + def * d + hp * h);
            }
        System.out.println(ans);
    }
}

