import java.io.*;
import java.util.*;
import java.math.*;

public class Education_89_2
{
	InputReader in;PrintWriter pw;

	void solve(int test) throws Exception
	{
		int n=ni(),k=ni(),f=0,prev=0,ans=0,count=0;
		char arr[] = nln().toCharArray();

		if(n==1 && arr[0]=='0')
		{
			pn("1");
			return;
		}

		int i=0;
		for(i=0;i<n;i++)
		{
			if(arr[i]=='1')
			{
				//pn("A"+i);
				i += (k);
				f=0;
				prev=i;
				count=0;
				continue;
			}
			if(f==1 && arr[i]=='0')
			{
				//pn("C"+i);
				count++;
				if(count==k)
				{
					ans++;
					f=0;
					prev=i;
					count=0;
				}
				continue;
			}
			if(f==0 && arr[i]=='0')
			{
				//pn("D"+i);
				f=1;
				continue;
			}
		}
		if(i<=n && f==1) ans++;
		pn(ans);
	}
	void run() throws Exception 
	{
		in = new InputReader();
		pw = new PrintWriter(System.out);
		int test = ni();
		while(test--!=0){solve(test);}
		pw.close();
	}
	public static void main(String[] args) throws Exception
	{
		new Education_89_2().run();
	}
	void p(Object o){pw.print(o);}
	void pn(Object o){pw.println(o);}
	void pn(){pw.println();}
	void spn(Object o){System.out.println(o);};
	String nln() throws Exception {return in.nextLine();}
	int ni() throws Exception {return Integer.parseInt(in.next());}
	double nd() throws Exception {return Double.parseDouble(in.next());}
	long nl() throws Exception {return Long.parseLong(in.next());}
	class InputReader
	{
		BufferedReader br;
		StringTokenizer st;

		public InputReader()
		{
			br = new BufferedReader(new InputStreamReader(System.in));
		}
		public InputReader(String s) throws IOException
		{
			br = new BufferedReader(new FileReader(s));
		}

		String next() throws Exception
		{
			if(st==null || !st.hasMoreElements())
			{
				try
				{
					st = new StringTokenizer(br.readLine());
				}
				catch(IOException e)
				{
					throw new Exception(e.toString());
				}
			}
			return st.nextToken();
		}

		String nextLine() throws Exception
		{
			String str = "";
			try
			{
				str = br.readLine();
			}
			catch(IOException e)
			{
				throw new Exception(e.toString());
			}
			return str;
		}
	}
}

