def answer(n,k,s):
    if s=="0"*n:
        if n==k+2:
            return 2
        t=n//(k+1)
        if n%(k+1)==0:
            return t
        else:
            return t+1
    first1=0
    for i in range(n):
        if s[i]=="1":
            first1=i
            break

    last1=0
    for i in range(n-1,-1,-1):
        if s[i]=="1":
            last1=i
            break
    count=(first1)//(k+1)+(n-1-last1)//(k+1)
    c=0
    for i in range(first1+1,last1+1):
        if s[i]=="0":
            c+=1
        else:
            count+=int((c-k)/(k+1))
            c=0
    return count









