import java.util.*;
import java.lang.*;
import java.io.*;

/* Name of the class has to be "Main" only if the class is public. */
public class sdist
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner in = new Scanner(System.in);
		int t;
		t = in.nextInt();
		while(t-->0){
		    int n,k;
		    n = in.nextInt();
		    k = in.nextInt();
		    String st = in.next();
		    int i=0;
		    int r = -1;
		    int l = -1;
		    int c = 0;
		    int j = 0;
		    char ch = st.charAt(0);
		    if(ch == '1') {
		        l = 0;
		    } else {

		        for(;j<st.length();j++){
		            if(st.charAt(j) == '1') break;
		        }

		        if(j+1>k) {
		            c = c+1;
		            l = 0;
		            if(j == st.length()){
		                int temp = (j-l-1)/(k+1);
		                c = c + temp;
		            } else {
		                int temp = (j-l)/(k+1);
		                int p = (k+1)*temp;
		                 if((p-j)>k){
		                     c = c + temp;
		                } else c = c + temp-1;
		            }
		        }
		        l = j;
		    }
		    j++;
		    while(j<st.length()){
		        for(;j<st.length();j++){
		            if(st.charAt(j) == '1') break;
		        }
		        if((j-l)>(k+1)) {
		            if(j == st.length()){
		                int temp = (j-l-1)/(k+1);
		                c = c + temp;
		            } else {

    		            int temp = (j-l)/(k+1);
    		            int p = (k+1)*temp;
    		            if((p-j)>k){
    		                c = c + temp;
    		            } else c = c + temp-1;
		            }
		        }
		        l = j;
		        j++;
		    }
		    System.out.println(c);

		}
	}
}

