        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    static <T> void printArray(T[] arr) {
        for (T x : arr)
            print(x, " ");
        printn("");
    }

    static <T> void print(T s, String sep) {
        System.out.print(s + sep);
    }

    static <T> void printn(T s) {
        System.out.println(s);
    }

    static Long[] inputArrL(int n, FastReader fr) {
        Long[] arr = new Long[n];
        for (int i = 0; i < n; i++)
            arr[i] = fr.nextLong();
        return arr;
    }

    static Integer[] inputArr(int n, FastReader fr) {
        Integer[] arr = new Integer[n];
        for (int i = 0; i < n; i++)
            arr[i] = fr.nextInt();
        return arr;
    }

    static int max(int... args) {
        int max = Integer.MIN_VALUE;
        for (int x : args) {
            max = Math.max(x, max);
        }
        return max;
    }

    static int min(int... args) {
        int min = Integer.MAX_VALUE;
        for (int x : args) {
            min = Math.min(x, min);
        }
        return min;
    }

    static int lenDigit(int d) {
        if (d == 0)
            return 1;
        int l = 0;
        while (d != 0) {
            l++;
            d /= 10;
        }
        return l;
    }

    static StringBuilder binOR(String a, String b){
        StringBuilder res = new StringBuilder();
        for(int i=0; i<a.length(); i++) {
            if(a.charAt(i) != b.charAt(i))
                res.append('1');
            else
                res.append('0');
        }
        return res;
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader();
        int len = fr.nextInt();
        String a, b;
        a = fr.nextLine();
        b = fr.nextLine();
        StringBuilder or = binOR(a, b);
        int res = 0;
        for(int i=0; i<len; ){
            if(or.charAt(i) == '1'){
                //there is mismatch between a and b
                if(i <= len-2 && or.charAt(i + 1) == '1'){
                    if(a.charAt(i+1) == b.charAt(i) && a.charAt(i) == b.charAt(i+1)){
                        //swap
                        res += 1;
                        i += 2;
                    }
                    else{
                        res += 1;
                        i += 1;
                    }
                }
                else{
                    res += 1;
                    i += 1;
                }
            }
            else
                i += 1;
        }
        System.out.println(res);
    }
}

