def cost(bit1, bit2):
  return 0 if bit1 == bit2 else 1

def solve(n, a, b):
  dp = (0, cost(a[0], b[0]))

  for i in xrange(1, n):
    approach1 = cost(a[i], b[i]) + dp[-1]
    approach2 = cost(a[i], b[i-1]) + cost(a[i-1], b[i]) + 1 + dp[-2]
    dp = (dp[-1], min(approach1, approach2))

  return dp[-1]


def main():
  n = int(raw_input().strip())
  a = raw_input().strip()
  b = raw_input().strip()
  print solve(n, a, b)


if __name__ == '__main__':
  main()

