using namespace std;
string s, t;
int n, m, f[200009][30], vis[30], l, r, ans, flag, mid;
int main() {
  cin >> n >> s;
  for (int i = 0; i < n; i++) {
    if (!i)
      f[i][s[i] - 'a'] = 1;
    else {
      for (int j = 0; j < 30; j++) {
        if (s[i] - 'a' == j) {
          f[i][j] = f[i - 1][j] + 1;
        } else
          f[i][j] = f[i - 1][j];
      }
    }
  }
  cin >> m;
  for (int i = 0; i < m; i++) {
    cin >> t;
    memset(vis, 0, sizeof(vis));
    for (int j = 0; j < t.size(); j++) {
      vis[t[j] - 'a']++;
    }
    ans = 0;
    l = 0, r = n;
    while (l <= r) {
      mid = (l + r) / 2;
      flag = 1;
      for (int j = 0; j < 30; j++) {
        if (f[mid][j] < vis[j]) {
          flag = 0;
          break;
        }
      }
      if (flag) {
        ans = mid;
        r = mid - 1;
      } else {
        l = mid + 1;
      }
    }
    cout << ans + 1 << endl;
  }
}

solution_18:
#include <bits/stdc++.h>
using namespace std;
long long gcd(long long a, long long b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}
long long lcm(int a, int b) { return (a / gcd(a, b)) * b; }
int mxor(int x, int y) { return (x | y) & (~x | ~y); }
int isprime(long long n) {
  if (n == 1)
    return 0;
  else if (n == 2)
    return 1;
  else {
    bool flag = true;
    for (long long i = 2; i * i < n; i++) {
      if (n % i == 0) {
        flag = false;
        break;
      }
    }
    if (!flag)
      return 0;
    else
      return 1;
  }
}
long long summ(long long n) {
  long long sum = ((n * (n + 1)) / 2);
  return sum;
}
void factors(long long n, vector<long long>& v) {
  for (int i = 2; i * i <= n; i++) {
    if (n % i == 0) {
      v.push_back(i);
      if (i != n / i) {
        v.push_back(n / i);
      }
    }
  }
  v.push_back(n);
}
long long digitsum(long long n) {
  long long sum = 0;
  while (n > 0) {
    sum += n % 10;
    n /= 10;
  }
  return sum;
}
long long tt(long long n) {
  int i = 1;
  while (pow(2, i - 1) < n) {
    i++;
  }
  if (pow(2, i) == n)
    return i;
  else
    return i;
}
int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  int n;
  cin >> n;
  string s;
  cin >> s;
  vector<int> p[26];
  for (int i = 0; i < s.length(); i++) {
    p[s[i] - 'a'].push_back(i + 1);
  }
  int t;
  cin >> t;
  while (t--) {
    string ss;
    cin >> ss;
    vector<int> v(26);
    for (int i = 0; i < ss.length(); i++) {
      v[ss[i] - 'a']++;
    }
    int ans = -1;
    for (int i = 0; i < 26; i++) {
      if (v[i] > 0) ans = max(ans, p[i][v[i] - 1]);
    }
    cout << ans << "\n";
  }
}

