        res[1] = 1;
        res[n] = 0;
        for (int i = 2; i < n; i++) {
            res[i] = ((res[i - 1] + 1) * 2 - 1) % 1000000007;
        }

        int cnt = 0;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            if (c[i] == 'a') {
                cnt++;
            } else {
                ans += res[cnt];
                ans %= 1000000007;
            }
        }

        System.out.println(ans);
    }
}

