int getint(string s, int &now) {
  int o = 0;
  for (; now < s.size() && s[now] >= '0' && s[now] <= '9'; now++)
    o = o * 10 + (s[now] - '0');
  return o;
}
int main() {
  int n, m, now = 0;
  bool done = 0;
  queue<long long> q;
  string s;
  getline(cin, s);
  n = getint(s, now);
  m = getint(s, ++now);
  while (getline(cin, s)) {
    now = 5;
    for (int i = 0; i < 5; i++, now++) in[i] = getint(s, now);
    int cnt = 0;
    for (int i = 1; i < in[0]; cnt += days[i++])
      ;
    long long time =
        (cnt + in[1] - 1) * 24 * 3600 + in[2] * 3600 + in[3] * 60 + in[4];
    while (!q.empty() && q.front() + n <= time) q.pop();
    q.push(time);
    if (!done && q.size() == m) {
      for (int i = 0; i < 19; i++) cout << s[i];
      cout << endl;
      done = 1;
    }
  }
  if (!done) cout << -1 << endl;
  return 0;
}

