#include <bits/stdc++.h>
using namespace std;
const long long mod = 1000000007;
int a1[13] = {0, 0, 31, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335};
int main() {
  const int N = 5000001;
  int n, m;
  int mmd, ddd, hh, mm, ss;
  cin >> n >> m;
  string line;
  vector<int> events;
  vector<string> tms;
  getline(cin, line);
  while (getline(cin, line)) {
    if (line == "") break;
    struct tm T;
    sscanf(line.c_str(), "%*d-%d-%d %d:%d:%d %*s", &mmd, &ddd, &hh, &mm, &ss);
    events.push_back(ss + (mm + (hh + (a1[mmd] + ddd) * 24) * 60) * 60);
    tms.push_back(line);
  }
  int ret = -1;
  for (int i = 0; i + m - 1 < events.size(); ++i) {
    int j = i + m - 1;
    if (events[j] - events[i] + 1 <= n) {
      ret = j;
      break;
    }
  }
  if (ret < 0)
    cout << -1 << endl;
  else {
    string fm = "2012-mm-dd hh:mm:ss";
    cout << tms[ret].substr(0, fm.size()) << endl;
  }
  return 0;
}

solution_9:
import java.util.Scanner;
import java.io.OutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 * @author George Marcus
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		Scanner in = new Scanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskF solver = new TaskF();
		solver.solve(1, in, out);
		out.close();
	}
}

class TaskF {
	public void solve(int testNumber, Scanner in, PrintWriter out) {
        int N = in.nextInt();
        int M = in.nextInt();
        in.nextLine();
        ArrayList<Log> logs = new ArrayList<Log>();

        int i = 0;
        while(in.hasNext()) {

            String line = in.nextLine();

            logs.add(new Log(line));
            if(logs.size() >= M) {
                int now = logs.get(i).absSec;
                int then = logs.get(i - M + 1).absSec;
                if(now - then + 1 <= N) {
                    out.println(logs.get(i).time);
                    return;
                }
            }
            i++;
        }

        out.println(-1);
	}

    private class Log {
        private int month;
        private int day;
        private int hour;
        private int min;
        private int sec;
        public int absSec;
        private int[] days = { 0, 31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        public String time;

        public Log(String raw) {
            int startMessage = raw.length() - 1;
            for(; raw.charAt(startMessage) != ':'; startMessage--);

            time = raw.substring(0, startMessage);
            String[] tokens = time.split(" ");

            String[] date = tokens[0].split("-");
            month = Integer.parseInt(date[1]);
            day = Integer.parseInt(date[2]);

            String[] clock = tokens[1].split(":");
            hour = Integer.parseInt(clock[0]);
            min = Integer.parseInt(clock[1]);
            sec = Integer.parseInt(clock[2]);

            absSec = sec + 60 * min + 3600 * hour + 3600 * 24 * day;
            absSec += 3600 * 24 * getAbsDays();
        }

        private int getAbsDays() {
            int ret = 0;

            for(int i = 1; i <= 12; i++)
                if(month > i)
                    ret += days[i];

            return ret;
        }
    }
}

solution_10:
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.io.*;

public class F {
    FastScanner in;
    PrintWriter out;

    class Messages {
        long time;
        String t;
        String message;
        public Messages(long time, String message, String t) {
            super();
            this.time = time;
            this.message = message;
            this.t = t;
        }

    }

    public void solve() throws IOException {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong(); 
        int m = sc.nextInt();
        long [] monthes = {0, 31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30};
        for (int i = 1; i < 12; i++) {
            monthes[i] += monthes[i - 1];
        }
        sc.nextLine();
//      Messages[] messages = new Messages[n];
        ArrayList<Messages> messages = new ArrayList<Messages>();
        while(sc.hasNext()) {
            String line = sc.nextLine();

            long year = Integer.parseInt(line.substring(0, 4));
            int month = Integer.parseInt(line.substring(5, 7)) - 1;
            long day = Integer.parseInt(line.substring(8, 10)) - 1;
            long hour = Integer.parseInt(line.substring(11, 13));
            long minute = Integer.parseInt(line.substring(14, 16));
            long second = Integer.parseInt(line.substring(17, 19));

//          System.err.println(year+ "|" + month + "|" + day + "|" + hour + "|" + minute + "|" + second);
            messages.add( new Messages(monthes[month] * 24 * 60 * 60 + day * 24 * 60 * 60 + hour * 60 * 60 + minute * 60 + second, line.substring(21), line.substring(0, 19)));

        }
        for (int i = 0; i < messages.size() - m + 1; i++) {
//          System.err.println((messages.get(i + m - 1).time.getTimeInMillis() - messages.get(i).time.getTimeInMillis()));
//          System.err.println(n);
//          System.err.println(messages.get(i + m - 1).time + " " + messages.get(i).time + " " + (messages.get(i + m - 1).time - messages.get(i).time ));
            if ((messages.get(i + m - 1).time - messages.get(i).time < n)) {
                out.println(messages.get(i + m - 1).t);
                return;
            }
        }
        out.println(-1);
    }

    public void run() {
        try {
//          in = new FastScanner(System.in);
            out = new PrintWriter(System.out);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            return hasNext() ? st.nextToken() : null;
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        boolean hasNext() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return false;
                }
                st = new StringTokenizer(line);
            }
            return true;
        }

        int nextInt() throws NumberFormatException, IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] arg) {
        new F().run();
    }
}

