solution_14:
#include <bits/stdc++.h>
int n, m;
int Y[1000000], M[1000000], D[1000000], hh[1000000], mm[1000000], ss[1000000];
int f[1000000];
char str[1000000];
int main() {
  scanf("%d%d", &n, &m);
  int t = 0;
  while (scanf("%d-%d-%d%d:%d:%d", &Y[t], &M[t], &D[t], &hh[t], &mm[t],
               &ss[t]) != EOF) {
    gets(str);
    int tot = 0, xx = 1, yy = 1;
    while (true) {
      if (xx == M[t] && yy == D[t]) break;
      yy++;
      if ((yy == 30 && xx == 2) ||
          (yy == 31 && (xx == 4 || xx == 6 || xx == 9 || xx == 11)) || yy == 32)
        xx++, yy = 1;
      tot++;
    }
    f[t] = tot * 24 * 60 * 60 + hh[t] * 60 * 60 + mm[t] * 60 + ss[t];
    t++;
  }
  int ans = -1;
  for (int i = t - 1; i >= m - 1; i--) {
    if (f[i] - f[i - m + 1] < n) ans = i;
  }
  if (ans > 0)
    printf("%d-%02d-%02d %02d:%02d:%02d\n", Y[ans], M[ans], D[ans], hh[ans],
           mm[ans], ss[ans]);
  else
    printf("-1\n");
}

solution_15:
#include <bits/stdc++.h>
using namespace std;
int days[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
class Date {
 public:
  inline static bool isLeap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
  }
  int year, month, day;
  inline bool isLegal() const {
    if (month <= 0 || month > 12) {
      return false;
    }
    if (month == 2) {
      return day > 0 && day <= 28 + isLeap(year);
    }
    return day > 0 && day <= days[month - 1];
  }
  inline int compareTo(const Date& other) const {
    if (year != other.year) {
      return year - other.year;
    }
    if (month != other.month) {
      return month - other.month;
    }
    return day - other.day;
  }
  inline int toWeekday() const {
    int tm = month >= 3 ? (month - 2) : (month + 10);
    int ty = month >= 3 ? year : (year - 1);
    return (ty + ty / 4 - ty / 100 + ty / 400 + (int)(2.6 * tm - 0.2) + day) %
           7;
  }
  inline int toInt() const {
    int ret = year * 365 + (year - 1) / 4 - (year - 1) / 100 + (year - 1) / 400;
    days[1] += isLeap(year);
    for (int i = 0; i < month - 1; ret += days[i++])
      ;
    days[1] = 28;
    return ret + day;
  }
  inline void fromInt(int a) {
    year = a / 146097 * 400;
    for (a %= 146097; a >= 365 + isLeap(year); a -= 365 + isLeap(year), year++)
      ;
    days[1] += isLeap(year);
    for (month = 1; a >= days[month - 1]; a -= days[month - 1], month++)
      ;
    days[1] = 28;
    day = a + 1;
  }
};
const int INF = 1000000007;
int main() {
  int n, m, yy, nn, dd, hh, mm, ss;
  vector<long long> a;
  scanf("%d%d", &n, &m);
  while (scanf("%d", &yy) == 1) {
    scanf("-%d-%d%d:%d:%d", &nn, &dd, &hh, &mm, &ss);
    while (getchar() != '\n') continue;
    Date t = {yy, nn, dd};
    a.push_back(((t.toInt() * 24ll + hh) * 60 + mm) * 60 + ss);
    if (a.size() >= m && a.back() - a[a.size() - m] < n)
      return printf("%d-%02d-%02d %02d:%02d:%02d\n", yy, nn, dd, hh, mm, ss), 0;
  }
  puts("-1");
}

