int getsec(struct date *x) {
  int t;
  t = mon[x->m - 1] * 3600 * 24;
  t += (x->d - 1) * 3600 * 24;
  t += x->h * 3600;
  t += x->min * 60;
  t += x->s;
  return t;
}
