vector<int> que[200000 + 5];
int s[400000 + 5];
bool check(int up) {
  for (int i = 1; i <= up; i++) s[i] = 0;
  for (int i = 1; i <= n; i++) {
    for (int j = que[i].size() - 1; j >= 0; j--) {
      if (que[i][j] <= up) {
        s[que[i][j]] += a[i];
        break;
      }
    }
  }
  int now = 0, buy = 0;
  for (int i = 1; i <= up; i++) {
    now++;
    buy += min(now, s[i]);
    now -= min(now, s[i]);
  }
  return now >= 2 * (sum - buy);
}
