  for (int i = 1; i <= n; i++) sort(que[i].begin(), que[i].end());
  r = sum << 1;
  int l = 0;
  while (l + 1 < r) {
    int mid = (l + r) >> 1;
    if (check(mid))
      r = mid;
    else
      l = mid;
  }
