void _W(const char *x) { cout << x; }
void _W(const string &x) { cout << x; }
template <class T, class U>
void _W(const pair<T, U> &x) {
  _W(x.first);
  cout << ' ';
  _W(x.second);
}
template <class T>
void _W(const vector<T> &x) {
  for (auto i = x.begin(); i != x.end(); _W(*i++))
    if (i != x.cbegin()) cout << ' ';
}
void W() {}
template <class T, class... U>
void W(const T &head, const U &...tail) {
  _W(head);
  cout << (sizeof...(tail) ? ' ' : '\n');
  W(tail...);
}
const int N = 2e5 + 10;
int n, m, x, y, d, tr, l, r;
vector<int> day[N];
vector<int> need(N);
bool can(int m) {
  int lastday = m;
  vector<int> tneed = need;
  vector<int> spend(2 * N, 0);
  for (int d = (min(m, 200000)); d > (0); d--) {
    for (auto tr : day[d]) {
      if (tneed[tr] > 0) {
        m -= tneed[tr];
        spend[d] += tneed[tr];
        tneed[tr] = 0;
      }
      if (m < 0) return false;
    }
    if (m < 0) return false;
  }
  for (int i = (1); i < (lastday + 1); i++) {
    spend[i] += spend[i - 1];
    if (spend[i] > i) {
      m -= (spend[i] - i);
      spend[i] = i;
    }
  }
  if (m < 0) return false;
  for (int i = (1); i < (n + 1); i++) {
    if (tneed[i] > 0) {
      m -= 2 * tneed[i];
    }
    if (m < 0) return false;
  }
  return true;
}
void solve() {
  R(n, m);
  for (int i = (1); i < (n + 1); i++) {
    R(need[i]);
    l += need[i];
  }
  for (int i = (1); i < (m + 1); i++) {
    R(d, tr);
    day[d].push_back(tr);
  }
  r = 2 * l;
  l -= 1;
  while (r - l > 1) {
    int m = (r + l) / 2;
    if (can(m)) {
      r = m;
    } else {
      l = m;
    }
  }
  W(r);
}
signed main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  int t = 1;
  for (int testcase = 1; testcase <= t; testcase++) {
    solve();
  }
  return 0;
}

