  for (int i = 0; i < m; ++i)
    if (last[i]) {
      cur_money += q[i].first - last_t;
      if (cur_money > need[q[i].second]) {
        cur_money -= need[q[i].second];
        ans -= need[q[i].second];
        need[q[i].second] = 0;
      } else {
        need[q[i].second] -= cur_money;
        ans -= cur_money;
        cur_money = 0;
      }
      last_t = q[i].first;
    }
  return ans <= day;
}
int main() {
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; ++i) {
    scanf("%d", &k[i]);
    sum += k[i];
  }
  for (int i = 0; i < m; ++i) {
    scanf("%d%d", &q[i].first, &q[i].second);
    --q[i].second;
  }
  sort(q, q + m);
  can(7);
  int l = 0, r = 2000000001;
  while (r - l > 1) {
    int mid = (l + r) >> 1;
    if (can(mid))
      r = mid;
    else
      l = mid;
  }
  printf("%d\n", r);
  return 0;
}

