import java.io.*;
import java.nio.CharBuffer;
import java.util.HashSet;
import java.util.NoSuchElementException;

public class P1165F2 {

    private static final int MAX = 200000;


    public static void main(String[] args) {
        SimpleScanner scanner = new SimpleScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[] target = new int[n];
        int sum = 0;
        for (int i = 0; i < n; ++i) {
            target[i] = scanner.nextInt();
            sum += target[i];
        }
        HashSet<Integer>[] sales = new HashSet[MAX + 1];
        for (int i = 0; i < m; ++i) {
            int d = scanner.nextInt();
            int t = scanner.nextInt() - 1;
            if (sales[d] == null)
                sales[d] = new HashSet<>();
            sales[d].add(t);
        }
        int l = sum, r = 2 * sum;
        while (l < r) {
            int mid = (l + r) >> 1;
            if (!test(target.clone(), sales, sum, mid))
                l = mid + 1;
            else
                r = mid;
        }
        writer.println(l);

        writer.close();
    }

    private static boolean test(int[] target, HashSet<Integer>[] sales, int sum, int k) {
        int mostSale = 0;
        for (int day = Math.min(k, MAX), fund = Math.min(k, MAX); fund > 0; --day, fund = Math.min(fund, day)) {
            if (sales[day] != null) {
                for (int sale : sales[day]) {
                    if (target[sale] > 0) {
                        int num = Math.min(fund, target[sale]);
                        target[sale] -= num;
                        fund -= num;
                        mostSale += num;
                    }
                }
            }
        }
        return 2 * sum - mostSale <= k;
    }

    private static class SimpleScanner {

        private static final int BUFFER_SIZE = 10240;

        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }


        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

