    void solve() throws IOException {

        int n = in.nextInt();
        int m = in.nextInt();
        int[] a = in.nextIntArray(n);

        g = new ArrayList[200010];
        for (int i = 0; i < g.length; i++)
            g[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int x = in.nextInt();
            int y = in.nextInt();
            g[x].add(y - 1);
        }

        int l = 0;
        int r = 10000000;

        while (r > l) {
            int mid = (l + r) / 2;
            int[] b = new int[n];
            int sum = 0;

            int[] last = new int[n];

            for ( int i = 1; i <= mid; i++) {
                if (i < g.length)
                    for (int t : g[i]) {
                        last[t] = i;
                    }
            }

            for ( int i = 1; i <= mid; i++) {
                sum++;
                if (i < g.length)
                    for (int t : g[i]) {
                        if (last[t] == i) {
                            while (b[t] < a[t] && sum > 0) {
                                b[t]++;
                                sum--;
                            }
                        }
                    }
            }

            //System.err.println(mid + " " + sum);

            for (int i = 0; i < n; i++)
                sum -= 2 * (a[i] - b[i]);

            if (sum < 0)
                l = mid + 1;
            else
                r = mid;
        }

        out.print(r);
    }


    class Pair implements Comparable<Pair> {
        int a;
        int b;

        Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        public int compareTo(Pair p) {
            if (a != p.a)
                return Integer.compare(a, p.a);
            else
                return Integer.compare(b, p.b);
        }
    }

