const int maxn = 2e5 + 10;
const int maxl = 110;
int n, m;
vector<int> v[maxn];
int k[maxn];
int lad[maxn];
vector<int> ddl[maxn << 2];
int kk[maxn];
bool ch(int dx) {
  memset(lad, -1, sizeof(lad));
  memcpy(kk, k, sizeof(kk));
  int cm = 0;
  for (int t = (0); t < (maxn << 2); ++t) ddl[t].clear();
  for (int i = 1; i <= n; ++i) {
    auto& e = v[i];
    int r = upper_bound(e.begin(), e.end(), dx) - e.begin() - 1;
    if (r >= 0) lad[i] = e[r], ddl[lad[i]].push_back(i);
  }
  for (int i = 1; i <= dx; ++i) {
    ++cm;
    for (auto& w : ddl[i]) {
      while (kk[w] > 0) {
        --kk[w];
        --cm;
        if (cm == 0) goto N;
      }
    }
  N:;
  }
  int lef = 0;
  for (int i = (1); i < (n + 1); ++i) lef += kk[i];
  lef <<= 1;
  return lef <= cm;
}
int main() {
  ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
