    v[ty].push_back(d);
  }
  for (int t = (1); t < (n + 1); ++t) {
    auto& e = v[t];
    sort(e.begin(), e.end());
  }
  int l = 1, r = 5e5;
  while (r - l > 1) {
    int mi = l + r >> 1;
    if (ch(mi))
      r = mi;
    else
      l = mi + 1;
  }
  while (!ch(l)) ++l;
  cout << l;
}

