import java.io.*;
import java.util.*;

public class Codechef {

    static class MyScanner{
        BufferedReader br;
	StringTokenizer st;

	MyScanner(FileReader fileReader){
            br = new BufferedReader(fileReader);
	}

	MyScanner(){
            br = new BufferedReader(new InputStreamReader(System.in));
	}

	String nn(){
            while(st == null || !st.hasMoreElements()){
		try{
                    st = new StringTokenizer(br.readLine());
		}catch(IOException e){
                    e.printStackTrace();
		}
            }
            return st.nextToken();
	}

	char nc(){
            return nn().charAt(0);
	}

	int ni(){
            return Integer.parseInt(nn());
	}

	long nl(){
            return Long.parseLong(nn());
	}

	double nd(){
            return Double.parseDouble(nn());
	}

	int[] niArr0(int n){
            int[] ar = new int[n];
            for(int i = 0; i < n; i++) ar[i] = ni();
            return ar;
	}

        int[] niArr1(int n){
            int[] ar = new int[n + 1];
            for(int i = 1; i <= n; i++) ar[i] = ni();
            return ar;
	}

        long[] nlArr0(int n){
            long[] ar = new long[n];
            for(int i = 0; i < n; i++) ar[i] = nl();
            return ar;
        }

        long[] nlArr1(int n){
            long[] ar = new long[n + 1];
            for(int i = 1; i <= n; i++) ar[i] = nl();
            return ar;
        }
    }

    public static <T> void mprintln(T ... ar){
        for(T i: ar) out.print(i + " ");
        out.println();
    }

    private static PrintWriter out;

    public static void main(String[] args) throws FileNotFoundException{

        // Input from file
        // File inputFile = new File("JavaFile.txt");
        // File outputFile = new File("JavaOutputFile.txt");
        // FileReader fileReader = new FileReader(inputFile);
        // Here it ends

        MyScanner sc = new MyScanner();
        // MyScanner sc = new MyScanner(fileReader);

        out = new PrintWriter(new BufferedOutputStream(System.out)); // Output to console
        // out = new PrintWriter(new PrintStream(outputFile)); // Output to file

        getAns(sc);

        out.close();
    }

    private static void getAns(MyScanner sc){
        int n = sc.ni(), m = sc.ni();
        int[] k = sc.niArr0(n);
        HashMap<Integer, NavigableSet<Integer>> map = new HashMap();

        for(int i = 0; i < m; i++){
            int day = sc.ni(), type = sc.ni();
            map.putIfAbsent(type, new TreeSet());
            map.get(type).add(day);
        }

//        out.println(map);

        int start = 1, end = 4 * (int)1e5;
        int ans = end;

//        out.println(map);

        while(start <= end){
            int mid = start + end >> 1;
            if(OK(mid, getMapAccordingly(map, mid), Arrays.copyOf(k, n), n)){
                ans = mid;
                end = mid - 1;
            }else{
                start = mid + 1;
            }
        }

        out.println(ans);
    }

    private static HashMap<Integer, ArrayList<Integer>> getMapAccordingly(HashMap<Integer, NavigableSet<Integer>> map, int day){
        HashMap<Integer, ArrayList<Integer>> curMap = new HashMap();

        for(Integer in: map.keySet()){
            NavigableSet<Integer> set = map.get(in);
            Integer cur = set.floor(day);
            if(cur == null) continue;
            curMap.putIfAbsent(cur, new ArrayList<>());
            curMap.get(cur).add(in);
        }

//        out.println(day + " " + curMap);

        return curMap;
    }

    private static boolean OK(int days, HashMap<Integer, ArrayList<Integer>> map, int[] k, int n){
        int cur = 0;
//        out.println(days);

        for(int i = 1; i <= days; i++){
            ++cur;
            ArrayList<Integer> index = map.get(i);
            if(index == null) continue;
            for(Integer in: index){
                if(cur == 0) break;
                int min = Math.min(cur, k[in - 1]);
                cur -= min;
                k[in - 1] -= min;
            }
        }

        for(int i = 0; i < n; i++) cur -= 2 * k[i];

        return cur >= 0;
    }
}

