import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.stream.IntStream;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in Actual solution is at the top
 *
 * @author NMouad21
 */
public class Main {

  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    PrintWriter out = new PrintWriter(outputStream);
    F2MicrotransactionsHardVersion solver = new F2MicrotransactionsHardVersion();
    solver.solve(1, in, out);
    out.close();
  }

  static class F2MicrotransactionsHardVersion {

    public void solve(int testNumber, InputReader in, PrintWriter out) {
      int n = in.nextInt();
      int m = in.nextInt();
      int[] k = in.nextIntArrayOneBased(n);
      final int sum = IntStream.of(k).sum();
      final int maxDay = (int) 2e5;

      ArrayList<Integer>[] s = (ArrayList<Integer>[]) new ArrayList[maxDay + 1];
      for (int i = 0; i < s.length; i++) {
        s[i] = new ArrayList<>();
      }
      for (int i = 0; i < m; i++) {
        int d = in.nextInt();
        int t = in.nextInt();
        s[d].add(t);
      }

      int lo = 0, hi = (int) 5e5, ans = hi;
      while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (sum * 2 - saved(s, Arrays.copyOf(k, k.length), Math.min(mid + 1, s.length), n) <= mid) {
          hi = mid - 1;
          ans = mid;
        } else {
          lo = mid + 1;
        }
      }

      out.println(ans);
    }

    private int saved(ArrayList<Integer>[] s, int[] k, int length, int n) {
      int[] lastSale = new int[n + 1];
      for (int i = 1; i < length; i++) {
        for (int type : s[i]) {
          lastSale[type] = i;
        }
      }

      int saved = 0, has = 0;
      for (int i = 1; i < length; i++) {
        ++has;
        for (int type : s[i]) {
          if (i == lastSale[type]) {
            int win = Math.min(has, k[type]);
            saved += win;
            k[type] -= win;
            has -= win;
          }
        }
      }

      return saved;
    }

  }

  static class InputReader {

    private InputStream stream;
    private static final int DEFAULT_BUFFER_SIZE = 1 << 16;
    private static final int EOF = -1;
    private byte[] buf = new byte[DEFAULT_BUFFER_SIZE];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public int read() {
      if (this.numChars == EOF) {
        throw new UnknownError();
      } else {
        if (this.curChar >= this.numChars) {
          this.curChar = 0;

          try {
            this.numChars = this.stream.read(this.buf);
          } catch (IOException ex) {
            throw new InputMismatchException();
          }

          if (this.numChars <= 0) {
            return EOF;
          }
        }

        return this.buf[this.curChar++];
      }
    }

    public int nextInt() {
      int c;
      for (c = this.read(); isSpaceChar(c); c = this.read()) {
      }

      byte sgn = 1;
      if (c == 45) {
        sgn = -1;
        c = this.read();
      }

      int res = 0;

      while (c >= 48 && c <= 57) {
        res *= 10;
        res += c - 48;
        c = this.read();
        if (isSpaceChar(c)) {
          return res * sgn;
        }
      }

      throw new InputMismatchException();
    }

    public static boolean isSpaceChar(int c) {
      return c == 32 || c == 10 || c == 13 || c == 9 || c == EOF;
    }

    public int[] nextIntArrayOneBased(int n) {
      int[] ret = new int[n + 1];
      for (int i = 1; i <= n; i++) {
        ret[i] = nextInt();
      }
      return ret;
    }

  }
}

