      c[b[i].second] = b[i].first;
    }
  }
  for (int i = 1; i <= n; i++) {
    if (c[i] > 0) v.push_back(make_pair(c[i], i));
    aa[i] = a[i];
  }
  sort((v).begin(), (v).end());
  int day = 0, money = 0;
