public class A {

	public static void main(String[] args) {
		Scanner scan=new Scanner(System.in);
		int n=scan.nextInt();
		int d=scan.nextInt();
		int arr[][]=new int[2][d];
		for(int i=0;i<d;i++){
			arr[0][i]=scan.nextInt();
			arr[1][i]=scan.nextInt();
		}
		System.out.println(B(n));

	}

	public static int A(int n, int d, int arr[]){

		int diff=2*d;
		int ans=2;
		for(int i=0;i<n-1;i++){
			if(arr[i+1]-arr[i]<diff){
				continue;
			}

			int foundDiff=arr[i+1]-arr[i];
			ans+= foundDiff-diff+1;

		}

		return ans;
	}

	public static String B(int n){
		String s="";
		for(int i=0;i<n;i++){
			s+= (i%2==0)? "0": "1";
		}
		return s;
	}

}

