        long p=power(b,mod-2);

        p=a%mod*p%mod;
        p%=mod;

        return p;

    }
    long power(long x,long y){
        if(y==0)return 1%mod;
        if(y==1)return x%mod;
        long res=1;
        x=x%mod;
        while(y>0)
        {
            if((y%2)!=0){
                res=(res*x)%mod;
            }
            y=y/2;
            x=(x*x)%mod;
        }
        return res;
