  for (int i = 0; i < (int)n; ++i) {
    A[a[i]] = a[i];
  }
  for (int mask = 0; mask < (1 << N); ++mask) {
    dp[mask] = A[mask];
  }
  for (int mask = 0; mask < (1 << N); ++mask) {
    for (int i = 0; i < N; ++i) {
      if ((mask & (1 << i)) == 0 && dp[mask]) {
        dp[mask ^ (1 << i)] = dp[mask];
      }
    }
  }
  for (int i = 0; i < (int)n; ++i) {
    int mask = L ^ a[i];
    if (dp[mask]) {
