    if (dp[i]) continue;
    for (int j = 0; j <= magic; j++) {
      if (((i >> j) & 1) == 0) continue;
      int mask = i ^ (1 << j);
      if (dp[mask]) {
        dp[i] = dp[mask];
        break;
      }
