import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.*;

public class E112Div2
{
    public static void main(String[] args)
    {
        new E112Div2(System.in, System.out);
    }

    private static class Solver implements Runnable
    {
        int n;
        int[] arr, dp;
        InputReader in;
        PrintWriter out;

        void solve() throws IOException
        {
            int lim = (1 << 22);

            n = in.nextInt();
            arr = new int[n];
            dp = new int[lim];
            Arrays.fill(dp, -1);

            for (int i = 0; i < n; i++)
            {
                arr[i] = in.nextInt();
                dp[arr[i]] = arr[i];
            }

            for (int mask = 0; mask < lim; mask++)
            {
                if (dp[mask] != -1)
                {
                    for (int i = 0; i < 22; i++)
                        dp[mask | (1 << i)] = dp[mask];
                }
            }

/*            for (int i = 0; i < 22; i++)
            {
                for (int mask = 0; mask < lim; mask++)
                {
                    if (dp[mask] != 0)
                        dp[mask | (1 << i)] = dp[mask];
                }
            }*/

            for (int i = 0; i < n; i++)
                out.print(dp[~arr[i] & (1 << 22) - 1] + " ");
        }

        Solver(InputReader in, PrintWriter out)
        {
            this.in = in;
            this.out = out;
        }

        @Override
        public void run()
        {
            try
            {
                solve();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
        }

    }

    private static class InputReader
    {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        int read()
        {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars)
            {
                curChar = 0;
                try
                {
                    numChars = stream.read(buf);
                }
                catch (IOException e)
                {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }

            return buf[curChar++];
        }

        int nextInt()
        {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-')
            {
                sgn = -1;
                c = read();
            }

            int res = 0;

            do
            {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += c & 15;

                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        boolean isSpaceChar(int c)
        {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        void close()
        {
            try
            {
                stream.close();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
        }

        InputReader(InputStream stream)
        {
            this.stream = stream;
        }

    }

    private E112Div2(InputStream inputStream, OutputStream outputStream)
    {
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Thread thread = new Thread(null, new Solver(in, out), "Solver", 1 << 29);

        try
        {
            thread.start();
            thread.join();
        }
        catch (InterruptedException e)
        {
            e.printStackTrace();
        }

        in.close();
        out.flush();
        out.close();
    }

}

