#include <bits/stdc++.h>
using namespace std;
const int N = (1 << 23) - 1;
int n, a[N], bits = 22, mem[N];
int dp(int mask) {
  int &ret = mem[mask];
  if (ret != -1) {
    return ret;
  }
  ret = -2;
  for (int i = 0; i < bits; i++) {
    if (mask & (1 << i)) {
      ret = max(ret, dp(mask - (1 << i)));
    }
  }
  return ret;
}
int get(int x) {
  int mask = (((1 << 22) - 1) - x);
  int ret = dp(mask);
  if (ret == -2) {
    return -1;
  }
  return ret;
}
int main() {
  memset(mem, -1, sizeof mem);
  scanf("%d", &n);
  for (long long i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
    mem[a[i]] = a[i];
  }
  for (int i = 0; i < (1 << bits); i += 1024) {
    dp(i);
  }
  for (long long i = 1; i <= n; i++) {
    int ans = get(a[i]);
    printf("%d ", ans);
  }
}

solution_9:
#include <bits/stdc++.h>
using namespace std;
const int maxn = (int)1e6 + 10;
const int L = 22;
int a[maxn], magic[1 << L], n;
bool seen[1 << L];
int global_elite;
void input(void) {
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
}
void dfs(int &v) {
  seen[v] = 1;
  magic[v] = global_elite;
  for (int i = 0; i <= L - 1; i++)
    if ((v & (1 << i)) == 0 && !seen[v | (1 << i)]) {
      v |= 1 << i;
      dfs(v);
      v &= ~(1 << i);
    }
}
int main() {
  input();
  for (int i = 1; i <= n; i++) {
    global_elite = a[i];
    dfs(a[i]);
  }
  for (int i = 1; i <= n; i++) {
    int no = 0;
    for (int j = 0; j <= L - 1; j++) {
      int number = (1 << j);
      if ((a[i] & number) == 0) no |= number;
    }
    if (!magic[no]) magic[no]--;
    printf("%d ", magic[no]);
  }
  printf("\n");
  return 0;
}

