public class Solution {

	final static int MAXVAL = (1 << 22) - 1;

	public static void main(String[] args) throws IOException {
		StreamTokenizer in = new StreamTokenizer(new InputStreamReader(System.in));

		in.nextToken();
		int n = (int) Math.round(in.nval);
		int[] a = new int[n + 1];
		int m[] = new int[MAXVAL + 1];
		a[0] = -1;
		for (int i = 1; i <= n; i++) {
			in.nextToken();
			a[i] = (int) Math.round(in.nval);
			m[(~a[i]) & MAXVAL] = i;
		}
		for (int x = MAXVAL; x >= 0; x--) {
			if (m[x] > 0) continue;
			for (int j = 0; j < 22; j++)
				if ((m[x] = m[x | (1 << j)]) > 0)
					break;
		}

		for (int i = 1; i <= n; i++)
			System.out.println(a[m[a[i]]]);
	}

}

