  for (i = 0; i < n; i++) {
    cin >> a[i];
    dp[a[i]] = a[i];
    while ((1 << N) <= a[i]) N++;
  }
  for (j = 0; j < N; j++)
    for (i = 0; i < (1 << N); i++)
      if ((i >> j) & 1) dp[i] = max(dp[i ^ (1 << j)], dp[i]);
  for (i = 0; i < n; i++)
    cout << (dp[a[i] ^ ((1 << N) - 1)] ? dp[a[i] ^ ((1 << N) - 1)] : -1) << " ";
  return 0;
}

