#include <bits/stdc++.h>
using namespace std;
int powermod(int a, int b, int c) {
  int ans = 1, tempans = a % c;
  while (b > 0) {
    if ((b & 1) == 1) {
      ans = (ans * tempans) % c;
    }
    tempans = (tempans * tempans) % c;
    b = b >> 1;
  }
  return ans;
}
int modinverse(int a, int m) { return powermod(a, m - 2, m); }
long long add(long long x, long long y) {
  x += y;
  if (x >= 1000000007) return x - 1000000007;
  return x;
}
long long sub(long long x, long long y) {
  x -= y;
  if (x < 0) return x + 1000000007;
  return x;
}
long long mult(long long x, long long y) { return (x * y) % 1000000007; }
long long inv(long long x) { return powermod(x, 1000000007 - 2, 1000000007); }
long long divide(long long x, long long y) { return mult(x, inv(y)); }
