    int x = (m.find(mask) != m.end()) ? m[mask] : -1;
    dp[mask][0] = x;
  }
  for (int j = 1; j <= nn; j++) {
    for (int mask = 0; mask < (1 << nn); mask++) {
      int moddd = j & 1;
      if (mask & (1 << (j - 1))) {
        if (dp[mask][1 - moddd] != -1) {
          dp[mask][moddd] = dp[mask][1 - moddd];
        } else if (dp[mask ^ (1ll << (j - 1))][1 - moddd] != -1) {
          dp[mask][moddd] = dp[mask ^ (1ll << (j - 1))][1 - moddd];
        } else {
          dp[mask][moddd] = -1;
        }
      } else {
        if (dp[mask][1 - moddd] != -1) {
          dp[mask][moddd] = dp[mask][1 - moddd];
        } else {
          dp[mask][moddd] = -1;
        }
      }
    }
  }
  for (int i = 0; i < n; i++) {
