public class F {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        for (int o = 0; o < t; o++) {
            int l = scanner.nextInt(),
                    r = scanner.nextInt();
            int n = String.valueOf(r).length();
            String ones = "";
            for (int i = 0; i < n; i++) {
                ones += "1";
            }
            int prefix = Integer.parseInt(ones);
            String right = String.valueOf(r);
            int res = 0;
            for (int i = 0; i < n; i++) {
                res += prefix * Integer.parseInt(right.charAt(i)+"");
                prefix /= 10;
            }
            n = String.valueOf(l).length();
            ones = "";
            for (int i = 0; i < n; i++) {
                ones += "1";
            }
            prefix = Integer.parseInt(ones);
            String left = String.valueOf(l);
            int ans = 0;
            for (int i = 0; i < n; i++) {
                ans += prefix * Integer.parseInt(left.charAt(i)+"");
                prefix /= 10;
            }
            System.out.println(res - ans);
        }
    }


    static int min(int a, int b) {
        return Math.min(a, b);
    }

    static int min(int a, int b, int c) {
        return min(a, min(b, c));
    }

    static int max(int a, int b) {
        return Math.max(a, b);
    }

    static int max(int a, int b, int c) {
        return max(a, max(b, c));
    }

    static int abs(int x) {
        return Math.abs(x);
    }

    static double sqrt(int x) {
        return Math.sqrt(x);
    }

    static int gcd(int a, int b) {
        if (b == 0)
            return a;
        return gcd(b, a % b);
    }
}

