	catch (IOException e)
	{
	e.printStackTrace();
	}
	return str;
	}
	}
	static long solve(long n)
	{
		long sum=0;
		long m=1;
		for (int i=0;i<12;i++)
		{
			sum+=n/m;
			m*=10;;
		}
		return sum;
	}

	public static void main(String[] args) throws java.lang.Exception {
