import java.io.*;
import java.util.StringTokenizer;

public class F {
    public static void main(String[] args) {
        new F().solve(System.in, System.out);
    }

    public void solve(InputStream in, OutputStream out) {
        InputReader inputReader = new InputReader(in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(out));

        int t = inputReader.nextInt();
        for (int t1 = 0; t1 < t; t1++) {
            int l = inputReader.nextInt();
            int r = inputReader.nextInt();
            writer.println(solve(l, r));
        }

        writer.close();
    }

    public int solve(int l, int r) {
        return solve(l, r, 1);
    }

    public int solve(int l, int r, int d) {
        if (l == r) {
            return 0;
        }
        int l10 = l % 10;
        int lAdd = (10 - l10) % 10;
        if (l + lAdd >= r) {
            return bruteSolve(l, r, d);
        }
        int rMinus = r % 10;
        int solveMore = solve((l + lAdd) / 10, (r - rMinus) / 10, d * 10 + 1);
        int lAddCost;
        if (lAdd == 0) {
            lAddCost = 0;
        } else {
            int[] array = toArray(l);
            int i = 1;
            lAddCost = 1;
            while (array[i] == 9) {
                lAddCost++;
                i++;
            }
        }
        return d * lAdd + lAddCost + d * rMinus + solveMore;
    }

    public int bruteSolve(int l, int r, int d) {
        int[] first = toArray(l);
        int[] second = toArray(r);
        int result = 0;
        while (!eq(first, second)) {
            result += d + add(first) - 1;
        }
        return result;
    }

    private int[] toArray(int x) {
        int[] result = new int[10];
        int i = 0;
        while (x > 0) {
            result[i++] = x % 10;
            x /= 10;
        }
        return result;
    }

    private boolean eq(int[] first, int[] second) {
        for (int i = 0; i < first.length; i++) {
            if (first[i] != second[i]) {
                return false;
            }
        }
        return true;
    }

    private int add(int[] a) {
        int i = 0;
        int result = 0;
        while (true) {
            a[i]++;
            result++;
            if (a[i] < 10) {
                break;
            }
            a[i] -= 10;
            i++;
        }
        return result;
    }

    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

