def main():
    n, a, b = map(int, input().split())
    ab = a + b
    for v in map(len, filter(None, input().split('*'))):
        if v & 1:
            v //= 2
            if a > b:
                a -= v + 1
                b -= v
            else:
                b -= v + 1
                a -= v
        else:
            v //= 2
            a -= v
            b -= v
    print(ab - max(a, 0) - max(b, 0))


