  _, a, b = map(int, input().split())
  s = input()
  intervals = []
  cur = 0
  for c in s:
    if c == '*' and cur:
      intervals.append(cur) 
      cur = 0
    elif c != '*':
      cur += 1
  if cur:
    intervals.append(cur)

  nb_student_init = a + b
  for i in intervals:
    if a == 0 and b == 0:
      break 
    elif a > b: 
      max_a_in_i = min(a, (i+1) // 2)
      a -= max_a_in_i
      max_b_in_i = min(i - max_a_in_i, b)
      b -= max_b_in_i
    else:
      max_b_in_i = min(b, (i+1) // 2)
      b -= max_b_in_i
      max_a_in_i = min(i - max_b_in_i, a)
      a -= max_a_in_i

  print(nb_student_init - a - b)

