import java.util.*;
public class Main{
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int t=sc.nextInt();
        while(t-->0){
            int n=sc.nextInt(),k=sc.nextInt();
            int[] arr=new int[n];
            int[] w=new int[k];
            for(int i=0;i<n;i++) arr[i]=sc.nextInt();
            for(int i=0;i<k;i++) w[i]=sc.nextInt();
            Arrays.sort(arr);
            Arrays.sort(w);
            long sum=0;
            int x=0,y=n-k;
            for(int i=k-1;i>=0;i--){
                int a=w[i];
                if(a>1){
                    sum+=arr[x];
                    sum+=arr[y];
                    x+=a-1;
                    y++;
                }
                else{
                    sum+=arr[y];
                    sum+=arr[y];
                    y++;
                }
            }
            System.out.println(sum);
        }
    }
}

