import math

def isPrimes2(n):
    if n > 1:
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for x in range(3, int(math.sqrt(n) + 1), 2):
            if n % x == 0:
                return False
        return True
    return False

def isok(n):
    while n!=1:
        if n%2==1:
            return False
        n/=2
    return True

def main():
