                ans += 2 * a[flag1]
                flag1 -= 1
            elif w[j] == 1 and j == len(w) - 1:
                ans += 2 * a[flag1]
                flag1 -= 1
                tmp = j + 1
                break
            else:
                tmp = j
                break
        # print(tmp)
        for j in range(len(w) - tmp):
            ans += a[flag1]
            ans += a[flag0]
            flag1 -= 1
            flag0 += w[-j-1] - 1
        print(ans)
