        sum = sum + a[j];
      c[i] = c[i] - 1;
      j = j - 1;
    }
    j = m + 1;
    i = n - k - 1;
    for (i = i; i >= 0; i = i - 1) {
      while (c[j] > 1) {
        c[j] = c[j] - 1;
        i = i - 1;
      }
      sum = sum + a[i];
      j = j + 1;
    }
    cout << sum << "\n";
  }
  return 0;
}

