void dfs1(long long u, long long f) {
  siz[u] = 1;
  for (long long i = head[u]; ~i; i = edge[i].nxt) {
    long long v = edge[i].v;
    if (v == f) continue;
    fa[v] = u;
    dep[v] = dep[u] + 1;
    dis[v] = dis[u] + edge[i].w;
    dfs1(v, u);
    siz[u] += siz[v];
    if (siz[v] > siz[son[u]]) son[u] = v;
  }
}
long long tim;
long long dfn[500010];
long long rea[500010];
long long top[500010];
void dfs2(long long u, long long tp) {
  dfn[u] = ++tim;
  rea[tim] = u;
  top[u] = tp;
  if (son[u]) {
    dfs2(son[u], tp);
  }
  for (long long i = head[u]; ~i; i = edge[i].nxt) {
    long long v = edge[i].v;
    if (v == fa[u] || v == son[u]) continue;
    dfs2(v, v);
  }
}
long long minn[800010];
long long sum[800010];
long long sb[500010];
void up(long long o) { minn[o] = min(minn[o << 1], minn[o << 1 | 1]); }
long long tag[800010];
void down(long long o, long long v, long long type) {
  if (type == 0) sum[o] += v;
  tag[o] += v, minn[o] += v;
}
void pushdown(long long o) {
  if (tag[o]) {
    down(o << 1, tag[o], 0);
    down(o << 1 | 1, tag[o], 0);
    tag[o] = 0;
  }
}
void build(long long o, long long l, long long r) {
  if (l == r) {
    minn[o] = dis[rea[l]] + sb[rea[l]];
    sum[o] = dis[rea[l]];
    return;
  }
  long long mid = (l + r) / 2;
  build(o << 1, l, mid);
  build(o << 1 | 1, mid + 1, r);
  up(o);
}
void update(long long o, long long l, long long r, long long L, long long R,
            long long v, bool type) {
  if (L <= l && r <= R) {
    down(o, v, type);
    return;
  }
  pushdown(o);
  long long mid = (l + r) / 2;
  if (L <= mid) update(o << 1, l, mid, L, R, v, type);
  if (mid < R) update(o << 1 | 1, mid + 1, r, L, R, v, type);
  up(o);
}
long long queryminn(long long o, long long l, long long r, long long L,
                    long long R) {
  if (L <= l && r <= R) {
    return minn[o];
  }
  pushdown(o);
  long long mid = (l + r) / 2;
  long long ret = 19198e10;
  if (L <= mid) ret = min(ret, queryminn(o << 1, l, mid, L, R));
  if (mid < R) ret = min(ret, queryminn(o << 1 | 1, mid + 1, r, L, R));
  return ret;
}
long long queryx(long long o, long long l, long long r, long long x) {
  if (l == r) {
    return sum[o];
  }
  pushdown(o);
  long long mid = (l + r) / 2;
  if (x <= mid)
    return queryx(o << 1, l, mid, x);
  else
    return queryx(o << 1 | 1, mid + 1, r, x);
}
long long LCA(long long u, long long v) {
  while (top[u] != top[v]) {
    if (dep[u] < dep[v]) swap(u, v);
    u = fa[top[u]];
  }
  if (dep[u] > dep[v]) swap(u, v);
  return u;
}
long long query(long long u, long long v) {
  if (LCA(u, v) == u) {
    return queryx(1, 1, n, dfn[v]) - queryx(1, 1, n, dfn[u]);
  } else {
    return queryx(1, 1, n, dfn[v]) - queryx(1, 1, n, dfn[u]) +
           queryminn(1, 1, n, dfn[u], dfn[u] + siz[u] - 1);
  }
}
struct e {
  long long v;
  long long fa, u;
} ed[500010];
void change(long long i, long long v) {
  if (i <= n - 1) {
    update(1, 1, n, dfn[ed[i].u], dfn[ed[i].u] + siz[ed[i].u] - 1, v - ed[i].v,
           0);
    ed[i].v = v;
  } else {
    update(1, 1, n, dfn[ed[i].u], dfn[ed[i].u], v - sb[ed[i].u], 1);
    sb[ed[i].u] = v;
  }
}
signed main() {
  memset(head, -1, sizeof(head));
  long long q;
  scanf("%lld%lld", &n, &q);
  for (long long i = 1; i < n; ++i) {
    long long u, v, w;
    scanf("%lld%lld%lld", &u, &v, &w);
    add(u, v, w), add(v, u, w);
    ed[i].fa = u, ed[i].u = v, ed[i].v = w;
  }
  for (long long i = 1; i < n; ++i) {
    long long u, v;
    scanf("%lld%lld", &u, &v);
    scanf("%lld", &sb[u]);
    ed[i + n - 1].u = u;
  }
  dfs1(1, -1), dfs2(1, 1);
  build(1, 1, n);
  for (long long i = 1; i <= q; ++i) {
    long long opt, x, y;
    scanf("%lld%lld%lld", &opt, &x, &y);
    if (opt == 1) {
      change(x, y);
    } else {
      printf("%lld\n", query(x, y));
    }
  }
}

solution_2:
#include <bits/stdc++.h>
using namespace std;
vector<pair<int, int> > adj[400005];
int a[400005], b[400005], w[400005];
int anc[400005][20], depth[400005];
int ml[400005], mr[400005];
int pos = 1;
void dfs(int node, int p) {
  anc[node][0] = p;
  ml[node] = pos++;
  for (int i = 1; i < 20; ++i) {
    anc[node][i] = anc[anc[node][i - 1]][i - 1];
  }
  for (pair<int, int> edge : adj[node]) {
    int ch = edge.second;
    if (p == ch) {
      continue;
    }
    depth[ch] = depth[node] + 1;
    dfs(ch, node);
  }
  mr[node] = pos - 1;
}
bool isAncestor(int a, int b) {
  if (depth[a] > depth[b]) {
    return false;
  }
  int d = depth[b] - depth[a];
  for (int i = 0; i < 20; ++i) {
    if (d & (1 << i)) {
      b = anc[b][i];
    }
  }
  return a == b;
}
int id[400005], idw[400005];
void push(long long *seg, long long *lazy, int pos, int l, int r) {
  if (lazy[pos] != 0) {
    seg[pos] += lazy[pos];
    if (l != r) {
      lazy[pos * 2] += lazy[pos];
      lazy[pos * 2 + 1] += lazy[pos];
    }
    lazy[pos] = 0;
  }
}
void update(long long *seg, long long *lazy, int pos, int l, int r, int ql,
            int qr, int val) {
  push(seg, lazy, pos, l, r);
  if (r < ql || qr < l) {
    return;
  }
  if (ql <= l && r <= qr) {
    lazy[pos] = val;
    push(seg, lazy, pos, l, r);
    return;
  }
  int mid = (l + r) / 2;
  update(seg, lazy, pos * 2, l, mid, ql, qr, val);
  update(seg, lazy, pos * 2 + 1, mid + 1, r, ql, qr, val);
  seg[pos] = min(seg[pos * 2], seg[pos * 2 + 1]);
}
long long query(long long *seg, long long *lazy, int pos, int l, int r, int ql,
                int qr) {
  push(seg, lazy, pos, l, r);
  if (r < ql || qr < l) {
    return 1e18;
  }
  if (ql <= l && r <= qr) {
    return seg[pos];
  }
  int mid = (l + r) / 2;
  return min(query(seg, lazy, pos * 2, l, mid, ql, qr),
             query(seg, lazy, pos * 2 + 1, mid + 1, r, ql, qr));
}
long long seg[400005 * 4], lazy[400005 * 4], qq[400005 * 4], ww[400005 * 4];
int g[400005];
void solve() {
  int n, q;
  scanf("%d %d ", &n, &q);
  for (int i = 1; i <= n - 1; ++i) {
    scanf("%d %d %d ", &a[i], &b[i], &w[i]);
    adj[a[i]].push_back(make_pair(i, b[i]));
  }
  for (int i = n; i <= 2 * n - 2; ++i) {
    int x, y, z;
    scanf("%d %d %d ", &x, &y, &z);
    id[i] = x;
    idw[i] = z;
    g[x] = i;
  }
  dfs(1, 0);
  for (int i = 1; i <= n - 1; ++i) {
    update(seg, lazy, 1, 1, n, ml[b[i]], mr[b[i]], w[i]);
    update(qq, ww, 1, 1, n, ml[b[i]], mr[b[i]], w[i]);
  }
  for (int i = n; i <= 2 * n - 2; ++i) {
    update(qq, ww, 1, 1, n, ml[id[i]], ml[id[i]], idw[i]);
  }
  while (q--) {
    int type, x, y;
    scanf("%d %d %d ", &type, &x, &y);
    if (type == 1) {
      if (x <= n - 1) {
        int ch = b[x];
        update(seg, lazy, 1, 1, n, ml[ch], mr[ch], y - w[x]);
        update(qq, ww, 1, 1, n, ml[ch], mr[ch], y - w[x]);
        w[x] = y;
      } else {
        int ch = id[x];
        update(qq, ww, 1, 1, n, ml[ch], ml[ch], y - idw[x]);
        idw[x] = y;
      }
    } else {
      long long ret = 0;
      if (isAncestor(x, y)) {
        ret = query(seg, lazy, 1, 1, n, ml[y], ml[y]) -
              query(seg, lazy, 1, 1, n, ml[x], ml[x]);
      } else {
        ret = query(qq, ww, 1, 1, n, ml[x], mr[x]) -
              query(seg, lazy, 1, 1, n, ml[x], ml[x]);
        ret += query(seg, lazy, 1, 1, n, ml[y], ml[y]);
      }
      printf("%lld\n", ret);
    }
  }
}
int main() {
  solve();
  return 0;
}

solution_3:
#include <bits/stdc++.h>
using namespace std;
struct Fenwick {
  vector<long long> A;
  long long n;
  Fenwick(long long n = 1) : n(n) { A = vector<long long>(n + 1, 0); }
  inline long long lsb(long long x) { return ((x) & (-x)); }
  void add(long long i, long long w) {
    for (; i <= n; i += lsb(i)) {
      A[i] += w;
    }
  }
  long long get(long long i) {
    i = min(i, n);
    long long ret = 0;
    for (; i > 0; i -= lsb(i)) {
      ret += A[i];
    }
    return ret;
  }
};
struct ST {
  long long l, r;
  long long mn = 0;
  ST *left;
  ST *right;
  long long lazy = 0;
  ST(long long l, long long r) : l(l), r(r) {
    if (l < r) {
      left = new ST(l, (l + r) / 2);
      right = new ST((l + r) / 2 + 1, r);
    }
  }
  void fix() {
    mn += lazy;
    if (l < r) {
      left->lazy += lazy;
      right->lazy += lazy;
    }
    lazy = 0;
  }
  long long get(long long a, long long b) {
    fix();
    if (a <= l && r <= b) return mn;
    if (r < a || b < l) return 1e17;
    return min(left->get(a, b), right->get(a, b));
  }
  void add(long long a, long long b, long long w) {
    fix();
    if (a <= l && r <= b) {
      lazy += w;
      return fix();
    }
    if (r < a || b < l) return;
    left->add(a, b, w);
    right->add(a, b, w);
    mn = min(left->mn, right->mn);
  }
  void set(long long i, long long w) {
    fix();
    if (l <= i && i <= r) {
      if (l == r) {
        mn = w;
        return;
      }
      left->set(i, w);
      right->set(i, w);
      mn = min(left->mn, right->mn);
    }
  }
};
int main() {
  ios_base::sync_with_stdio(false);
  long long n, q;
  cin >> n >> q;
  long long d1[n + 1];
  d1[1] = 0;
  vector<long long> adj[n + 1];
  long long a[2 * n];
  long long b[2 * n];
  long long c[2 * n];
  long long d[n + 1];
  d[1] = 0;
  for (long long i = 1; i <= 2 * n - 2; i++) {
    cin >> a[i] >> b[i] >> c[i];
    if (b[i] == 1)
      d1[a[i]] = c[i];
    else {
      adj[a[i]].push_back(b[i]);
      d[b[i]] = c[i];
    }
  }
  long long timer = 1;
  long long in[n + 1];
  long long out[n + 1];
  function<void(long long)> dfs = [&](long long i) {
    in[i] = out[i] = timer++;
    for (long long j : adj[i]) {
      dfs(j);
      out[i] = out[j];
    }
  };
  dfs(1);
  Fenwick W(n + 3);
  for (long long i = 1; i <= n; i++) {
    W.add(in[i], d[i]);
    W.add(out[i] + 1, -d[i]);
  }
  ST XXX(in[1], out[1]);
  for (long long i = 1; i <= n; i++) {
    XXX.set(in[i], d1[i] + W.get(in[i]));
  }
  while (q--) {
    long long t;
    cin >> t;
    if (t == 2) {
      long long x, y;
      cin >> x >> y;
      if (in[x] <= in[y] && in[y] <= out[x]) {
        cout << W.get(in[y]) - W.get(in[x]) << "\n";
      } else {
        cout << XXX.get(in[x], out[x]) - W.get(in[x]) + W.get(in[y]) << "\n";
      }
    } else {
      long long i, w;
      cin >> i >> w;
      if (b[i] == 1) {
        d1[a[i]] = w;
        long long c = a[i];
        XXX.set(in[c], d1[c] + W.get(in[c]));
      } else {
        W.add(in[b[i]], w - c[i]);
        W.add(out[b[i]] + 1, -(w - c[i]));
        XXX.add(in[b[i]], out[b[i]], w - c[i]);
        c[i] = w;
      }
    }
  }
}

solution_4:
#include <bits/stdc++.h>
using namespace std;
const int N = 800000 + 10;
const long long INF = 1e18;
int n, m, u[N], v[N], w[N];
int dfnL[N], dfnR[N], who[N], moment;
long long dis[N], lazy[N], val[N];
long long disToRoot[N];
vector<pair<int, int> > g[N];
long long par[N][20], dep[N];
void dfs(int u, int p) {
  dfnL[u] = ++moment;
  who[moment] = u;
  dep[u] = dep[p] + 1;
  for (int i = 0; i < g[u].size(); i++) {
    int v = g[u][i].first;
    par[v][0] = u;
    dis[v] = dis[u] + g[u][i].second;
    dfs(v, u);
  }
  dfnR[u] = moment;
}
void push_down(int rt) {
  if (lazy[rt]) {
    lazy[rt << 1] += lazy[rt];
    lazy[rt << 1 | 1] += lazy[rt];
    val[rt << 1] += lazy[rt];
    val[rt << 1 | 1] += lazy[rt];
    lazy[rt] = 0;
  }
}
void build(int l, int r, int rt) {
  if (l == r) {
    val[rt] = dis[who[l]] + disToRoot[who[l]];
    return;
  }
  int mid = (l + r) >> 1;
  build(l, mid, rt << 1);
  build(mid + 1, r, rt << 1 | 1);
  val[rt] = min(val[rt << 1], val[rt << 1 | 1]);
}
long long queryMin(int l, int r, int rt, int L, int R) {
  if (L <= l && r <= R) return val[rt];
  push_down(rt);
  int mid = (l + r) >> 1;
  long long ans = 1e16;
  if (L <= mid) ans = min(ans, queryMin(l, mid, rt << 1, L, R));
  if (R > mid) ans = min(ans, queryMin(mid + 1, r, rt << 1 | 1, L, R));
  return ans;
}
void update(int l, int r, int rt, int L, int R, long long x) {
  if (L <= l && r <= R) {
    lazy[rt] += x;
    val[rt] += x;
    return;
  }
  push_down(rt);
  int mid = (l + r) >> 1;
  if (L <= mid) update(l, mid, rt << 1, L, R, x);
  if (R > mid) update(mid + 1, r, rt << 1 | 1, L, R, x);
  val[rt] = min(val[rt << 1], val[rt << 1 | 1]);
}
bool ispar(int u, int v) {
  int k = dep[v] - dep[u];
  if (k < 0) return 0;
  int cur = v;
  long long ans = 0;
  for (int i = 0; i < 20; i++) {
    if ((k >> i) & 1) cur = par[cur][i];
  }
  return cur == u;
}
int main() {
  scanf("%d%d", &n, &m);
  for (int i = 1; i < n; i++) {
    scanf("%d%d%d", &u[i], &v[i], &w[i]);
    g[u[i]].push_back(make_pair(v[i], w[i]));
  }
  for (int i = n; i < 2 * n - 1; i++) {
    scanf("%d%d%d", &u[i], &v[i], &w[i]);
    disToRoot[u[i]] = w[i];
  }
  dfs(1, 1);
  for (int i = 1; i < 20; i++) {
    for (int j = 1; j <= n; j++) {
      par[j][i] = par[par[j][i - 1]][i - 1];
    }
  }
  build(1, n, 1);
  for (int i = 1; i <= m; i++) {
    int op, x, y;
    scanf("%d%d%d", &op, &x, &y);
    if (op == 1) {
      if (x < n) {
        update(1, n, 1, dfnL[v[x]], dfnR[v[x]], y - w[x]);
        w[x] = y;
      } else {
        update(1, n, 1, dfnL[u[x]], dfnL[u[x]], y - disToRoot[u[x]]);
        disToRoot[u[x]] = y;
      }
    }
    if (op == 2) {
      long long ans = queryMin(1, n, 1, dfnL[x], dfnR[x]) -
                      (queryMin(1, n, 1, dfnL[x], dfnL[x]) - disToRoot[x]) +
                      (queryMin(1, n, 1, dfnL[y], dfnL[y]) - disToRoot[y]);
      if (ispar(x, y)) {
        ans =
            min(ans, (queryMin(1, n, 1, dfnL[y], dfnL[y]) - disToRoot[y]) -
                         (queryMin(1, n, 1, dfnL[x], dfnL[x]) - disToRoot[x]));
      }
      printf("%lld\n", ans);
    }
  }
}

solution_5:
#include <bits/stdc++.h>
using namespace std;
const int N = 200123;
const int INF = 1e9;
struct Node {
  long long push;
  long long sum;
  long long mn;
};
Node t[10 * N];
int tin[N];
int tout[N];
int timer = 0;
int eda[2 * N], edb[2 * N], edc[2 * N];
vector<int> tr[N];
long long costup[N];
inline void setVal(int v, int l, int r, long long val) {
  t[v].push += val;
  t[v].mn += val;
  t[v].sum += val * (r - l + 1);
}
inline void push(int v, int l, int r) {
  int m = (l + r) >> 1;
  setVal(v * 2, l, m, t[v].push);
  setVal(v * 2 + 1, m + 1, r, t[v].push);
  t[v].push = 0;
}
void modify(int v, int l, int r, int lb, int rb, int add) {
  if (lb > r || rb < l) return;
  if (lb <= l && rb >= r) {
    setVal(v, l, r, add);
    return;
  }
  push(v, l, r);
  int m = (l + r) >> 1;
  modify(v * 2, l, m, lb, rb, add);
  modify(v * 2 + 1, m + 1, r, lb, rb, add);
  t[v].sum = t[v * 2].sum + t[v * 2 + 1].sum;
  t[v].mn = min(t[v * 2].mn, t[v * 2 + 1].mn);
}
void updMin(int v, int l, int r, int pos, int add) {
  if (l == r) {
    t[v].mn += add;
    return;
  }
  push(v, l, r);
  int m = (l + r) >> 1;
  if (pos <= m)
    updMin(v * 2, l, m, pos, add);
  else
    updMin(v * 2 + 1, m + 1, r, pos, add);
  t[v].sum = t[v * 2].sum + t[v * 2 + 1].sum;
  t[v].mn = min(t[v * 2].mn, t[v * 2 + 1].mn);
}
long long getSum(int v, int l, int r, int pos) {
  if (l == r) return t[v].sum;
  push(v, l, r);
  int m = (l + r) >> 1;
  if (pos <= m)
    return getSum(v * 2, l, m, pos);
  else
    return getSum(v * 2 + 1, m + 1, r, pos);
}
int getMin(int v, int l, int r, int lb, int rb) {
  if (lb > r || rb < l) return INF;
  if (lb <= l && rb >= r) return t[v].mn;
  push(v, l, r);
  int m = (l + r) >> 1;
  return min(getMin(v * 2, l, m, lb, rb), getMin(v * 2 + 1, m + 1, r, lb, rb));
}
void dfs(int v) {
  tin[v] = ++timer;
  for (int to : tr[v]) dfs(to);
  tout[v] = ++timer;
}
bool isPar(int a, int b) { return tin[a] <= tin[b] && tout[a] >= tout[b]; }
inline long long getSum(int v) { return v ? getSum(1, 1, timer, tin[v]) : 0; }
bool good[3 * N];
int main() {
  int n, q;
  scanf("%d%d", &n, &q);
  for (int i = 1; i <= 2 * n - 2; ++i) {
    scanf("%d%d%d", &eda[i], &edb[i], &edc[i]);
    if (edb[i] != 1)
      tr[eda[i]].push_back(edb[i]);
    else
      costup[eda[i]] = edc[i];
  }
  dfs(1);
  for (int i = 1; i <= n; ++i) good[tin[i]] = true;
  for (int i = 1; i <= timer; ++i)
    if (!good[i]) updMin(1, 1, timer, i, INF);
  for (int i = 1; i < n; ++i)
    modify(1, 1, timer, tin[edb[i]], tout[edb[i]], edc[i]);
  for (int i = n; i <= 2 * n - 2; ++i) updMin(1, 1, timer, tin[eda[i]], edc[i]);
  for (int i = 0; i < q; ++i) {
    int tp;
    scanf("%d", &tp);
    if (tp == 1) {
      int qi, qw;
      scanf("%d%d", &qi, &qw);
      if (edb[qi] == 1) {
        updMin(1, 1, timer, tin[eda[qi]], qw - costup[eda[qi]]);
        costup[eda[qi]] = qw;
      } else {
        modify(1, 1, timer, tin[edb[qi]], tout[edb[qi]], qw - edc[qi]);
        edc[qi] = qw;
      }
    } else {
      int u, v;
      scanf("%d%d", &u, &v);
      long long ans = 0;
      if (isPar(u, v)) {
        ans = getSum(v) - getSum(u);
      } else {
        ans = getSum(v) + getMin(1, 1, timer, tin[u], tout[u]) - getSum(u);
      }
      printf("%lld\n", ans);
    }
  }
  return 0;
}

solution_6:
#include <bits/stdc++.h>
using namespace std;
const int mx = 2e5 + 5;
struct node {
  int v;
  int u;
  long long w;
  int next;
} E[2 * mx];
int tot = 0, dfn = 0;
int head[mx], L[mx], R[mx];
long long lazy[mx << 4], T[mx << 4];
long long v[mx << 2];
long long dis[mx];
bool vis[mx];
void add(int u, int v, long long w) {
  tot++;
  E[tot].v = v;
  E[tot].w = w;
  E[tot].u = u;
  E[tot].next = head[u];
  head[u] = tot;
}
void dfs(int u, long long sum) {
  vis[u] = 1;
  int s = head[u];
  L[u] = ++dfn;
  v[dfn] = sum + dis[u];
  for (int i = head[u]; i; i = E[i].next) {
    long long w = E[i].w;
    if (!vis[E[i].v]) dfs(E[i].v, sum + w);
  }
  R[u] = ++dfn;
  v[dfn] = sum + dis[u];
}
void push_down(int rt) {
  if (lazy[rt]) {
    lazy[2 * rt] += lazy[rt];
    lazy[2 * rt | 1] += lazy[rt];
    T[2 * rt] += lazy[rt];
    T[2 * rt | 1] += lazy[rt];
    lazy[rt] = 0;
  }
}
void built(int rt, int L, int R) {
  if (L == R) {
    T[rt] = v[L];
    return;
  }
  built(2 * rt, L, (L + R) / 2);
  built(2 * rt | 1, (L + R) / 2 + 1, R);
  T[rt] = min(T[2 * rt], T[2 * rt | 1]);
}
void update(int rt, int L, int R, int l, int r, int v) {
  if (L >= l && R <= r) {
    T[rt] += v;
    lazy[rt] += v;
    return;
  }
  push_down(rt);
  if (l > (L + R) / 2)
    update(2 * rt | 1, (L + R) / 2 + 1, R, l, r, v);
  else if (r <= (L + R) / 2)
    update(2 * rt, L, (L + R) / 2, l, r, v);
  else {
    update(2 * rt, L, (L + R) / 2, l, (L + R) / 2, v);
    update(2 * rt | 1, (L + R) / 2 + 1, R, (L + R) / 2 + 1, r, v);
  }
  T[rt] = min(T[2 * rt], T[2 * rt | 1]);
}
long long query(int rt, int L, int R, int l, int r) {
  if (L >= l && R <= r) return T[rt];
  push_down(rt);
  if (l > (L + R) / 2)
    return query(2 * rt | 1, (L + R) / 2 + 1, R, l, r);
  else if (r <= (L + R) / 2)
    return query(2 * rt, L, (L + R) / 2, l, r);
  else
    return min(query(2 * rt, L, (L + R) / 2, l, (L + R) / 2),
               query(2 * rt | 1, (L + R) / 2 + 1, R, (L + R) / 2 + 1, r));
}
bool ischild(int u, int v) { return L[v] >= L[u] && R[v] <= R[u]; }
int main() {
  int n, q;
  scanf("%d%d", &n, &q);
  for (int i = 1; i < n; i++) {
    int u, v;
    long long w;
    scanf("%d%d%I64d", &u, &v, &w);
    add(u, v, w);
  }
  dis[1] = 0;
  for (int i = 1; i < n; i++) {
    int u, v;
    long long w;
    scanf("%d%d%I64d", &u, &v, &w);
    dis[u] = w;
    add(u, v, w);
  }
  dfs(1, 0);
  built(1, 1, dfn);
  while (q--) {
    int casei, x, y;
    scanf("%d%d%d", &casei, &x, &y);
    if (casei == 1) {
      if (x < n)
        update(1, 1, dfn, L[E[x].v], R[E[x].v], y - E[x].w);
      else {
        update(1, 1, dfn, L[E[x].u], L[E[x].u], y - E[x].w);
        update(1, 1, dfn, R[E[x].u], R[E[x].u], y - E[x].w);
        dis[E[x].u] = y;
      }
      E[x].w = y;
    } else {
      long long ans = 0;
      if (ischild(x, y))
        ans = query(1, 1, dfn, L[y], L[y]) - dis[y] -
              query(1, 1, dfn, L[x], L[x]) + dis[x];
      else
        ans = query(1, 1, dfn, L[x], R[x]) - query(1, 1, dfn, L[x], L[x]) +
              dis[x] + query(1, 1, dfn, L[y], L[y]) - dis[y];
      printf("%I64d\n", ans);
    }
  }
  return 0;
}

solution_7:
#include <bits/stdc++.h>
using namespace std;
#pragma GCC optimize("Ofast")
#pragma GCC target("avx,avx2,fma")
const long long N = 2e5 + 5, inf = 1e18;
vector<int> g[N];
long long a[N], p[N], b[N], tin[N], tout[N], tmr;
void dfs(int u, int par) {
  tin[u] = ++tmr;
  for (int v : g[u])
    if (v != par) {
      p[v] += p[u];
      dfs(v, u);
    }
  tout[u] = tmr;
}
bool is_anc(int u, int v) { return tin[u] <= tin[v] and tout[u] >= tout[v]; }
struct T {
  long long t[4 * N], lazy[4 * N];
  void prop(int i, int st, int en) {
    if (lazy[i]) {
      t[i] += lazy[i];
      if (st != en) {
        lazy[2 * i] += lazy[i];
        lazy[2 * i + 1] += lazy[i];
      }
      lazy[i] = 0;
    }
  }
  void update(int i, int st, int en, int l, int r, long long v) {
    prop(i, st, en);
    if (st > r or en < l) {
      return;
    }
    if (st >= l and en <= r) {
      lazy[i] = v;
      prop(i, st, en);
      return;
    }
    int mid = (st + en) / 2;
    update(2 * i, st, mid, l, r, v);
    update(2 * i + 1, mid + 1, en, l, r, v);
    t[i] = min(t[2 * i], t[2 * i + 1]);
  }
  long long query(int i, int st, int en, int l, int r) {
    prop(i, st, en);
    if (st > r or en < l) {
      return inf;
    }
    if (st >= l and en <= r) {
      return t[i];
    }
    int mid = (st + en) / 2;
    long long x = query(2 * i, st, mid, l, r);
    long long y = query(2 * i + 1, mid + 1, en, l, r);
    return min(x, y);
  }
} t[2];
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  int n, q;
  cin >> n >> q;
  int e[2 * n];
  for (int i = 1; i <= 2 * n - 2; i++) {
    int x, y, w;
    cin >> x >> y >> w;
    if (i <= n - 1) {
      g[x].push_back(y);
      a[y] = p[y] = w;
      e[i] = y;
    } else {
      b[x] = w;
      e[i] = x;
    }
  }
  dfs(1, 0);
  for (int i = 1; i <= n; i++) {
    t[0].update(1, 1, n, tin[i], tin[i], p[i]);
    t[1].update(1, 1, n, tin[i], tin[i], p[i] + b[i]);
  }
  while (q--) {
    int ty, x, y;
    cin >> ty >> x >> y;
    if (ty == 1) {
      int u = e[x];
      if (x <= n - 1) {
        t[0].update(1, 1, n, tin[u], tout[u], y - a[u]);
        t[1].update(1, 1, n, tin[u], tout[u], y - a[u]);
        a[u] = y;
      } else {
        t[1].update(1, 1, n, tin[u], tin[u], y - b[u]);
        b[u] = y;
      }
    }
    if (ty == 2) {
      long long ans, tmp1, tmp2;
      tmp1 = t[0].query(1, 1, n, tin[x], tin[x]);
      tmp2 = t[0].query(1, 1, n, tin[y], tin[y]);
      ans = t[1].query(1, 1, n, tin[x], tout[x]) - tmp1 + tmp2;
      if (is_anc(x, y)) {
        ans = min(ans, tmp2 - tmp1);
      }
      cout << ans << "\n";
    }
  }
}

solution_8:
#include <bits/stdc++.h>
using namespace std;
const int MaxN = 200003;
int n, q;
struct Edge {
  int u, v, w;
} edge[MaxN * 2];
vector<pair<int, int> > e[MaxN];
int fa[MaxN], dep[MaxN], sz[MaxN], id[MaxN], idx;
long long dist[MaxN], weight[MaxN];
void dfs(int x) {
  id[x] = ++idx;
  for (pair<int, int>& i : e[x]) {
    int v = i.first, w = i.second;
    dfs(v);
  }
}
void dfs2(int x) {
  sz[id[x]] = 1;
  for (pair<int, int>& i : e[x]) {
    int v = i.first, w = i.second;
    dist[id[v]] = dist[id[x]] + w;
    dfs2(v);
    sz[id[x]] += sz[id[v]];
  }
}
namespace MinSegTree {
long long mn[MaxN << 2], adds[MaxN << 2];
void build(int p, int l, int r) {
  if (l == r) {
    mn[p] = dist[l] + weight[l];
    adds[p] = 0;
    return;
  }
  int mid = (l + r) / 2;
  build(p * 2, l, mid);
  build(p * 2 + 1, mid + 1, r);
  mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
  adds[p] = 0;
}
inline void init() { build(1, 1, n); }
inline void pushdown(int p, int l, int r) {
  mn[p] += adds[p];
  if (l < r) {
    adds[p * 2] += adds[p];
    adds[p * 2 + 1] += adds[p];
  }
  adds[p] = 0;
}
inline void update(int p, int l, int r) {
  pushdown(p, l, r);
  if (l < r) {
    mn[p] = min(mn[p * 2] + adds[p * 2], mn[p * 2 + 1] + adds[p * 2 + 1]);
  }
}
void add(long long s, int p, int l, int r, int ll, int rr) {
  if (ll <= l && r <= rr) {
    adds[p] += s;
    return;
  }
  pushdown(p, l, r);
  int mid = (l + r) / 2;
  if (ll <= mid) add(s, p * 2, l, mid, ll, rr);
  if (rr > mid) add(s, p * 2 + 1, mid + 1, r, ll, rr);
  update(p, l, r);
}
long long query(int p, int l, int r, int ll, int rr) {
  if (ll <= l && r <= rr) {
    return mn[p] + adds[p];
  }
  pushdown(p, l, r);
  long long ret = 0x7f7f7f7f7f7f7f7fLL;
  int mid = (l + r) / 2;
  if (ll <= mid) ret = min(ret, query(p * 2, l, mid, ll, rr));
  if (rr > mid) ret = min(ret, query(p * 2 + 1, mid + 1, r, ll, rr));
  return ret;
}
}  // namespace MinSegTree
namespace DistSegTree {
long long s[MaxN << 2];
void build(int p, int l, int r) {
  if (l == r) {
    s[p] = dist[l];
    return;
  }
  int mid = (l + r) / 2;
  build(p * 2, l, mid);
  build(p * 2 + 1, mid + 1, r);
}
inline void init() { build(1, 1, n); }
inline void pushdown(int p) {
  s[p * 2] += s[p];
  s[p * 2 + 1] += s[p];
  s[p] = 0;
}
void add(int x, int p, int l, int r, int ll, int rr) {
  if (ll <= l && r <= rr) {
    s[p] += x;
    return;
  }
  pushdown(p);
  int mid = (l + r) / 2;
  if (ll <= mid) add(x, p * 2, l, mid, ll, rr);
  if (rr > mid) add(x, p * 2 + 1, mid + 1, r, ll, rr);
}
inline long long query(int x, int p, int l, int r) {
  if (l == r) return s[p];
  pushdown(p);
  int mid = (l + r) / 2;
  if (x <= mid)
    return query(x, p * 2, l, mid);
  else
    return query(x, p * 2 + 1, mid + 1, r);
}
}  // namespace DistSegTree
int main() {
  scanf("%d%d", &n, &q);
  for (int i = 1; i < n; ++i) {
    int u, v, w;
    scanf("%d%d%d", &u, &v, &w);
    edge[i].u = u, edge[i].v = v, edge[i].w = w;
    e[u].emplace_back(v, w);
  }
  fa[1] = 1, dep[1] = 0, dist[1] = 0, weight[1] = 0;
  dfs(1);
  dfs2(1);
  for (int i = n; i <= 2 * n - 2; ++i) {
    int u, v, w;
    scanf("%d%d%d", &u, &v, &w);
    edge[i].u = u, edge[i].v = v, edge[i].w = w;
    weight[id[u]] = w;
  }
  MinSegTree::init();
  DistSegTree::init();
  for (int i = 1; i <= q; ++i) {
    int type;
    scanf("%d", &type);
    if (type == 1) {
      int pos, x;
      scanf("%d%d", &pos, &x);
      if (pos < n) {
        int change = x - edge[pos].w;
        int l = id[edge[pos].v], r = l + sz[l] - 1;
        MinSegTree::add(change, 1, 1, n, l, r);
        DistSegTree::add(change, 1, 1, n, l, r);
        edge[pos].w = x;
      } else {
        int change = x - edge[pos].w;
        int l = id[edge[pos].u], r = l + sz[l] - 1;
        MinSegTree::add(change, 1, 1, n, l, l);
        edge[pos].w = x;
      }
    } else {
      int u, v;
      scanf("%d%d", &u, &v);
      int l = id[u], r = l + sz[l] - 1;
      long long ans;
      if (l <= id[v] && id[v] <= r) {
        ans = DistSegTree::query(id[v], 1, 1, n) -
              DistSegTree::query(id[u], 1, 1, n);
      } else {
        ans = MinSegTree::query(1, 1, n, l, r) -
              DistSegTree::query(id[u], 1, 1, n) +
              DistSegTree::query(id[v], 1, 1, n);
      }
      printf("%lld\n", ans);
    }
  }
  return 0;
}

solution_9:
#include <bits/stdc++.h>
using namespace std;
const int maxn = 5e5 + 20, maxm = 1e6 + 10;
const int INF = 0x3f3f3f3f;
const long long mod = 1e9 + 7;
const double PI = acos(-1.0);
int casn, n, m, k, nume;
int u[maxn], v[maxn], nx[maxn], head[maxn];
long long w[maxn];
void add(int a, int b, int c) {
  v[++nume] = b;
  nx[nume] = head[a], w[nume] = c;
  u[nume] = a;
  head[a] = nume;
}
int dfn, in[maxn], reid[maxn], out[maxn];
long long to1[maxn], dis[maxn];
void dfs(int now, long long s) {
  in[now] = ++dfn;
  reid[dfn] = now;
  for (int i = head[now]; i; i = nx[i])
    if (v[i] != 1) dfs(v[i], s + w[i]);
  out[now] = dfn, dis[now] = s + to1[now];
}
long long mn[maxn << 2 | 1], f[maxn << 2 | 1];
void down(int now) {
  if (f[now]) {
    mn[now << 1] += f[now];
    mn[now << 1 | 1] += f[now];
    f[now << 1] += f[now];
    f[now << 1 | 1] += f[now];
    f[now] = 0;
  }
}
void maketree(int s, int t, int now = 1) {
  mn[now] = dis[reid[s]];
  if (s == t) return;
  maketree(s, (s + t) / 2, now << 1);
  maketree((s + t) / 2 + 1, t, now << 1 | 1);
  mn[now] = min(mn[now << 1], mn[now << 1 | 1]);
}
void update(int s, int t, long long x, int l, int r, int now = 1) {
  if (s <= l && t >= r) {
    mn[now] += x, f[now] += x;
    return;
  }
  down(now);
  if (s <= (l + r) / 2) update(s, t, x, l, (l + r) / 2, now << 1);
  if (t > (l + r) / 2) update(s, t, x, (l + r) / 2 + 1, r, now << 1 | 1);
  mn[now] = min(mn[now << 1], mn[now << 1 | 1]);
}
long long query(int s, int t, int l, int r, int now = 1) {
  if (s <= l && t >= r) return mn[now];
  down(now);
  long long ret = 1e18;
  if (s <= (l + r) / 2) ret = query(s, t, l, (l + r) / 2, now << 1);
  if (t > (l + r) / 2)
    ret = min(query(s, t, (l + r) / 2 + 1, r, now << 1 | 1), ret);
  return ret;
}
int intree(int a, int b) { return in[b] <= in[a] && out[b] >= out[a]; }
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n >> m;
  for (int i = 1; i <= n - 1; ++i) {
    int a, b, c;
    cin >> a >> b >> c;
    add(a, b, c);
  }
  for (int i = 1; i <= n - 1; ++i) {
    int a, b, c;
    cin >> a >> b >> c;
    add(a, b, c);
    to1[a] = c;
  }
  dfs(1, 0);
  maketree(1, n, 1);
  while (m--) {
    int a, b, c;
    cin >> a >> b >> c;
    if (a == 1) {
      if (b <= n - 1) {
        update(in[v[b]], out[v[b]], c - w[b], 1, n);
        w[b] = c;
      } else {
        update(in[u[b]], in[u[b]], c - to1[u[b]], 1, n);
        to1[u[b]] = c;
      }
    } else {
      if (intree(c, b)) {
        cout << query(in[c], in[c], 1, n) - query(in[b], in[b], 1, n) - to1[c] +
                    to1[b]
             << '\n';
      } else {
        cout << query(in[b], out[b], 1, n) + query(in[c], in[c], 1, n) -
                    to1[c] - query(in[b], in[b], 1, n) + to1[b]
             << '\n';
      }
    }
  }
  return 0;
}

solution_10:
#include <bits/stdc++.h>
using namespace std;
struct node {
  int q, p, lazy;
  void merge(struct node &l, struct node &r) { q = min(l.q, r.q); }
};
struct edge_ {
  int a, b, c;
};
int TIME;
int sr[200010], en[200010], dist[200010];
bool visit[200010];
void lazy(struct node *st, int si, int ss, int se) {
  if (st[si].lazy == 0) return;
  st[si].q += st[si].lazy;
  st[si].p += st[si].lazy;
  if (ss != se) {
    st[si * 2 + 1].lazy += st[si].lazy;
    st[si * 2 + 2].lazy += st[si].lazy;
  }
  st[si].lazy = 0;
}
void update1(struct node *st, int ss, int se, int us, int ue, int si, int val) {
  lazy(st, si, ss, se);
  if (ss > se || ss > ue || se < us) return;
  if (ss >= us && se <= ue) {
    st[si].q += val;
    st[si].p += val;
    if (ss != se) {
      st[si * 2 + 1].lazy += val;
      st[si * 2 + 2].lazy += val;
    }
    return;
  }
  int mid = ss + (se - ss) / 2;
  update1(st, ss, mid, us, ue, 2 * si + 1, val);
  update1(st, mid + 1, se, us, ue, 2 * si + 2, val);
  st[si].merge(st[2 * si + 1], st[2 * si + 2]);
}
void update2(struct node *st, int ss, int se, int index, int si, int val) {
  lazy(st, si, ss, se);
  if (ss > index || se < index) return;
  if (ss == se) {
    st[si].q += val;
    return;
  }
  int mid = ss + (se - ss) / 2;
  update2(st, ss, mid, index, 2 * si + 1, val);
  update2(st, mid + 1, se, index, 2 * si + 2, val);
  st[si].merge(st[2 * si + 1], st[2 * si + 2]);
}
struct node query1(struct node *st, int ss, int se, int index, int si) {
  struct node result;
  lazy(st, si, ss, se);
  if (ss == se) return st[si];
  int mid = ss + (se - ss) / 2;
  if (index > mid) return query1(st, mid + 1, se, index, 2 * si + 2);
  if (index <= mid) return query1(st, ss, mid, index, 2 * si + 1);
}
struct node query2(struct node *st, int ss, int se, int qs, int qe, int si) {
  struct node result;
  lazy(st, si, ss, se);
  if (ss >= qs && se <= qe) return st[si];
  int mid = ss + (se - ss) / 2;
  if (qs > mid) return query2(st, mid + 1, se, qs, qe, 2 * si + 2);
  if (qe <= mid) return query2(st, ss, mid, qs, qe, 2 * si + 1);
  struct node l = query2(st, ss, mid, qs, qe, 2 * si + 1);
  struct node r = query2(st, mid + 1, se, qs, qe, 2 * si + 2);
  result.merge(l, r);
  return result;
}
void constructSTUtil(struct node *st, int ss, int se, int si) {
  if (ss > se) return;
  if (ss == se) {
    st[si].p = 0;
    st[si].q = 0;
    st[si].lazy = 0;
    return;
  }
  int mid = (ss + se) / 2;
  constructSTUtil(st, ss, mid, si * 2 + 1);
  constructSTUtil(st, mid + 1, se, si * 2 + 2);
  st[si].merge(st[si * 2 + 1], st[si * 2 + 2]);
  st[si].lazy = 0;
}
struct node *constructST(int n) {
  int x = (int)(ceil(log2(n)));
  int size = 2 * pow(2, x) - 1;
  struct node *st = new struct node[size];
  constructSTUtil(st, 0, n - 1, 0);
  return st;
}
void dfs(vector<int> v[], int n = 0, int d = 0) {
  visit[n] = true;
  sr[n] = TIME;
  TIME++;
  dist[n] = d;
  for (int i = 0; i < v[n].size(); i++) {
    int k = v[n][i];
    if (visit[k]) continue;
    dfs(v, k, d + 1);
  }
  en[n] = TIME - 1;
}
int main() {
  int n, q;
  scanf("%d%d", &n, &q);
  vector<int> v[n];
  struct edge_ edge[2 * n];
  for (int i = 0; i < 2 * n - 2; i++) {
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);
    a--, b--;
    edge[i].a = a, edge[i].b = b, edge[i].c = c;
    v[a].push_back(b);
  }
  TIME = 0;
  memset(visit, false, sizeof visit);
  dfs(v);
  struct node *st = constructST(n);
  for (int i = 0; i < (2 * n - 2); i++) {
    if (i < (n - 1))
      update1(st, 0, n - 1, sr[edge[i].b], en[edge[i].b], 0, edge[i].c);
    else
      update2(st, 0, n - 1, sr[edge[i].a], 0, edge[i].c);
  }
  while (q--) {
    int a, i, w;
    scanf("%d%d%d", &a, &i, &w);
    if (a == 1) {
      i--;
      if (i < (n - 1))
        update1(st, 0, n - 1, sr[edge[i].b], en[edge[i].b], 0, w - edge[i].c);
      else
        update2(st, 0, n - 1, sr[edge[i].a], 0, w - edge[i].c);
      edge[i].c = w;
    } else {
      int u = i, v = w;
      u--, v--;
      if (sr[u] <= sr[v] && en[u] >= en[v])
        printf("%d\n", query1(st, 0, n - 1, sr[v], 0).p -
                           query1(st, 0, n - 1, sr[u], 0).p);
      else
        printf("%d\n", query1(st, 0, n - 1, sr[v], 0).p +
                           query2(st, 0, n - 1, sr[u], en[u], 0).q -
                           query1(st, 0, n - 1, sr[u], 0).p);
    }
  }
  return 0;
}

