#include <bits/stdc++.h>
using namespace std;
int n, q, u[404000], v[404000], w[404000], bak[404000] = {0};
struct R {
  int to, val, nex;
} r[202000];
int hea[202000] = {0}, cnt = 1;
int df1[202000], df2[202000], dft = 0;
long long an, ans;
namespace D {
long long d[202000];
void RE() { memset(d, 0, sizeof d); }
void add(int x, int v) {
  for (; x <= n; x += x & (-x)) d[x] += v;
}
void A(int st, int en, int val) {
  add(st, val);
  add(en + 1, -val);
}
long long Q(int x) {
  long long t = 0;
  for (; x > 0; x -= x & -x) t += d[x];
  return t;
}
}  // namespace D
namespace tr {
long long mn[808000], laz[808000];
void U(int x) { mn[x] = min(mn[x << 1], mn[x << 1 | 1]); }
void D(int x) {
  if (!laz[x]) return;
  mn[x << 1] += laz[x];
  laz[x << 1] += laz[x];
  mn[x << 1 | 1] += laz[x];
  laz[x << 1 | 1] += laz[x];
  U(x);
  laz[x] = 0;
}
void B(int x, int l, int r) {
  laz[x] = 0;
  if (l == r) {
    mn[x] = D::Q(l) + bak[l];
    return;
  }
  int mid = (l + r) >> 1;
  B(x << 1, l, mid);
  B(x << 1 | 1, mid + 1, r);
  U(x);
}
void RE() { B(1, 1, n); }
long long que(int x, int l, int r, int st, int en) {
  if (st > en) return (1e16);
  if (l == st && r == en) return mn[x];
  D(x);
  int mid = (l + r) >> 1;
  return min(que(x << 1, l, mid, max(st, l), min(en, mid)),
             que(x << 1 | 1, mid + 1, r, max(st, mid + 1), min(en, r)));
}
long long Q(int st, int en) { return que(1, 1, n, st, en); }
void chg(int x, int l, int r, int st, int en, int val) {
  if (st > en) return;
  if (l == st && r == en) {
    mn[x] += val;
    laz[x] += val;
    return;
  }
  D(x);
  int mid = (l + r) >> 1;
  chg(x << 1, l, mid, max(st, l), min(en, mid), val);
  chg(x << 1 | 1, mid + 1, r, max(st, mid + 1), min(en, r), val);
  U(x);
}
void C(int st, int en, int val) { chg(1, 1, n, st, en, val); }
}  // namespace tr
void dfs(int x) {
  df1[x] = ++dft;
  int y;
  for (int i = hea[x]; i > 0; i = r[i].nex) {
    y = r[i].to;
    dfs(y);
  }
  df2[x] = dft;
}
int main() {
  D::RE();
  scanf("%d%d", &n, &q);
  int x, y, z;
  for (int i = 1; i < n; i++) {
    scanf("%d%d%d", &u[i], &v[i], &w[i]);
    r[++cnt] = (R){v[i], w[i], hea[u[i]]};
    hea[u[i]] = cnt;
  }
  dfs(1);
  for (int i = n; i <= n * 2 - 2; i++) {
    scanf("%d%d%d", &u[i], &v[i], &w[i]);
    bak[df1[u[i]]] = w[i];
  }
  for (int i = 1; i < n; i++) {
    D::A(df1[v[i]], df2[v[i]], w[i]);
  }
  tr::RE();
  for (int t; q--;) {
    scanf("%d%d%d", &t, &x, &y);
    if (t == 1) {
      if (x < n) {
        D::A(df1[v[x]], df2[v[x]], y - w[x]);
        tr::C(df1[v[x]], df2[v[x]], y - w[x]);
        w[x] = y;
      } else {
        tr::C(df1[u[x]], df1[u[x]], y - bak[df1[u[x]]]);
        bak[df1[u[x]]] = y;
      }
    } else {
      if (df1[x] <= df1[y] && df2[x] >= df2[y]) {
        ans = D::Q(df1[y]) - D::Q(df1[x]);
      } else {
        ans = tr::Q(df1[x], df2[x]) - D::Q(df1[x]) + D::Q(df1[y]);
      }
      printf("%I64d\n", ans);
    }
  }
}

solution_12:
#include <bits/stdc++.h>
using namespace std;
const long long int N = 4e5 + 2, inf = 1e12 + 7;
vector<pair<int, int> > vec[N];
pair<int, pair<int, int> > edg[N];
long long int n, dis[N], dis2[N], st[N], ed[N];
long long int T[2 * N], lzy[2 * N], tim;
void dfs(int u, int pr) {
  st[u] = ++tim;
  for (auto x : vec[u]) {
    int v = x.first, w = x.second;
    if (v == pr) continue;
    dis[v] = dis[u] + w;
    dfs(v, u);
  }
  ed[u] = tim;
}
void push_down(int nod, int lo, int hi) {
  T[nod] += lzy[nod];
  if (lo != hi) {
    lzy[2 * nod] += lzy[nod];
    lzy[2 * nod + 1] += lzy[nod];
  }
  lzy[nod] = 0;
}
void updt(int nod, int lo, int hi, int l, int r, int vl) {
  if (lzy[nod]) push_down(nod, lo, hi);
  if (hi < l || lo > r || lo > hi) return;
  if (lo >= l && hi <= r) {
    T[nod] += vl;
    if (lo != hi) {
      lzy[2 * nod] += vl;
      lzy[2 * nod + 1] += vl;
    }
    return;
  }
  int md = (lo + hi) >> 1;
  updt(2 * nod, lo, md, l, r, vl);
  updt(2 * nod + 1, md + 1, hi, l, r, vl);
  T[nod] = min(T[2 * nod], T[2 * nod + 1]);
}
long long int qry(int nod, int lo, int hi, int l, int r) {
  if (lzy[nod]) push_down(nod, lo, hi);
  if (hi < l || lo > r || lo > hi) return inf;
  if (lo >= l && hi <= r) return T[nod];
  int md = (lo + hi) >> 1;
  return min(qry(2 * nod, lo, md, l, r), qry(2 * nod + 1, md + 1, hi, l, r));
}
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  int tc = 1, t = 0;
  while (tc--) {
    int q;
    cin >> n >> q;
    for (int i = 1; i < n; i++) {
      int u, v, c;
      cin >> u >> v >> c;
      vec[u].push_back(make_pair(v, c));
      edg[i] = make_pair(u, make_pair(v, c));
    }
    for (int i = n; i < n + n - 1; i++) {
      int u, v, c;
      cin >> u >> v >> c;
      edg[i] = make_pair(u, make_pair(v, c));
      dis2[u] = c;
    }
    dfs(1, -1);
    for (int i = 1; i <= n; i++) updt(1, 1, n, st[i], st[i], dis[i] + dis2[i]);
    while (q--) {
      int typ;
      cin >> typ;
      if (typ == 1) {
        int id, w;
        cin >> id >> w;
        int u = edg[id].first, v = edg[id].second.first;
        int c = edg[id].second.second;
        if (id < n) {
          updt(1, 1, n, st[v], ed[v], -c);
          updt(1, 1, n, st[v], ed[v], w);
          edg[id].second.second = w;
        } else {
          updt(1, 1, n, st[u], st[u], -c);
          updt(1, 1, n, st[u], st[u], w);
          edg[id].second.second = w;
          dis2[u] = w;
        }
      } else {
        int u, v;
        cin >> u >> v;
        if (st[v] >= st[u] && ed[u] >= ed[v]) {
          cout << qry(1, 1, n, st[v], st[v]) - qry(1, 1, n, st[u], st[u]) +
                      dis2[u] - dis2[v]
               << "\n";
        } else {
          long long int rs = qry(1, 1, n, st[u], ed[u]);
          rs -= qry(1, 1, n, st[u], st[u]);
          rs += qry(1, 1, n, st[v], st[v]);
          rs += dis2[u] - dis2[v];
          cout << rs << "\n";
        }
      }
    }
  }
  return 0;
}

solution_13:
#include <bits/stdc++.h>
using namespace std;
inline int min(int a, int b) { return a < b ? a : b; }
inline int read() {
  int s = 0, f = 1;
  char ch = getchar();
  while (ch < '0' || ch > '9') {
    if (ch == '-') f = -1;
    ch = getchar();
  }
  while (ch >= '0' && ch <= '9') s = s * 10 + ch - '0', ch = getchar();
  return s * f;
}
const int maxn = 8e5 + 10;
int n, q, tot, head[maxn], xx[maxn << 1], yy[maxn << 1];
struct data {
  int to, next, w;
} edge[maxn << 1];
int fa[maxn], sz[maxn], top[maxn], dep[maxn], son[maxn];
int seg[maxn << 2], w[maxn], ww[maxn], kkk;
int id[maxn], cnt, bian[maxn], num[maxn], ANS, d[maxn];
int LCA(int x, int y) {
  while (top[x] != top[y]) {
    if (dep[top[x]] < dep[top[y]]) swap(x, y);
    x = fa[top[x]];
  }
  if (dep[x] > dep[y]) swap(x, y);
  return x;
}
inline void pushup(int rt) { seg[rt] = seg[rt << 1] + seg[rt << 1 | 1]; }
void change(int rt, int lb, int rb, int kkk, int k) {
  if (kkk > rb || kkk < lb) return;
  if (lb == rb) {
    seg[rt] = k;
    return;
  }
  int mid = (lb + rb) >> 1;
  change(rt << 1, lb, mid, kkk, k), change(rt << 1 | 1, mid + 1, rb, kkk, k);
  pushup(rt);
}
int ask(int rt, int lb, int rb, int l, int r) {
  if (lb > r || l > rb) return 0;
  if (l <= lb && r >= rb) return seg[rt];
  int mid = (lb + rb) >> 1;
  return ask(rt << 1, lb, mid, l, r) + ask(rt << 1 | 1, mid + 1, rb, l, r);
}
void built(int rt, int lb, int rb) {
  if (lb == rb) {
    seg[rt] = w[lb];
    return;
  }
  int mid = (lb + rb) >> 1;
  built(rt << 1, lb, mid), built(rt << 1 | 1, mid + 1, rb);
  pushup(rt);
}
void dfs1(int x, int f, int Dep) {
  dep[x] = Dep;
  sz[x] = 1;
  fa[x] = f;
  int maxs = -1;
  for (int i = head[x]; i; i = edge[i].next) {
    int y = edge[i].to;
    dfs1(y, x, Dep + 1);
    sz[x] += sz[y];
    ww[y] = edge[i].w;
    if (sz[y] > maxs) maxs = sz[y], son[x] = y;
  }
}
void dfs2(int x, int Top) {
  top[x] = Top;
  id[x] = ++cnt;
  w[cnt] = ww[x];
  if (!son[x]) return;
  dfs2(son[x], Top);
  for (int i = head[x]; i; i = edge[i].next) {
    int y = edge[i].to;
    if (y == son[x]) continue;
    dfs2(y, y);
  }
}
int querysum(int x, int y) {
  int ans = 0;
  while (top[x] != top[y]) {
    if (dep[top[x]] < dep[top[y]]) swap(x, y);
    ans += ask(1, 1, n, id[top[x]], id[x]);
    x = fa[top[x]];
  }
  if (dep[x] > dep[y]) swap(x, y);
  if (x != y) ans += ask(1, 1, n, id[x] + 1, id[y]);
  return ans;
}
void dfsk(int x) {
  d[x] += bian[x];
  for (int i = head[x]; i; i = edge[i].next) {
    int y = edge[i].to;
    d[y] = d[x] + edge[i].w - bian[x];
    if (d[y] >= kkk) continue;
    dfsk(y);
    kkk = min(kkk, d[y]);
  }
}
int query(int x, int y) {
  int k = LCA(x, y);
  if (k == x)
    return querysum(x, y);
  else {
    kkk = bian[x];
    d[x] = 0;
    dfsk(x);
    return querysum(1, y) + kkk;
  }
}
inline void make(int u, int v, int w) {
  edge[++tot] = (data){v, head[u], w};
  head[u] = tot;
}
int main() {
  n = read(), q = read();
  for (int i = 1; i < n; i++) {
    xx[i] = read(), yy[i] = read();
    int z = read();
    make(xx[i], yy[i], z);
  }
  for (int i = 1; i < n; i++) {
    int x = read(), y = read(), z = read();
    num[n - 1 + i] = max(x, y);
    bian[max(x, y)] = z;
  }
  dfs1(1, 0, 1);
  dfs2(1, 1);
  built(1, 1, n);
  for (int i = 1; i <= q; i++) {
    int opt = read(), x = read(), y = read();
    if (opt == 1) {
      if (x > n - 1)
        bian[num[x]] = y;
      else {
        change(1, 1, n, id[edge[x].to], y);
        edge[x].w = y;
      }
    }
    if (opt == 2) printf("%d\n", query(x, y));
  }
  return 0;
}

solution_14:
#include <bits/stdc++.h>
using namespace std;
const int maxn = 4e5 + 10;
struct edge {
  int u, v, d;
} edges[maxn];
int n, q, back[maxn], front[maxn], dist[maxn], t, tin[maxn], tout[maxn];
vector<pair<int, int> > grafo[maxn];
long long tree[4 * maxn], lazy[4 * maxn];
void flush(int node, int l, int r) {
  if (!lazy[node]) return;
  tree[node] += lazy[node];
  if (l != r) {
    lazy[2 * node] += lazy[node];
    lazy[2 * node + 1] += lazy[node];
  }
  lazy[node] = 0;
}
void update(int node, int tl, int tr, int l, int r, long long v) {
  flush(node, tl, tr);
  if (tl > r or tr < l) return;
  if (tl >= l and tr <= r) {
    lazy[node] = v;
    flush(node, tl, tr);
    return;
  }
  int mid = (tl + tr) >> 1;
  update(2 * node, tl, mid, l, r, v);
  update(2 * node + 1, mid + 1, tr, l, r, v);
  tree[node] = min(tree[2 * node], tree[2 * node + 1]);
}
long long query(int node, int tl, int tr, int l, int r) {
  flush(node, tl, tr);
  if (tl > r or tr < l) return 10000000000000000;
  if (tl >= l and tr <= r) return tree[node];
  int mid = (tl + tr) >> 1;
  return min(query(2 * node, tl, mid, l, r),
             query(2 * node + 1, mid + 1, tr, l, r));
}
void dfs(int u, int p, long long d) {
  tin[u] = ++t;
  for (auto v : grafo[u]) {
    if (v.first == p) continue;
    dfs(v.first, u, d + v.second);
  }
  update(1, 1, n, tin[u], tin[u], d + dist[u]);
  tout[u] = t;
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  cout.tie(NULL);
  cin >> n >> q;
  for (int i = 1; i < n; i++) {
    int u, v, d;
    cin >> u >> v >> d;
    grafo[u].push_back({v, d});
    edges[i] = {u, v, d};
  }
  for (int i = n; i <= 2 * n - 2; i++) {
    int u, v, d;
    cin >> u >> v >> d;
    edges[i] = {u, v, d};
    dist[u] = d;
  }
  dfs(1, 0, 0);
  while (q--) {
    int op;
    cin >> op;
    if (op == 1) {
      int id, d;
      cin >> id >> d;
      if (id < n) {
        int v = edges[id].v;
        update(1, 1, n, tin[v], tout[v], -edges[id].d);
        update(1, 1, n, tin[v], tout[v], d);
        edges[id].d = d;
      } else {
        int u = edges[id].u;
        update(1, 1, n, tin[u], tin[u], -dist[u]);
        update(1, 1, n, tin[u], tin[u], d);
        dist[u] = d;
      }
    } else {
      int u, v;
      cin >> u >> v;
      if (tin[v] >= tin[u] and tout[u] >= tout[v]) {
        cout << -query(1, 1, n, tin[u], tin[u]) +
                    query(1, 1, n, tin[v], tin[v]) + dist[u] - dist[v]
             << "\n";
      } else {
        cout << query(1, 1, n, tin[u], tout[u]) -
                    query(1, 1, n, tin[u], tin[u]) +
                    query(1, 1, n, tin[v], tin[v]) + dist[u] - dist[v]
             << "\n";
      }
    }
  }
  return 0;
}

solution_15:
#include <bits/stdc++.h>
using namespace std;
const int maxn = 2e5 + 100;
int n, q, tin[maxn], tout[maxn], timer, v[maxn * 2], u[maxn * 2], w[maxn * 2],
    cur[maxn], up[maxn];
vector<pair<int, long long> > adj[maxn];
long long sum[maxn * 4], lazy[maxn * 4], mn[maxn * 4];
void dfs(int v) {
  tin[v] = timer++;
  for (auto to : adj[v])
    if (to.first != 1) dfs(to.first);
  tout[v] = timer;
}
void upd(int id, int l, int r, long long val) {
  sum[id] += (long long)(r - l) * val;
  mn[id] += val;
  lazy[id] += val;
}
void shift(int id, int l, int r) {
  int mid = (l + r) / 2;
  upd(id * 2, l, mid, lazy[id]);
  upd(id * 2 + 1, mid, r, lazy[id]);
  lazy[id] = 0;
}
void modify(int first, int second, long long val, int id = 1, int l = 0,
            int r = n) {
  if (l >= second || r <= first) return;
  if (l >= first && r <= second) {
    upd(id, l, r, val);
    return;
  }
  shift(id, l, r);
  int mid = (l + r) / 2;
  modify(first, second, val, id * 2, l, mid);
  modify(first, second, val, id * 2 + 1, mid, r);
  sum[id] = sum[id * 2] + sum[id * 2 + 1];
  mn[id] = min(mn[id * 2], mn[id * 2 + 1]);
}
void modify_mn(int pos, int val, int id = 1, int l = 0, int r = n) {
  if (r - l < 2) {
    mn[id] += val;
    return;
  }
  shift(id, l, r);
  int mid = (l + r) / 2;
  if (pos < mid)
    modify_mn(pos, val, id * 2, l, mid);
  else
    modify_mn(pos, val, id * 2 + 1, mid, r);
  mn[id] = min(mn[id * 2], mn[id * 2 + 1]);
}
long long toroot(int pos, int id = 1, int l = 0, int r = n) {
  if (r - l < 2) return sum[id];
  shift(id, l, r);
  int mid = (l + r) / 2;
  if (pos < mid)
    return toroot(pos, id * 2, l, mid);
  else
    return toroot(pos, id * 2 + 1, mid, r);
}
long long get_mn(int first, int second, int id = 1, int l = 0, int r = n) {
  if (l >= second || r <= first) return LLONG_MAX;
  if (l >= first && r <= second) return mn[id];
  int mid = (l + r) / 2;
  shift(id, l, r);
  return min(get_mn(first, second, id * 2, l, mid),
             get_mn(first, second, id * 2 + 1, mid, r));
}
int main() {
  ios_base::sync_with_stdio(false), cin.tie(0);
  cin >> n >> q;
  for (int i = 1; i <= n * 2 - 2; i++) {
    cin >> v[i] >> u[i] >> w[i];
    adj[v[i]].push_back({u[i], w[i]});
    if (i <= n - 1)
      cur[u[i]] = w[i];
    else
      up[v[i]] = w[i];
  }
  dfs(1);
  for (int i = 2; i <= n; i++) modify(tin[i], tout[i], cur[i]);
  for (int i = 2; i <= n; i++) modify_mn(tin[i], up[i]);
  while (q--) {
    int type, a, b;
    cin >> type >> a >> b;
    if (type == 1) {
      if (a <= n - 1) {
        modify(tin[u[a]], tout[u[a]], b - cur[u[a]]);
        cur[u[a]] = b;
      } else {
        modify_mn(tin[v[a]], b - up[v[a]]);
        up[v[a]] = b;
      }
    } else {
      if (tin[a] <= tin[b] && tout[a] >= tout[b])
        cout << toroot(tin[b]) - toroot(tin[a]) << "\n";
      else
        cout << get_mn(tin[a], tout[a]) - toroot(tin[a]) + toroot(tin[b])
             << "\n";
    }
  }
  return 0;
}

