#include <bits/stdc++.h>
using namespace std;
long long spf[301];
long long fac[301];
void sieve() {
  spf[1] = 1;
  for (long long i = 2; i < 301; i++) spf[i] = i;
  for (long long i = 4; i < 301; i += 2) spf[i] = 2;
  for (long long i = 3; i * i < 301; i++) {
    if (spf[i] == i) {
      for (long long j = i * i; j < 301; j += i)
        if (spf[j] == j) spf[j] = i;
    }
  }
}
map<long long, long long> getfactor(long long a) {
  map<long long, long long> m;
  while (a > 1) {
    m[spf[a]]++;
    a /= spf[a];
  }
  return m;
}
long long power(long long x, long long y, long long p) {
  long long res = 1;
  if (x == 0) return 0;
  while (y > 0) {
    if (y & 1) res = (res * x);
    y = y >> 1;
    x = (x * x);
  }
  return res;
}
long long gcd(long long a, long long b) {
  if (a == 0) return b;
  return gcd(b % a, a);
}
long long inverse(long long a, long long p) { return power(a, p - 2, p); }
long long ncr(long long n, long long r, long long p) {
  if (r > n) return 0;
  if (r == 0) return 1;
  return (fac[n] * inverse(fac[r], p) % p * inverse(fac[n - r], p) % p) % p;
}
long long seg[4000009] = {0}, lazy[4000009] = {0};
void push(long long v) {
  seg[v * 2] += lazy[v];
  seg[v * 2 + 1] += lazy[v];
  lazy[v * 2] += lazy[v];
  lazy[v * 2 + 1] += lazy[v];
  lazy[v] = 0;
}
void update(long long v, long long l, long long r, long long posl,
            long long posr, long long val) {
  if (l >= posl && r <= posr) {
    seg[v] += val;
    lazy[v] += val;
    return;
  } else if (l > posr || r < posl)
    return;
  push(v);
  long long mid = (l + r) / 2;
  update(v * 2, l, mid, posl, posr, val);
  update(v * 2 + 1, mid + 1, r, posl, posr, val);
  seg[v] = min(seg[v * 2], seg[v * 2 + 1]);
}
long long query(long long v, long long l, long long r, long long posl,
                long long posr) {
  if (l >= posl && r <= posr)
    return seg[v];
  else if (l > posr || r < posl)
    return 1e18;
  push(v);
  long long mid = (l + r) / 2;
  return min(query(v * 2, l, mid, posl, posr),
             query(v * 2 + 1, mid + 1, r, posl, posr));
}
vector<long long> v[200001];
long long back[200001] = {0};
long long normal[200001] = {0};
long long insert[200001] = {0};
long long out[200001] = {0};
long long val = 0;
void dfs(long long cur) {
  val++;
  insert[cur] = val;
  for (auto it : v[cur]) dfs(it);
  val++;
  out[cur] = val;
}
bool ances(long long u, long long v) {
  if (insert[u] <= insert[v] && out[u] >= out[v])
    return true;
  else
    return false;
}
void solve() {
  long long n, q;
  cin >> n >> q;
  map<long long, long long> m;
  for (long long i = 1; i <= n - 1; i++) {
    long long x, y, w;
    cin >> x >> y >> w;
    v[x].push_back(y);
    normal[y] = w;
    m[i] = y;
  }
  for (long long i = 1; i <= n - 1; i++) {
    long long x, y, w;
    cin >> x >> y >> w;
    back[x] = w;
    m[i + n - 1] = x;
  }
  dfs(1);
  for (long long i = 1; i <= n - 1; i++) {
    update(1, 1, 2 * n, insert[m[i]], out[m[i]], normal[m[i]]);
  }
  for (long long i = 1; i <= n - 1; i++) {
    update(1, 1, 2 * n, insert[m[i + n - 1]], insert[m[i + n - 1]],
           back[m[i + n - 1]]);
    update(1, 1, 2 * n, out[m[i + n - 1]], out[m[i + n - 1]],
           back[m[i + n - 1]]);
  }
  while (q--) {
    long long t;
    cin >> t;
    if (t == 1) {
      long long i, w;
      cin >> i >> w;
      if (i <= n - 1) {
        long long temp = normal[m[i]];
        temp = w - temp;
        normal[m[i]] = w;
        update(1, 1, 2 * n, insert[m[i]], out[m[i]], temp);
      } else {
        long long temp = back[m[i]];
        temp = w - temp;
        back[m[i]] = w;
        update(1, 1, 2 * n, insert[m[i]], insert[m[i]], temp);
        update(1, 1, 2 * n, out[m[i]], out[m[i]], temp);
      }
    } else {
      long long u, v;
      cin >> u >> v;
      if (ances(u, v)) {
        cout << query(1, 1, 2 * n, insert[v], insert[v]) -
                    query(1, 1, 2 * n, insert[u], insert[u]) + back[u] - back[v]
             << '\n';
      } else {
        cout << query(1, 1, 2 * n, insert[u], out[u]) +
                    query(1, 1, 2 * n, insert[v], insert[v]) + back[u] -
                    back[v] - query(1, 1, 2 * n, insert[u], insert[u])
             << '\n';
      }
    }
  }
}
signed main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  long long test = 1;
  while (test--) {
    solve();
  }
}

