using namespace std;
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  map<long long, int> indexes;
  vector<long long> numbers(n);
  for (int i = 0; i < n; ++i) {
    cin >> numbers[i];
    ++indexes[numbers[i]];
  }
  vector<long long> pows_of_two;
  long long base = 1L;
  for (int i = 0; i < 31; ++i) {
    base *= 2;
    pows_of_two.push_back(base);
  }
  long long count = 0;
  for (int i = 0; i < n; ++i) {
    --indexes[numbers[i]];
    for (int j = 0; j < (int)pows_of_two.size(); ++j) {
      long long temp = pows_of_two[j] - numbers[i];
      if ((int)indexes[temp] == 0) continue;
      count += max(0, indexes[temp]);
    }
  }
  cout << count << endl;
  return 0;
}

