import java.util.*;
import java.io.*;
import java.lang.Math;
import java.util.Random;


public class Solution{


	public static void main(String[] args) throws Exception{

		FastScanner fs = new FastScanner();

		int t = fs.nextInt();

		while(t-->0){
			int n = fs.nextInt();
			long[] arr = new long[n];

			for(int i=0;i<n;i++) arr[i] = fs.nextLong();

			long sum = 0;
			for(int i=0;i<n;i+=2)
				sum += arr[i];

			int n1 = n/2;
			int n2 = (n-1)/2;
			long[] v1 = new long[n1];
			long[] v2 = new long[n2];

			for(int i=0;i<n1;i++){
				v1[i] = arr[2*i+1] - arr[2*i];
			}

			for(int i=0;i<n2;i++){
				v2[i] = arr[2*i+1] - arr[2*(i+1)];
			}

			System.out.println(sum + Math.max(maxSum(v1), maxSum(v2)));


		}



	}

	static long maxSum(long[] arr){
		int n = arr.length;
		long ans = 0;
		long sum = 0;
		for(int i=0;i<n;i++){
			if(arr[i]<0){
				ans = Math.max(ans, sum);
			}
			sum = sum + arr[i];
			if(sum<0)
				sum = 0;
		}
		ans = Math.max(ans, sum);
		return ans;
	}

	static class FastScanner{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer("");

		public String next(){
			while(!st.hasMoreElements()){
				try{
					st = new StringTokenizer(br.readLine());
				} catch(IOException e){
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		public int nextInt(){
			return Integer.parseInt(next());
		}

		public int[] readArray(int n){
			int[] a = new int[n];
			for(int i=0;i<n;i++)
				a[i] = nextInt();
			return a;
		}

		public long nextLong(){
			return Long.parseLong(next());
		}

	}

}

