#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ull = unsigned long long;
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  int t;
  cin >> t;
  while (t--) {
    int n;
    cin >> n;
    vector<ll> in(n);
    for (ll &i : in) cin >> i;
    vector<vector<ll>> dp(n + 5, vector<ll>(3));
    for (int i = 0; i < n; i++) {
      dp[i + 1][0] = max(dp[i + 1][0], dp[i][0] + (i & 1 ? 0 : in[i]));
      if (i + 2 <= n)
        dp[i + 2][1] = max(dp[i + 2][1], max(dp[i][0], dp[i][1]) +
                                             (i & 1 ? in[i] : in[i + 1]));
      dp[i + 1][2] = max(dp[i + 1][2], max({dp[i][0], dp[i][1], dp[i][2]}) +
                                           (i & 1 ? 0 : in[i]));
    }
    cout << max({dp[n][0], dp[n][1], dp[n][2]}) << endl;
  }
}

