def maxXsum(A, l, m, r):
    x=0; left=-1000000007
    for i in range(m, l-1, -1):
        x = x+A[i]
        if x>left:
            left = x

    x=0; right=-1000000007
    for i in range(m+1, r+1):
        x = x+A[i]
        if x>right:
            right = x

    return(max(left+right, left, right))

def maxsubsum(A, l, r):
    if l==r:
        return A[l]
    m = (l+r)//2

    return(max(maxsubsum(A,l,m), maxsubsum(A,m+1,r), maxXsum(A,l,m,r)))

t = int(input())
