    long long arr[n];
    for (long long i = 0; i < n; i++) cin >> arr[i];
    vector<long long> temp;
    long long ans = 0;
    for (long long i = 0; i < n; i += 2) ans += arr[i];
    for (long long i = 0; i < n; i += 2) {
      if (i + 1 < n) {
        temp.push_back(arr[i + 1] - arr[i]);
      }
    }
    long long maxsofar = 0, maxending = 0;
    long long start = -1, end = -1;
    long long currstart = 0;
    for (long long i = 0; i < temp.size(); i++) {
      maxending += temp[i];
      if (maxsofar < maxending) {
        maxsofar = maxending;
        start = currstart;
        end = i;
      }
      if (maxending < 0) {
        maxending = 0;
        currstart = i + 1;
      }
    }
