      long long sum = 0;
      for (long long i = 0; i < start * 2; i += 2) sum += arr[i];
      for (long long i = start * 2 + 1; i <= end * 2 + 1; i += 2) sum += arr[i];
      for (long long i = end * 2 + 2; i < n; i += 2) sum += arr[i];
      if (sum > ans) ans = sum;
    }
    temp.clear();
    for (long long i = 1; i < n; i += 2) {
      if (i + 1 < n) {
        temp.push_back(arr[i] - arr[i + 1]);
      }
