      for (long long i = 0; i < start * 2 + 1; i += 2) sum += arr[i];
      for (long long i = start * 2 + 1; i <= end * 2 + 1; i += 2) sum += arr[i];
      for (long long i = end * 2 + 4; i < n; i += 2) sum += arr[i];
      if (sum > ans) ans = sum;
    }
    cout << ans << "\n";
  }
  return 0;
}
long long power(long long x, long long y) {
  long long res = 1;
  x = x % 1000000007;
  while (y > 0) {
    if (y & 1) res = (res * x) % 1000000007;
    y = y >> 1;
    x = (x * x) % 1000000007;
  }
  return res;
}
long long gcd(long long a, long long b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}

