int main() {
  std::ios::sync_with_stdio(false);
  int t;
  cin >> t;
  while (t--) {
    int n;
    cin >> n;
    long long sum = 0, osum = 0;
    int cnt1 = 0, cnt2 = 0;
    for (int i = 0; i < n; i++) {
      cin >> data[i];
      if (i & 1) {
        ndata[0][cnt1++] = data[i] - data[i - 1];
      } else {
        sum += data[i];
        if (i) ndata[1][cnt2++] = data[i - 1] - data[i];
      }
    }
    long long minn = 0, per = 0, sub = 0, ans = 0;
    for (int i = 0; i < cnt1; i++) {
      per += ndata[0][i];
      minn = min(minn, per);
      sub = max(sub, per - minn);
    }
    ans = sum + sub;
    per = 0;
    minn = 0;
    for (int i = 0; i < cnt2; i++) {
      per += ndata[1][i];
      minn = min(minn, per);
      sub = max(sub, per - minn);
    }
    ans = max(ans, sum + sub);
    cout << ans << '\n';
  }
}

