    static void reverse(int a[], int l, int r){
        while (l<r){
            int t=a[l];
            a[l]=a[r];
            a[r]=t;
            l++;
            r--;
        }
    }


    private static int getResult(String s) {
        int res=0,i;
        for(i=0;i<1000000;i++){
            int curr=i;
            boolean ok=true;
            int j=0;
            for(char c:s.toCharArray()){
                res++;
                j++;
                if(c=='+')curr++;
                else curr--;
                if(curr<0){
                    ok=false;
                    break;
                }
            }
            System.out.print(j+" > ");
            if (ok)break;
        }
        System.out.println(i + " ###########");
        return res;
    }

    private static long getResult1(String s) {
        int sum=0;
        long ans=0;
        int mn=0;
        for(int i=0;i<s.length();i++){
            if (s.charAt(i)=='+')sum++;
            else sum--;
            if(sum<mn){
                ans=ans-sum;
                mn=sum;
            }
        }
        return ans+(maxx(-mn,0)+1)*s.length();
    }

    public static void main(String[] args) throws Exception {

        long START_TIME = System.currentTimeMillis();

        try (FastReader in = new FastReader();
             FastWriter out = new FastWriter()) {
            int n,t, i, j,f, k,m, ti, tidx, gm, q, g;
            for (t = in.nextInt(), tidx = 1; tidx <= t; tidx++)
            {
                long w,x, y = 0, z = 0, sum = 0, bhc = 0, ans = 0,l,r;
                //out.print(String.format("Case #%d: ", tidx));
                /*String s=in.next();
                out.println(getResult(s)+" "+getResult1(s));*/

                n=in.nextInt();
                int a[]=in.nextIntArr(n);
                for(i=0;i<n;i+=2){
                    ans+=a[i];
                }
                long m1=0,m2=0,currMax;
                if(n>1) {
                    currMax = a[1] - a[0];
                    m1 = currMax;
                    for (i = 2; i < n-1; i += 2) {
                        currMax = Math.max(a[i + 1] - a[i], currMax + a[i + 1] - a[i]);
                        m1 = Math.max(m1, currMax);
                    }
                }
                if(n>2) {
                    currMax = a[1] - a[2];
                    m2 = currMax;
                    for (i = 4; i < n; i += 2) {
                        currMax = Math.max(a[i - 1] - a[i], currMax + a[i - 1] - a[i]);
                        m2 = Math.max(m2, currMax);
                    }
                }
                out.println(ans+maxx(m1,m2,0L));
            }
            if (args.length > 0 && "ex_time".equals(args[0])) {
                out.print("\nTime taken: ");
                out.println(System.currentTimeMillis() - START_TIME);
            }
            out.commit();
        } catch (Exception e) {
            e.printStackTrace();
        }


    }




    public static class FastReader implements Closeable {
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] nextIntArr(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        Integer[] nextIntegerArr(int n) {
            Integer[] arr = new Integer[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        double[] nextDoubleArr(int n) {
            double[] arr = new double[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextDouble();
            }
            return arr;
        }

        long[] nextLongArr(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        String[] nextStrArr(int n) {
            String[] arr = new String[n];
            for (int i = 0; i < n; i++) {
                arr[i] = next();
            }
            return arr;
        }


        long[][] nextLongArr2(int n, int m) {
            long[][] arr = new long[n][m];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLongArr(m);
            }
            return arr;
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }


    public static class FastWriter implements Closeable {
        BufferedWriter bw;
        StringBuilder sb = new StringBuilder();
        List<String> list = new ArrayList<>();
        Set<String> set = new HashSet<>();

        public FastWriter() {
            bw = new BufferedWriter(new OutputStreamWriter(System.out));
        }

        <T> void commit() throws IOException {
            bw.write(sb.toString());
            bw.flush();
            sb = new StringBuilder();
        }

        public <T> void print(T obj) throws IOException {
            sb.append(obj.toString());
        }

        public void println() throws IOException {
            print("\n");
        }

        public <T> void println(T obj) throws IOException {
            print(obj.toString() + "\n");
        }

        <T> void printArrLn(T[] arr) throws IOException {
            for (int i = 0; i < arr.length - 1; i++) {
                print(arr[i] + " ");
            }
            println(arr[arr.length - 1]);
        }

        <T> void printArr2(T[][] arr) throws IOException {
            for (int j = 0; j < arr.length; j++) {
                for (int i = 0; i < arr[j].length - 1; i++) {
                    print(arr[j][i] + " ");
                }
                println(arr[j][arr[j].length - 1]);
            }
        }

        <T> void printColl(Collection<T> coll) throws IOException {
            for (T e : coll) {
                print(e + " ");
            }
            println();
        }

        void printCharN(char c, int n) throws IOException {
            for (int i = 0; i < n; i++) {
                print(c);
            }
        }

        void printIntArr2(int[][] arr) throws IOException {
            for (int j = 0; j < arr.length; j++) {
                for (int i = 0; i < arr[j].length - 1; i++) {
                    print(arr[j][i] + " ");
                }
                println(arr[j][arr[j].length - 1]);
            }
        }

        @Override
        public void close() throws IOException {
            bw.close();
        }

    }

}

