#include <bits/stdc++.h>
using namespace std;
string seq;
vector<string> pem;
string ms(int a[]) {
  string s = "000000";
  for (int i = 0; i < 6; i++) s[i] = a[i] + '0';
  return s;
}
void perm() {
  for (int i = 0; i <= 9; i++)
    for (int j = 0; j <= 9; j++)
      for (int k = 0; k <= 9; k++)
        for (int l = 0; l <= 9; l++)
          for (int m = 0; m <= 9; m++)
            for (int n = 0; n <= 9; n++) {
              if (i + j + k == l + m + n) {
                int a[] = {i, j, k, l, m, n};
                string s = ms(a);
                pem.push_back(s);
              }
            }
  return;
}
int dif(string a, string b) {
  int cnt = 0;
  for (int i = 0; i < 6; i++)
    if (a[i] != b[i]) cnt++;
  return cnt;
}
int main() {
  int ans = 99999999;
  cin >> seq;
  perm();
  for (int i = 0; i < pem.size(); i++) {
    ans = min(ans, dif(seq, pem[i]));
  }
  printf("%d\n", ans);
  return 0;
}

