#include <bits/stdc++.h>
using namespace std;
int n, n2;
string s, ss;
int ans, ans1;
void dfs(int y, int k) {
  if ((ss[3] - '0') + (ss[4] - '0') + (ss[5] - '0') ==
      (ss[0] - '0') + (ss[1] - '0') + (ss[2] - '0')) {
    ans = min(y, ans);
  }
  if (y > 6 || k >= 6) return;
  for (int i = 0; i <= 9; i++) {
    if (i != s[k] - '0') {
      ss[k] = i + '0';
      dfs(y + 1, k + 1);
      ss[k] = s[k];
    } else {
      dfs(y, k + 1);
    }
  }
  return;
}
int main() {
  cin >> s;
  ss = s;
  for (int i = 0; i < 3; i++) {
    n += (s[i] - '0');
    n2 += (s[i + 3] - '0');
  }
  ans = 100;
  ans1 = 100;
  dfs(0, 0);
  cout << min(ans1, ans) << endl;
}

