#include <bits/stdc++.h>
using namespace std;
const int N = 100005;
int po(int a, int b) {
  int ret = 1;
  while (b--) ret = ret * a;
  return ret;
}
char str[10];
int main() {
  scanf("%s", str);
  int ans = 7, a[7];
  for (int i = 0; i <= 999999; ++i) {
    for (int j = 0; j < 6; ++j) a[j] = (i / po(10, j)) % 10;
    if (a[0] + a[1] + a[2] != a[3] + a[4] + a[5]) continue;
    int tmp = 0;
    for (int j = 0; j < 6; ++j)
      if (str[j] - '0' != a[j]) ++tmp;
    ans = min(ans, tmp);
  }
  printf("%d\n", ans);
  return 0;
}

