      dp[i] = sum + 1;
      dp[i] %= mod;
      ans += dp[i];
      ans %= mod;
    } else if (a[i] == 'b') {
      sum += ans;
      sum %= mod;
      ans = 0;
      while (a[i] != 'a' && i <= n) i++;
      i--;
    }
    i++;
  }
  sum = 0;
