  for (i = 1; i < n; i++) {
    v[i] = v[i - 1];
    if (second[i] == 'a') {
      v[i] = i;
      dp[i] = (1 + dp[lasta]) % P;
      dp[i] = (dp[i] + dp[v[lastb]]) % P;
      lasta = i;
    }
    if (second[i] == 'b') {
      lastb = i;
    }
  }
  cout << dp[lasta] << "\n";
}
int main() {
  long long int t = 1;
  long long int i = 1;
  while (t--) {
    i++;
    solve();
  }
  return 0;
}

