        a[t].push_back(x);
      }
    }
  }
  auto place = a.begin();
  for (auto i = a.begin(); i != a.end(); i++) {
    vector<long long> b = i->second;
    int g = b.size();
    long long curr = *b.begin();
    for (int i = 0; i < g; i++) {
      curr = curr & b.at(i);
    }
    if (curr % i->first == 0) {
      place = i;
    }
  }
  vector<long long> b = place->second;
  cout << b.size() << "\n";
  for (auto i : b) {
    cout << i << " ";
  }
}

