import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.StringTokenizer;
import static java.lang.Math.*;
import static java.lang.Integer.*;
import static java.lang.Character.*;
import static java.lang.Long.*;
@SuppressWarnings("unused")

public class round195C {
    static BufferedReader br = new BufferedReader(new InputStreamReader(
            System.in));
    static StringTokenizer st = new StringTokenizer("");

    static int nextInt() throws Exception {
        return Integer.parseInt(next());
    }

    static String next() throws Exception {
        while (true) {
            if (st.hasMoreTokens()) {
                return st.nextToken();
            }
            String s = br.readLine();
            if (s == null) {
                return null;
            }
            st = new StringTokenizer(s);
        }
    }
    public static void main(String[] args)throws Exception {
        PrintWriter out = new PrintWriter(System.out);
        int n = nextInt();
        char [][] data = new char [n][31];
        int [] seq = new int [n];
        for(int i = 0 ; i < n ; ++i){
            int nxt = nextInt();
            seq[i] = nxt;
            String rep = Integer.toBinaryString(nxt);
            while(rep.length() < 31)
                rep = "0" + rep;            
            data[i] = rep.toCharArray();
        }
        for(int i = 0 ; i < 31 ; ++i){
            HashSet<Integer> can = new HashSet<Integer>();
            for(int j = 0 ; j < n ; ++j){
                if(data[j][i] == '1')
                    can.add(j);             
            }
            HashSet<Integer> vis = new HashSet<Integer>();
            for(Object o : can){
                int idx = (Integer) o;
                for(int j = i + 1 ; j < 31 ; ++j){
                    if(data[idx][j] == '0')
                        vis.add(j);
                }
            }
            if(vis.size() == 30 - i){
                HashSet<Integer> ret = new HashSet<Integer>();                          
                for(Object o : can){
                    int idx = (Integer) o;
                    ret.add(seq[idx]);
                }
                out.println(ret.size());
                for(Object o : ret){
                    int num = (Integer) o;
                    out.print(num + " ");
                }
                out.flush();                
                return;
            }
        }
        out.println(-1);
        out.flush();
    }
}

