#include <bits/stdc++.h>
using namespace std;
int a[111111];
int f(int x) {
  if (x == 0) {
    return -1;
  }
  int res = 0;
  while ((x & 1) == 0) {
    res++;
    x >>= 1;
  }
  return res;
}
int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) scanf("%d", &a[i]);
  int ans = -1;
  int ai = -1;
  int ahit = -1;
  for (int i = 29; i >= 0; i--) {
    int cur = (1 << 30) - 1;
    int chit = 0;
    for (int j = 0; j < n; j++) {
      if (a[j] & (1 << i)) {
        cur &= a[j];
        chit++;
      }
    }
    cur = f(cur);
    if (chit != 0 && (cur > ans || cur == ans && chit > ahit)) {
      ans = cur;
      ai = i;
      ahit = chit;
    }
  }
  vector<int> aa;
  for (int i = 0; i < n; i++) {
    if (a[i] & (1 << ai)) {
      aa.push_back(a[i]);
    }
  }
  cout << aa.size() << "\n";
  for (auto i : aa) {
    cout << i << " ";
  }
  return 0;
}

