import java.io.*;
import java.util.*;
import java.math.*;

public class Main implements Runnable {

	public void _main() throws IOException {
		char[] s = next().toCharArray();
		int n = s.length;
		h = new long[n];	
		pow = new long[n + 1];
		Random random = new Random(this.hashCode());
		P = random.nextInt(1000000) + 1000000;
		while (!BigInteger.valueOf(P).isProbablePrime(50)) ++P;
		pow[0] = 1;
		h[0] = s[0];
		for (int i = 1; i <= n; i++) {
			if (i < n) {
				h[i]  = P * h[i - 1]  + s[i]; 
			}
			pow[i] = pow[i - 1] * P;
		}

		boolean[] good = new boolean[n + 1];
		for (int i = 1; i <= n; i++)
			if (hash(0, i) == hash(n - i, i))
				good[i] = true;
		int l = 0;
		int r = n + 1;
		while (r - l > 1) {
			int m = (l + r) / 2;
			long need = hash(0, m);
			boolean ok = false;
			for (int i = 1; i + m < n; i++)
				if (hash(i, m) == need) {
					ok = true;
					break;
				}
			if (ok)
				l = m;
			else
				r = m;
		}

		int len = l;
		while (len > 0) {
			if (good[len])
				break;
			--len;
		}

		if (len == 0) {
			out.println("Just a legend");
		} else {
			for (int i = 0; i < len; i++)
				out.print(s[i]);
			out.println();
		}
	}

	long[] pow;
	long[] h;
	long P;

	private long hash(int pos, int len) {
		if (pos == 0)
			return h[len - 1];
		return h[pos + len - 1] - pow[len] * h[pos - 1];
	}

	private BufferedReader in;
	private PrintWriter out;
	private StringTokenizer st;

	private String next() throws IOException {
		while (st == null || !st.hasMoreTokens()) {
			String rl = in.readLine();
			if (rl == null)
				return null;
			st = new StringTokenizer(rl);
		}
		return st.nextToken();
	}

	private int nextInt() throws IOException {
		return Integer.parseInt(next());
	}

	private long nextLong() throws IOException {
		return Long.parseLong(next());
	}

	private double nextDouble() throws IOException {
		return Double.parseDouble(next());
	}

	public static void main(String[] args) {
		Locale.setDefault(Locale.UK);
		new Thread(new Main()).start();
	}

	public void run() {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);

			_main();

			out.close();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(202);
		}
	}

}

