import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.StringTokenizer;

public class SingleAllocationTrie {
	static int[][] t = new int[28][1 << 10];
	static int p = 1;

	static void add(String s) {
		int pointer = 0;
		for (char c : s.toCharArray())
			pointer = t[c - 'a'][pointer] == 0 ? (t[c - 'a'][pointer] = p++) : t[c - 'a'][pointer];
		t[27][pointer] = 1;
	}

	static int get(String s) {
		int pointer = 0;
		for (char c : s.toCharArray())
			pointer = t[c - 'a'][pointer];
		return pointer;
	}

	static boolean contains(String s) {
		return t[27][get(s)] == 1;
	}

	static int rk(String needle, String haystack) {
		if (haystack.length() < needle.length()) {
			return -1;
		}
		char[] h = haystack.toCharArray();
		long needleHash = 0, haystackHash = 0, pow = 1, BASE = 257;
		for (char c : needle.toCharArray()) {
			pow *= BASE;
			needleHash += c;
			needleHash *= BASE;
		}
		for (char c : haystack.substring(0, needle.length()).toCharArray()) {
			haystackHash += c;
			haystackHash *= BASE;
		}
		if (haystackHash == needleHash && haystack.startsWith(needle)) {
			return 0;
		}
		for (int l = 0, r = needle.length(); r < haystack.length(); l++, r++) {
			haystackHash = haystackHash - pow * h[l] + h[r];
			haystackHash *= BASE;
			if (haystackHash == needleHash && haystack.substring(l + 1).startsWith(needle)) {
				return l + 1;
			}
		}
		return -1;

	}

	public static void main(String[] args) {
		MyScanner in = new MyScanner();
		String s = in.nextLine();
		long h1 = 0, h2 = 0, pow = 1;
		int base = 257;
		List<Integer> len = new ArrayList<>();
		for (int i = 0; i < s.length() - 1; i++) {
			h1 += s.charAt(i);
			h1 *= base;
			pow *= base;
			h2 += pow * s.charAt(s.length() - i - 1);
			if (h1 == h2) {
				len.add(i + 1);
			}
		}
		int ans = -1;
		int l = 0, r = len.size();
		while (l != r) {
			int mid = (l + r) / 2;
			int length = len.get(mid);
			// fixprefixsuffix
			int res = rk(s.substring(0, length), s.substring(1, s.length() - 1));
			if (res == -1) {
				r = mid;
			} else {
				ans = length;
				l = mid + 1;
			}
		}
		if (ans != -1) {
			System.out.println(s.substring(0, ans));
		} else {
			System.out.println("Just a legend");
		}
	}

	public static class MyScanner {
		BufferedReader br;
		StringTokenizer st;

		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}

}

