                        out.append(s.substring(0,lps[lps[n-1]-1])+"\n");
                    }
                }
            }

        out.flush();
        out.close();
    }

    static long power( long x, long y, long p)
    {

        long res = 1;


        x = x % p;

        if (x == 0) return 0;

        while (y > 0)
        {

            if((y & 1)==1)
                res = (res * x) % p;


            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }


}

