#include <bits/stdc++.h>
using namespace std;
template <typename T>
inline bool read(T& x) {
  x = 0;
  char c = getchar();
  int f = 1;
  while (!isdigit(c) && (c != '-') && (c != EOF)) c = getchar();
  if (c == EOF) return 0;
  if (c == '-') f = -1, c = getchar();
  while (isdigit(c)) {
    x = (x << 1) + (x << 3) + (c & 15);
    c = getchar();
  }
  x *= f;
  return 1;
}
template <typename T, typename... Args>
inline bool read(T& x, Args&... args) {
  bool res = 1;
  res &= read(x);
  res &= read(args...);
  return res;
}
const int M = 1000000007, INF = 0x3f3f3f3f;
const long long INFLL = 0x3f3f3f3f3f3f3f3fLL;
const int N = 1000010;
const double EPS = 1e-6;
inline bool isc(char c) { return (c >= 'a') && (c <= 'z'); }
inline int reads(char* s) {
  int len = 0;
  char c = getchar();
  while (c != EOF && (!isc(c))) c = getchar();
  if (c == EOF) return 0;
  while (c != EOF && isc(c)) (*(++s)) = c, ++len, c = getchar();
  (*(++s)) = '\0';
  return len;
}
char s[N];
int n, nex[N], pos[N];
inline void init() {
  n = reads(s);
  int j = 0;
  for (int i = (2), (ii) = (n); i <= (ii); ++i) {
    while (j && (s[j + 1] != s[i])) j = nex[j];
    if (s[j + 1] == s[i]) ++j;
    ++pos[j];
    nex[i] = j;
  }
}
inline void solve() {
  int res = nex[n];
  --pos[res];
  while ((res) && (!pos[res])) res = nex[res];
  if (res == 0) {
    puts("Just a legend");
  } else {
    s[res + 1] = '\0';
    printf("%s\n", s + 1);
  }
}
signed main() {
  init();
  solve();
  return 0;
}

