#include <bits/stdc++.h>
using namespace std;
int n, a[300001], t[300001], p;
int lowbit(int x) { return x & (-x); }
void change(int x, int p) {
  while (x <= n) t[x] += p, x += lowbit(x);
}
int sum(int k) {
  int ans = 0;
  while (k > 0) ans += t[k], k -= lowbit(k);
  return ans;
}
bool check(int x) { return (x > 0 && sum(n) - sum(x - 1) == n - x + 1); }
int find() {
  int l = 1, r = n;
  while (l <= r) {
    int mid = l + r >> 1;
    if (check(mid) && !check(mid - 1)) return mid;
    if (check(mid))
      r = mid - 1;
    else
      l = mid + 1;
  }
  return n + 1;
}
int main() {
  scanf("%d", &n);
  printf("1 ");
  for (int i = 1; i <= n; i++) {
    scanf("%d", &p);
    change(p, 1);
    int r = find();
    printf("%d%c", i - n + r, i == n ? '\n' : ' ');
  }
  return 0;
}

