#include <bits/stdc++.h>
using namespace std;
const int max_n = 300005;
int DSU[max_n];
int dydis[max_n];
void init() {
  for (int i = 0; i < max_n; i++) {
    DSU[i] = i;
    dydis[i] = 1;
  }
}
int tevas(int id) {
  if (id == DSU[id])
    return id;
  else
    return DSU[id] = tevas(DSU[id]);
}
void sujungti(int i, int j) {
  int itevas = tevas(i), jtevas = tevas(j);
  if (itevas != jtevas) {
    if (dydis[itevas] > dydis[jtevas]) {
      DSU[jtevas] = itevas;
      dydis[itevas] += dydis[jtevas];
    } else {
      DSU[itevas] = jtevas;
      dydis[jtevas] += dydis[itevas];
    }
  }
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  cout.tie(NULL);
  int n;
  cin >> n;
  init();
  cout << 1 << " ";
  bool padeti[n + 2];
  for (int i = 0; i <= n + 1; i++) padeti[i] = 0;
  padeti[n + 1] = 1;
  int galiniai = 0;
  for (int i = 0; i < n; i++) {
    int p;
    cin >> p;
    padeti[p] = 1;
    if (p - 1 > 0) {
      if (padeti[p - 1]) sujungti(p, p - 1);
    }
    if (p + 1 <= n + 1) {
      if (padeti[p + 1]) sujungti(p + 1, p);
    }
    cout << i - dydis[tevas(n + 1)] + 3 << " ";
  }
  return 0;
}

