    for i in range(n):
        if s[i]=='1':
            dp[i+1]=i
        else:
            dp[i+1]=dp[i]
    for i in range(n):
        for j in range(i+1,min(n+1,i+19)):
            e=s[i:j]
            y=int(e,2)
            if len(e)==y:
                if (i,j) not in se:
                    ans+=1
                    #print(i,j,y)
                    se.add((i,j))
            elif y>18:
                if y<=len(e)+i-dp[i]-1:
                    ser=j-y+1
                    if (ser,j) not in se:
                        ans+=1
                        #print(ser,j,y)
                        se.add((ser,j))
    print(ans)

