import java.util.*;

public class AtCoder_A{
	public static void main(String[] args) {
		Scanner input = new Scanner(System.in);
		HashMap<String,Integer> map = new HashMap<>();
		for(int i = 1;i<=2*100000;i++){
			String str = "";
			int n = i;
			while(n>=1){
				str = (n%2) + str;
				n/=2;
			}
			int len = i - str.length();
			map.put(str,len);
		}

		int t = input.nextInt();
		for(int i = 0;i<t;i++){
			String s = input.next();
			long count = 0;
			int[] arr = new int[s.length()];
			for(int j = 1;j<arr.length;j++){
				if(s.charAt(j-1) == '0'){
					arr[j] = arr[j-1] + 1;
				}
			}

			for(int r = 1;r<=19;r++){
				for(int l = 0;r+l<=s.length();l++){
					if(s.charAt(l) == '1'){
						String temp = s.substring(l,r+l);
						if(map.containsKey(temp) && map.get(temp) <= arr[l]){
							count++;
						}
					}
				}
			}
			System.out.println(count);
		}
	}
}

