public class template {

	public static void main(String[] args) throws IOException {

		Scanner scn = new Scanner(System.in);

		int t = scn.nextInt();

		int p = f(5);

		for (int j = 0; j < t; j++) {

			String s = scn.next();

			int[] dp = new int[s.length()];
			int cnt = 0;

			for (int i = 0; i < s.length(); i++) {

				dp[i] = cnt;

				if (s.charAt(i) == '0')
					cnt++;

				else
					cnt = 0;

			}

			long ans = 0;

			for (int l = 0; l < s.length(); l++) {

				for (int r = l; r < s.length() && r - l + 1 <= 31; r++) {

					String sb = s.substring(l, r + 1);

					if (sb.charAt(0) == '0')
						break;

					int val = Integer.parseInt(sb, 2);

					if (val == r - l + 1)
						ans++;

					if (val > r - l + 1) {

						if (val <= (r - l + 1 + dp[l]))
							ans++;
					}

				}
			}

			System.out.println(ans);
		}
	}


	private static int f(int u) {

		int x = 0;

		for (int i = 0; i < 5; i++)
			x++;
		return 5;
	}

}

