import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Hardik
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int t = in.nextInt();
            for (int k = 0; k < t; k++) {
                char[] str = in.next().toCharArray();
                int[] zerocount = new int[str.length];
                int x = 0;
                for (int i = 0; i < str.length; i++) {
                    if (i > 0) {
                        zerocount[i] = (str[i - 1] == '0') ? zerocount[i - 1] + 1 : 0;

                    }
                    //out.print(zerocount[i]);
                }
                int count = 0;
                for (int i = 0; i < str.length; i++) {
                    x = 0;
                    if (str[i] == '1') {
                        x = 1;

                        count++;
                        for (int j = i + 1; j < Integer.min(str.length, i + 20); j++) {
                            x = str[j] == '0' ? 2 * x : 2 * x + 1;

                            if (zerocount[i] + j - i + 1 >= x) {
                                count++;
                            }
                            //  out.println(" i = " + i + " j = " + j + " zerocount = " + zerocount[j] + " x = " + x + " count = " + count);
                        }

                    }
                }
                //out.println();
                out.println(count);
            }
        }

    }
}

