solution_1:
#include <bits/stdc++.h>
using namespace std;
int N, M;
vector<int> G[100100];
int EA[100100];
int EB[100100];
int WGROUP[100100];
map<int, int> GROUP[100100];
set<int> WHITE[100100];
bool VD[100100];
bool path(int g, int ca, int cb) {
  if (ca > cb) swap(ca, cb);
  int nextwhite = *(WHITE[g].upper_bound(ca - 1));
  if (nextwhite < cb) return false;
  return true;
}
int main() {
  scanf("%d", &N);
  for (int i = 1; i <= N - 1; i++) {
    int a, b;
    scanf("%d%d", &a, &b);
    EA[i] = a;
    EB[i] = b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  int proxy = 0;
  int maxdeg = 0;
  for (int i = 1; i <= N; i++) {
    int t = G[i].size();
    if (maxdeg < t) {
      maxdeg = t;
      proxy = i;
    }
  }
  WGROUP[proxy] = -1;
  VD[proxy] = true;
  for (int i = 0; i < G[proxy].size(); i++) {
    WHITE[i].insert(-1000000);
    WHITE[i].insert(1000000);
    GROUP[i][proxy] = 0;
    int v = G[proxy][i];
    int no = 1;
    while (true) {
      GROUP[i][v] = no;
      WGROUP[v] = i;
      VD[v] = true;
      if (G[v].size() == 1) break;
      v = VD[G[v][0]] ? G[v][1] : G[v][0];
      no++;
    }
  }
  scanf("%d", &M);
  while (M--) {
    int type;
    scanf("%d", &type);
    if (type == 3) {
      int a, b;
      scanf("%d%d", &a, &b);
      int ans = -1;
      if (a == b) {
        ans = 0;
      } else {
        int ga = WGROUP[a], gb = WGROUP[b];
        if (ga == -1) ga = gb;
        if (gb == -1) gb = ga;
        int ca = GROUP[ga][a], cb = GROUP[gb][b];
        if (ga == gb) {
          if (path(ga, ca, cb)) ans = abs(ca - cb);
        } else {
          if (path(ga, ca, 0) && path(gb, cb, 0)) ans = ca + cb;
        }
      }
      printf("%d\n", ans);
    } else {
      int idx;
      scanf("%d", &idx);
      int a = EA[idx], b = EB[idx];
      int ga = WGROUP[a], gb = WGROUP[b];
      if (ga == -1) ga = gb;
      if (gb == -1) gb = ga;
      int ca = GROUP[ga][a], cb = GROUP[gb][b];
      if (ca > cb) swap(ca, cb);
      if (type == 2)
        WHITE[ga].insert(ca);
      else
        WHITE[ga].erase(ca);
    }
  }
  return 0;
}

solution_2:
#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 10;
typedef struct a {
  int l, r, num;
} per;
typedef struct b {
  int to, next;
} node;
per tree[maxn * 4];
node si[maxn * 2];
int n, m, ctt, head[maxn], points[maxn], cnt, fa[maxn], top[maxn], size[maxn],
    dep[maxn], id[maxn], son[maxn];
void add(int u, int v) {
  si[++ctt].next = head[u];
  si[ctt].to = v;
  head[u] = ctt;
}
void dfs(int now, int fa) {
  for (int i = head[now]; i != -1; i = si[i].next) {
    int to = si[i].to;
    if (to != fa) {
      if (i & 1)
        points[(i + 1) / 2] = to;
      else
        points[i / 2] = to;
      dfs(to, now);
    }
  }
}
void dfs1(int x, int f) {
  fa[x] = f;
  dep[x] = dep[f] + 1;
  size[x] = 1;
  int maxson = -1;
  for (int i = head[x]; i != -1; i = si[i].next) {
    int to = si[i].to;
    if (to != f) {
      dfs1(to, x);
      size[x] += size[to];
      if (size[to] > maxson) {
        maxson = size[to];
        son[x] = to;
      }
    }
  }
}
void dfs2(int x, int t) {
  id[x] = ++cnt;
  top[x] = t;
  if (!son[x]) return;
  dfs2(son[x], t);
  for (int i = head[x]; i != -1; i = si[i].next) {
    int to = si[i].to;
    if (to != son[x] && fa[x] != to) {
      dfs2(to, to);
    }
  }
}
void update(int p) {
  if (tree[p * 2].num == -1 || tree[p * 2 + 1].num == -1)
    tree[p].num = -1;
  else
    tree[p].num = tree[p * 2].num + tree[p * 2 + 1].num;
}
void build(int p, int l, int r) {
  tree[p].l = l;
  tree[p].r = r;
  if (l == r) {
    tree[p].num = 1;
    return;
  }
  build(p * 2, l, (tree[p].l + tree[p].r) / 2);
  build(p * 2 + 1, (tree[p].l + tree[p].r) / 2 + 1, r);
  update(p);
}
void change(int p, int pos, int num) {
  if (tree[p].l == tree[p].r) {
    if (num == 0)
      tree[p].num = 1;
    else
      tree[p].num = -1;
    return;
  }
  if (pos <= (tree[p].l + tree[p].r) / 2)
    change(p * 2, pos, num);
  else
    change(p * 2 + 1, pos, num);
  update(p);
}
int query(int p, int l, int r) {
  if (l > r) return 0;
  if (tree[p].l >= l && tree[p].r <= r) {
    return tree[p].num;
  }
  int tans = 0;
  if (l <= (tree[p].l + tree[p].r) / 2) tans = query(p * 2, l, r);
  if (tans == -1 || r <= (tree[p].l + tree[p].r) / 2) return tans;
  if (r > (tree[p].l + tree[p].r) / 2) {
    int temp = query(p * 2 + 1, l, r);
    if (temp == -1)
      return -1;
    else {
      return temp + tans;
    }
  }
}
void print() {
  cout << "TEST\n";
  for (int i = 1; i <= 5; ++i) {
    cout << tree[i].l << ' ' << tree[i].r << ' ' << tree[i].num << "\n";
  }
  cout << "********************\n";
}
int main() {
  cin >> n;
  int sign, u, v;
  memset(head, -1, sizeof(head));
  for (int i = 1; i < n; ++i) {
    scanf("%d%d", &u, &v);
    add(u, v);
    add(v, u);
  }
  dfs1(1, 0);
  dfs2(1, 1);
  dfs(1, 0);
  build(1, 1, n);
  cin >> m;
  for (int i = 1; i <= m; ++i) {
    scanf("%d%d", &sign, &u);
    if (sign == 1)
      change(1, id[points[u]], 0);
    else if (sign == 2)
      change(1, id[points[u]], 1);
    else {
      scanf("%d", &v);
      int ans = 0;
      while (top[u] != top[v]) {
        if (dep[top[u]] < dep[top[v]]) swap(u, v);
        int temp = query(1, id[top[u]], id[u]);
        if (temp == -1) {
          ans = -1;
          break;
        } else
          ans += temp;
        u = fa[top[u]];
      }
      if (ans == -1)
        printf("-1\n");
      else {
        if (dep[u] > dep[v]) swap(u, v);
        int temp = query(1, id[u] + 1, id[v]);
        if (temp == -1)
          printf("-1\n");
        else
          printf("%d\n", temp + ans);
      }
    }
  }
  return 0;
}

solution_3:
#include <bits/stdc++.h>
using namespace std;
vector<int> grav[100700];
int root;
int treeid[100700];
int height[100700];
int n;
int curid;
vector<set<int> > s;
pair<int, int> edges[100700];
void dfs(int v, int p, int h) {
  treeid[v] = curid;
  height[v] = h;
  for (int i = 0; i < (int)grav[v].size(); i++) {
    int u = grav[v][i];
    if (u == p) continue;
    dfs(u, v, h + 1);
  }
}
void deledge(int j) {
  int v = edges[j].first, u = edges[j].second;
  int t = max(treeid[v], treeid[u]);
  if (height[v] > height[u]) swap(u, v);
  s[t].insert(height[v]);
}
void addedge(int j) {
  int v = edges[j].first, u = edges[j].second;
  int t = max(treeid[v], treeid[u]);
  if (height[v] > height[u]) swap(u, v);
  s[t].erase(height[v]);
}
int getheight(int v) {
  int t = treeid[v];
  if (s[t].empty() || height[v] <= *s[t].begin())
    return height[v];
  else
    return -1;
}
int findpath(int u, int v) {
  if (u == v) return 0;
  if (treeid[u] == treeid[v] || treeid[u] == -1 || treeid[v] == -1) {
    int t = max(treeid[v], treeid[u]);
    if (height[v] > height[u]) swap(u, v);
    if (s[t].empty() ||
        s[t].lower_bound(height[v]) == s[t].lower_bound(height[u]))
      return height[u] - height[v];
    else
      return -1;
  } else {
    int hv = getheight(v), hu = getheight(u);
    if (hv == -1 || hu == -1)
      return -1;
    else
      return hv + hu;
  }
}
int main() {
  cin >> n;
  for (int i = 0; i < (int)(n - 1); i++) {
    int v, u;
    cin >> v >> u;
    --u;
    --v;
    grav[v].push_back(u);
    grav[u].push_back(v);
    edges[i] = make_pair(v, u);
  }
  int mmx = -1;
  for (int i = 0; i < (int)(n); i++)
    if ((int)grav[i].size() > mmx) {
      root = i;
      mmx = (int)grav[i].size();
    }
  curid = 0;
  for (int i = 0; i < (int)grav[root].size(); i++) {
    dfs(grav[root][i], root, 1);
    ++curid;
  }
  height[root] = 0;
  treeid[root] = -1;
  s.resize(curid);
  int m;
  int v, u, type;
  cin >> m;
  for (int i = 0; i < (int)(m); i++) {
    cin >> type;
    if (type == 1) {
      cin >> v;
      addedge(v - 1);
    }
    if (type == 2) {
      cin >> v;
      deledge(v - 1);
    }
    if (type == 3) {
      cin >> v >> u;
      cout << findpath(v - 1, u - 1) << endl;
    }
  }
  return 0;
}

solution_4:
#include <bits/stdc++.h>
using namespace std;
const int MAXN = 100000 + 10;
struct Tree {
  struct Edge {
    int v, w, n;
  } e[MAXN << 1];
  int G[MAXN], edgeCnt, N;
  void _add_edge(int u, int v, int w) {
    e[++edgeCnt].n = G[u];
    G[u] = edgeCnt;
    e[edgeCnt].v = v;
    e[edgeCnt].w = w;
  }
  void add_edge(int u, int v, int w) { _add_edge(u, v, w), _add_edge(v, u, w); }
  int dep[MAXN], fa[MAXN], top[MAXN];
  int size[MAXN], child[MAXN];
  int ed[MAXN];
  int id[MAXN], clk;
  void dfs(int u) {
    size[u] = 1, child[u] = 0;
    for (int i = G[u]; i; i = e[i].n)
      if (e[i].v != fa[u]) {
        dep[e[i].v] = dep[u] + 1;
        fa[e[i].v] = u;
        ed[e[i].w] = e[i].v;
        dfs(e[i].v);
        size[u] += size[e[i].v];
        if (size[child[u]] < size[e[i].v]) child[u] = e[i].v;
      }
  }
  void dfs(int u, int anc) {
    top[u] = anc;
    id[u] = ++clk;
    if (child[u]) dfs(child[u], anc);
    for (int i = G[u]; i; i = e[i].n)
      if (e[i].v != fa[u] && e[i].v != child[u]) dfs(e[i].v, e[i].v);
  }
  struct BinaryIndexedTree {
    int c[MAXN], N;
    int sum(int x) {
      int res = 0;
      for (; x; x -= x & -x) res += c[x];
      return res;
    }
    void add(int x, int v) {
      for (; x <= N; x += x & -x) c[x] += v;
    }
    int query(int l, int r) { return sum(r) - sum(l - 1); }
  } bit;
  void init(int n) {
    bit.N = n;
    dfs(1);
    dfs(1, 1);
  }
  void del(int i) { bit.add(id[ed[i]], -1); }
  void add(int i) { bit.add(id[ed[i]], 1); }
  int solve(int u, int v) {
    int cnt = dep[u] + dep[v];
    while (top[u] != top[v]) {
      if (dep[top[u]] < dep[top[v]]) swap(u, v);
      if (bit.query(id[top[u]], id[u])) return -1;
      u = fa[top[u]];
    }
    if (dep[u] > dep[v]) swap(u, v);
    cnt -= dep[u] * 2;
    if (u == v) return cnt;
    if (bit.query(id[child[u]], id[v])) return -1;
    return cnt;
  }
} tree;
int main() {
  ios::sync_with_stdio(0);
  int n, m;
  cin >> n;
  for (int i = 1; i < n; ++i) {
    int u, v;
    cin >> u >> v;
    tree.add_edge(u, v, i);
  }
  tree.init(n);
  cin >> m;
  for (int i = 1; i <= m; ++i) {
    int opt;
    cin >> opt;
    if (opt == 1) {
      int i;
      cin >> i;
      tree.del(i);
    } else if (opt == 2) {
      int i;
      cin >> i;
      tree.add(i);
    } else {
      int u, v;
      cin >> u >> v;
      cout << tree.solve(u, v) << endl;
    }
  }
}

solution_5:
#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 100001;
struct BIT {
  int n;
  vector<int> a, c;
  void init(int _n) {
    n = _n;
    a = vector<int>(n + 1, 0);
    c = vector<int>(n + 1, 0);
  }
  void update(int i, int val) {
    val -= a[i];
    a[i] += val;
    for (++i; i <= n; i += i & -i) {
      c[i] += val;
    }
  }
  int query(int i) {
    int ret = 0;
    while (i > 0) {
      ret += c[i];
      i &= i - 1;
    }
    return ret;
  }
  int query(int i, int j) { return query(j) - query(i); }
} bit[MAX_N];
int n, m, root;
int eu[MAX_N], ev[MAX_N], deg[MAX_N], depth[MAX_N], id[MAX_N];
int fa[18][MAX_N];
vector<int> e[MAX_N];
void dfs(int u, int f) {
  fa[0][u] = f;
  for (int i = 1; i < 18; ++i) {
    fa[i][u] = fa[i - 1][fa[i - 1][u]];
  }
  for (vector<int>::const_iterator i = e[u].begin(); i != e[u].end(); ++i) {
    if (*i != f) {
      depth[*i] = depth[u] + 1;
      id[*i] = id[u];
      dfs(*i, u);
    }
  }
  if (e[u].size() == 1) {
    bit[id[u]].init(depth[u]);
  }
}
int get_lca(int u, int v) {
  if (depth[u] < depth[v]) {
    swap(u, v);
  }
  for (int i = 0; i < 18; ++i) {
    if (((depth[u] - depth[v]) & 1 << i) != 0) {
      u = fa[i][u];
    }
  }
  if (u == v) return u;
  for (int i = 17; i >= 0; --i) {
    int nu = fa[i][u];
    int nv = fa[i][v];
    if (nu != nv) {
      u = nu;
      v = nv;
    }
  }
  return fa[0][u];
}
void solve() {
  for (int i = root = 0; i < n; ++i) {
    if (deg[i] > deg[root]) {
      root = i;
    }
  }
  depth[root] = 0;
  for (int i = 0; i < 18; ++i) {
    fa[i][root] = root;
  }
  for (vector<int>::const_iterator i = e[root].begin(); i != e[root].end();
       ++i) {
    depth[*i] = 1;
    id[*i] = i - e[root].begin();
    dfs(*i, root);
  }
  for (int i = 1; i < n; ++i) {
    if (depth[eu[i]] > depth[ev[i]]) {
      swap(eu[i], ev[i]);
    }
  }
  scanf("%d", &m);
  for (int i = 0; i < m; ++i) {
    int type, num, u, v;
    scanf("%d", &type);
    if (type == 1) {
      scanf("%d", &num);
      bit[id[ev[num]]].update(depth[eu[num]], 0);
    } else if (type == 2) {
      scanf("%d", &num);
      bit[id[ev[num]]].update(depth[eu[num]], 1);
    } else if (type == 3) {
      scanf("%d%d", &u, &v);
      --u, --v;
      int lca = get_lca(u, v);
      int t = 0;
      t += bit[id[u]].query(depth[lca], depth[u]);
      t += bit[id[v]].query(depth[lca], depth[v]);
      if (t == 0) {
        printf("%d\n", depth[u] + depth[v] - 2 * depth[lca]);
      } else
        puts("-1");
    }
  }
}
int main() {
  scanf("%d", &n);
  for (int i = 1; i < n; ++i) {
    scanf("%d%d", &eu[i], &ev[i]);
    --eu[i], --ev[i];
    e[eu[i]].push_back(ev[i]);
    e[ev[i]].push_back(eu[i]);
    ++deg[eu[i]], ++deg[ev[i]];
  }
  solve();
  return 0;
}

solution_6:
#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 10;
struct node {
  int l, r, sum;
} tr[5 * N];
int fst[N], nxt[2 * N], v[2 * N], cnt;
int fa[N], dep[N], siz[N], son[N], top[N], dfn[N], rk[N], tot;
int s[N], e[N], c[N];
void add(int x, int y) {
  v[++cnt] = y;
  nxt[cnt] = fst[x], fst[x] = cnt;
}
void dfs1(int x) {
  siz[x] = 1;
  for (int i = fst[x]; i; i = nxt[i]) {
    int y = v[i];
    if (siz[y]) continue;
    dep[y] = dep[x] + 1, fa[y] = x;
    dfs1(y);
    siz[x] += siz[y];
    if (siz[y] > siz[son[x]]) son[x] = y;
  }
}
void dfs2(int x, int t) {
  top[x] = t;
  dfn[x] = ++tot, rk[tot] = x;
  if (!son[x]) return;
  dfs2(son[x], t);
  for (int i = fst[x]; i; i = nxt[i]) {
    int y = v[i];
    if (y != fa[x] && y != son[x]) dfs2(y, y);
  }
}
void build(int x, int l, int r) {
  tr[x].l = l, tr[x].r = r;
  if (l == r) return;
  int mid = (l + r) / 2;
  build(x * 2, l, mid), build(x * 2 + 1, mid + 1, r);
}
void modif(int x, int k, int d) {
  if (tr[x].l == tr[x].r) {
    tr[x].sum = d;
    return;
  }
  if (k <= tr[x * 2].r)
    modif(x * 2, k, d);
  else
    modif(x * 2 + 1, k, d);
  tr[x].sum = tr[x * 2].sum + tr[x * 2 + 1].sum;
}
int query(int x, int l, int r) {
  if (tr[x].r < l || tr[x].l > r) return 0;
  if (tr[x].l >= l && tr[x].r <= r) return tr[x].sum;
  int ans = 0;
  if (tr[x * 2].r >= l) ans += query(x * 2, l, r);
  if (tr[x * 2 + 1].l <= r) ans += query(x * 2 + 1, l, r);
  return ans;
}
void ask(int x, int y) {
  int ans = 0, tmp = 0;
  while (top[x] != top[y]) {
    if (dep[top[x]] < dep[top[y]]) swap(x, y);
    tmp += query(1, dfn[top[x]], dfn[x]);
    ans += (dfn[x] - dfn[top[x]] + 1), x = fa[top[x]];
  }
  if (dep[x] < dep[y]) swap(x, y);
  tmp += query(1, dfn[y] + 1, dfn[x]), ans += (dfn[x] - dfn[y]);
  if (tmp)
    printf("-1\n");
  else
    printf("%d\n", ans);
}
int main() {
  int n, m, x, y, op;
  scanf("%d", &n);
  for (int i = 1; i < n; i++) {
    scanf("%d%d", &s[i], &e[i]);
    add(s[i], e[i]), add(e[i], s[i]);
  }
  dfs1(1), dfs2(1, 1);
  build(1, 1, n);
  scanf("%d", &m);
  while (m--) {
    scanf("%d", &op);
    if (op == 1) {
      scanf("%d", &x);
      if (dep[e[x]] > dep[s[x]])
        modif(1, dfn[e[x]], 0);
      else
        modif(1, dfn[s[x]], 0);
    }
    if (op == 2) {
      scanf("%d", &x);
      if (dep[e[x]] > dep[s[x]])
        modif(1, dfn[e[x]], 1);
      else
        modif(1, dfn[s[x]], 1);
    }
    if (op == 3) {
      scanf("%d%d", &x, &y);
      ask(x, y);
    }
  }
  return 0;
}

solution_7:
#include <bits/stdc++.h>
using namespace std;
template <class T>
T abs(T x) {
  return x > 0 ? x : -x;
}
int n;
int m;
vector<pair<int, int> > v[100000];
int f[200000];
int d[200000];
int u[200000];
int col[200000];
int tr[200000];
int o = 0;
int c[200000];
int go(int x, int p, int r, int l) {
  d[x] = l;
  if (r >= 0) {
    u[p] = o;
    o++;
  }
  col[x] = r;
  for (int i = 0; i < ((int)(v[x]).size()); i++) {
    int y = v[x][i].first;
    int z = v[x][i].second;
    if (z != p)
      if (r == -1) {
        f[i] = o;
        go(y, z, i, l + 1);
      } else
        go(y, z, r, l + 1);
  }
  return 0;
}
int get(int x) {
  int s = 0;
  while (x > 0) {
    s += tr[x];
    x = (x & (x + 1)) - 1;
  }
  return s;
}
int add(int x, int y) {
  x++;
  while (x <= n) {
    tr[x] += y;
    x |= x + 1;
  }
  return 0;
}
int main() {
  scanf("%d", &n);
  for (int i = 0; i + 1 < n; i++) {
    int a, b;
    scanf("%d%d", &a, &b);
    a--;
    b--;
    v[a].push_back(make_pair(b, i));
    v[b].push_back(make_pair(a, i));
    c[a]++;
    c[b]++;
  }
  int r = 0;
  for (int i = 0; i < n; i++)
    if (c[i] > c[r]) r = i;
  go(r, -1, -1, 0);
  scanf("%d", &m);
  for (int i = 0; i < m; i++) {
    int t, x, y;
    scanf("%d%d", &t, &x);
    x--;
    if (t == 1) {
      add(u[x], -1);
    } else if (t == 2) {
      add(u[x], 1);
    } else {
      scanf("%d", &y);
      y--;
      if (x == y)
        printf("0\n");
      else if (col[x] == col[y]) {
        if (d[x] > d[y]) swap(x, y);
        int X = col[x];
        int tmp = get(f[X] + d[y]) - get(f[X] + d[x]);
        if (tmp == 0)
          tmp = d[y] - d[x];
        else
          tmp = -1;
        printf("%d\n", tmp);
      } else {
        int tmp = 0, X = col[x], Y = col[y];
        if (X != -1) tmp += get(f[X] + d[x]) - get(f[X]);
        if (Y != -1) tmp += get(f[Y] + d[y]) - get(f[Y]);
        if (tmp == 0)
          tmp = d[y] + d[x];
        else
          tmp = -1;
        printf("%d\n", tmp);
      }
    }
  }
  return 0;
}

solution_8:
#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 10;
int i, j, k, n, m, f, a[maxn], b[maxn], q[maxn], z[maxn];
vector<int> e[maxn];
vector<int> s[maxn];
int get(int k, int x) {
  int ret = 0;
  for (; x; x -= ((x) & (-(x)))) ret += s[k][x];
  return ret;
}
int add(int k, int x, int t) {
  for (; x < s[k].size(); x += ((x) & (-(x)))) s[k][x] += t;
}
int main() {
  cin >> n;
  for (int i = 1; i <= n - 1; i++) {
    scanf("%d%d", a + i, b + i);
    e[a[i]].push_back(b[i]);
    e[b[i]].push_back(a[i]);
  }
  int r = 1;
  for (int i = 0; i < n + 1; i++)
    if (e[i].size() > 2) r = i;
  for (int i = 0; i < e[r].size(); i++) {
    for (j = e[r][i], f = r, k = 0;;) {
      q[j] = ++k, z[j] = i;
      if (e[j].size() == 1) break;
      m = f, f = j, j = e[f][0];
      if (j == m) j = e[f][1];
    }
    s[i].resize(k + 1, 0);
  }
  scanf("%d", &m);
  while (m--) {
    int k, i;
    scanf("%d%d", &k, &i);
    if (k < 3)
      add(max(z[a[i]], z[b[i]]), max(q[a[i]], q[b[i]]), k * 2 - 3);
    else {
      scanf("%d", &j);
      if (z[i] == z[j])
        printf("%d\n",
               get(z[i], q[i]) == get(z[j], q[j]) ? abs(q[i] - q[j]) : -1);
      else
        printf("%d\n", get(z[i], q[i]) + get(z[j], q[j]) ? -1 : q[i] + q[j]);
    }
  }
  return 0;
}

solution_9:
#include <bits/stdc++.h>
#pragma comment(linker, "/STACK:16777216")
using namespace std;
const double pi = 3.14159265358979323846264338327950288419716939937511;
const double eps = 1e-9;
char ch_ch_ch[1 << 20];
string gs() {
  scanf("%s", ch_ch_ch);
  return string(ch_ch_ch);
}
string gl() {
  gets(ch_ch_ch);
  return string(ch_ch_ch);
}
vector<vector<int> > G;
vector<pair<int, int> > E;
int n;
int root;
int gi[111111];
int d[111111];
vector<vector<int> > fen;
int br;
void dfs(int v, int pr, int ind, int dist) {
  gi[v] = ind;
  d[v] = dist;
  fen[ind].push_back(0);
  for (int i = 0; i < (G[v].size()); ++i)
    if (E[G[v][i]].second != pr) dfs(E[G[v][i]].second, v, ind, dist + 1);
}
void fenmod(int ind, int p, int val) {
  for (; p < fen[ind].size(); p += p & (-p)) {
    fen[ind][p - 1] += val;
  }
}
int fensum(int ind, int p) {
  int sum = 0;
  for (; p > 0; p -= p & (-p)) sum += fen[ind][p - 1];
  return sum;
}
int calc(int u, int v) {
  if (d[u] > d[v]) swap(u, v);
  int ind = gi[v];
  if (u == v) return 0;
  if (fensum(ind, d[v]) - fensum(ind, d[u]) > 0) return -1000000000;
  return d[v] - d[u];
}
void solution() {
  scanf("%d", &n);
  G.resize(n);
  for (int i = 0; i < (n - 1); ++i) {
    int u, v;
    scanf("%d%d", &u, &v);
    --u, --v;
    G[u].push_back(E.size());
    E.push_back(make_pair(u, v));
    G[v].push_back(E.size());
    E.push_back(make_pair(v, u));
  }
  root = 0;
  for (int i = (1); i < (G.size()); ++i)
    if (G[i].size() > 2) {
      root = i;
      break;
    }
  fen.resize(G[root].size());
  br = G[root].size();
  for (int i = 0; i < (br); ++i) {
    fen[i].push_back(0);
    dfs(E[G[root][i]].second, root, i, 1);
  }
  int m;
  scanf("%d", &m);
  d[root] = 0;
  for (int it = 0; it < (m); ++it) {
    int tp;
    scanf("%d", &tp);
    if (tp == 1 || tp == 2) {
      int e;
      scanf("%d", &e);
      --e;
      e *= 2;
      int v = (d[E[e].second] < d[E[e].first]) ? E[e].first : E[e].second;
      fenmod(gi[v], d[v], (tp == 1) ? -1 : 1);
    } else {
      int u, v;
      scanf("%d%d", &u, &v);
      --u, --v;
      if (d[u] > d[v]) swap(u, v);
      int res;
      if (gi[u] == gi[v])
        res = calc(u, v);
      else
        res = calc(root, u) + calc(root, v);
      if (res < 0)
        printf("-1\n");
      else
        printf("%d\n", res);
    }
  }
}
int main(int argc, char** argv) {
  solution();
  return 0;
}

