#include <bits/stdc++.h>
using namespace std;
const int MAXN = 1e6 + 69, MOD = 1e9 + 7;
int n, q, root, cnt, height[MAXN], par[MAXN], st[MAXN], seg[MAXN << 2];
pair<int, int> edge[MAXN];
vector<int> g[MAXN];
void dfs(int v, int parent = -1) {
  st[v] = cnt++;
  for (auto u : g[v])
    if (u != parent) {
      height[u] = height[v] + 1;
      if (height[u] == 1) par[u] = u;
      if (height[u] > 1) par[u] = par[v];
      dfs(u, v);
    }
}
void update(int indx, int val, int l = 0, int r = n, int id = 1) {
  if (indx < l or indx >= r) return;
  if (r - l == 1) {
    seg[id] = val;
    return;
  }
  int mid = (l + r) >> 1;
  update(indx, val, l, mid, id << 1 | 0);
  update(indx, val, mid, r, id << 1 | 1);
  seg[id] = max(seg[id << 1 | 0], seg[id << 1 | 1]);
}
int get(int st, int en, int l = 0, int r = n, int id = 1) {
  if (l >= en or r <= st) return 0;
  if (l >= st and r <= en) return seg[id];
  int mid = (l + r) >> 1;
  return max(get(st, en, l, mid, id << 1 | 0),
             get(st, en, mid, r, id << 1 | 1));
}
int32_t main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n;
  int v, u;
  for (int i = 1; i < n; i++)
    cin >> v >> u, edge[i] = {v, u}, g[v].push_back(u), g[u].push_back(v);
  root = 1;
  for (int i = 1; i <= n; i++)
    if (g[i].size() > g[root].size()) root = i;
  dfs(root);
  cin >> q;
  while (q--) {
    int type, id;
    cin >> type;
    if (type == 1) {
      cin >> id;
      if (height[edge[id].first] > height[edge[id].second])
        v = edge[id].first;
      else
        v = edge[id].second;
      update(st[v] - 1, 0);
    }
    if (type == 2) {
      cin >> id;
      if (height[edge[id].first] > height[edge[id].second])
        v = edge[id].first;
      else
        v = edge[id].second;
      update(st[v] - 1, 1);
    }
    if (type == 3) {
      cin >> v >> u;
      if (height[v] < height[u]) swap(v, u);
      if (v == u)
        cout << "0 \n";
      else if (u == root)
        if (get(st[par[v]] - 1, st[v]) == 0)
          cout << st[v] - st[par[v]] + 1 << "\n";
        else
          cout << "-1\n";
      else if (par[v] != par[u]) {
        if (get(st[par[u]] - 1, st[u]) == 0 and get(st[par[v]] - 1, st[v]) == 0)
          cout << height[v] + height[u] << "\n";
        else
          cout << "-1\n";
      } else if (get(st[u], st[v]) == 0)
        cout << st[v] - st[u] << "\n";
      else
        cout << "-1\n";
    }
  }
}

