#include <bits/stdc++.h>
using namespace std;
const int MAX = 100005;
struct Node {
  int l, r, del, s;
} t[MAX * 8];
struct node {
  int v, next;
} g[MAX * 2];
int adj[MAX], l[MAX], r[MAX], e, n, m, level[MAX], idx, deg[MAX];
int E[MAX][2], tr[MAX * 2], st, f[MAX], cnt, id[MAX], h[MAX];
void add(int u, int v) {
  g[e].v = v;
  g[e].next = adj[u];
  adj[u] = e++;
}
void dfs(int u, int fa, int d) {
  int i, v;
  l[u] = ++idx;
  level[u] = d;
  id[u] = ++cnt;
  if (fa == st)
    f[u] = u;
  else
    f[u] = f[fa];
  for (i = adj[u]; i != -1; i = g[i].next) {
    v = g[i].v;
    if (v == fa) continue;
    dfs(v, u, d + 1);
  }
  r[u] = ++idx;
  if (fa == st) h[u] = cnt;
}
void up(int i, int del, int high) {
  while (i <= high) {
    tr[i] += del;
    i += i & (-i);
  }
}
int read(int i, int low) {
  int res = 0;
  while (i >= low) {
    res += tr[i];
    i -= i & (-i);
  }
  return res;
}
void update(int u, int v, int del) {
  if (l[v] < l[u] && r[v] > r[u]) swap(u, v);
  up(id[v], del, h[f[v]]);
}
int query(int u, int v) {
  if (u == v) return 0;
  bool flag = false;
  if (l[u] < l[v] && r[u] > r[v]) flag = true;
  if (l[v] < l[u] && r[v] > r[u]) {
    flag = true;
    swap(u, v);
  }
  if (flag) {
    if (u != st) {
      int x = read(id[v], id[f[v]]) - read(id[u], id[f[u]]);
      if (x == level[v] - level[u])
        return level[v] - level[u];
      else
        return -1;
    } else {
      int x = read(id[v], id[f[v]]);
      if (x == level[v])
        return level[v];
      else
        return -1;
    }
  } else {
    int res = 0, x;
    if (u != st) {
      x = read(id[u], id[f[u]]);
      if (x != level[u]) return -1;
      res += level[u];
    }
    if (v != st) {
      x = read(id[v], id[f[v]]);
      if (x != level[v]) return -1;
      res += level[v];
    }
    return res;
  }
}
int main() {
  int i, j, k, ty;
  while (scanf("%d", &n) != EOF) {
    memset(adj, -1, sizeof(adj));
    e = 0;
    memset(deg, 0, sizeof(deg));
    memset(tr, 0, sizeof(tr));
    for (i = 0; i < n - 1; i++) {
      scanf("%d%d", &j, &k);
      E[i + 1][0] = j;
      E[i + 1][1] = k;
      add(j, k);
      add(k, j);
      deg[j]++;
      deg[k]++;
    }
    st = 1;
    for (i = 2; i <= n; i++)
      if (deg[i] > 2) {
        st = i;
        break;
      }
    idx = cnt = 0;
    dfs(st, -1, 0);
    scanf("%d", &m);
    for (i = 1; i <= n; i++) {
      if (i != st) {
        up(id[i], 1, h[f[i]]);
      }
    }
    while (m--) {
      scanf("%d", &ty);
      if (ty == 1) {
        scanf("%d", &k);
        update(E[k][0], E[k][1], 1);
      } else if (ty == 2) {
        scanf("%d", &k);
        update(E[k][0], E[k][1], -1);
      } else {
        scanf("%d%d", &i, &j);
        printf("%d\n", query(i, j));
      }
    }
  }
  return 0;
}

