#include <bits/stdc++.h>
using namespace std;
const int MAXN = 100005;
int head[MAXN], edge[MAXN << 1], next1[MAXN << 1], esz, from[MAXN], to[MAXN],
    dfs_clock, cent[MAXN], n;
int fa[MAXN], du[MAXN];
void addedge(int u, int v) {
  edge[esz] = v;
  next1[esz] = head[u];
  head[u] = esz++;
}
void dfs(int u, int p, int eid) {
  cent[u] = cent[p] + 1;
  if (eid != -1) {
    from[eid] = ++dfs_clock;
    fa[u] = eid;
  }
  for (int i = head[u]; i + 1; i = next1[i]) {
    int v = edge[i];
    if (v == p) continue;
    dfs(v, u, i >> 1);
  }
  if (eid != -1) to[eid] = dfs_clock;
}
int sum[MAXN];
void add(int p, int x) {
  while (p <= n) {
    sum[p] += x;
    p += ((-p) & p);
  }
}
int call(int p) {
  int res = 0;
  while (p >= 1) {
    res += sum[p];
    p -= ((-p) & p);
  }
  return res;
}
int fx(int u, int v) {
  if (cent[u] < cent[v]) swap(u, v);
  if (cent[u] - cent[v] == from[fa[u]] - from[fa[v]]) {
    int res = call(from[fa[u]]) - call(from[fa[v]]);
    if (res > 0)
      return -1;
    else
      return cent[u] - cent[v];
  } else {
    int res = call(from[fa[v]]) - call(from[fa[v]] - (cent[v] - 2) - 1);
    res += call(from[fa[u]]) - call(from[fa[u]] - (cent[u] - 2) - 1);
    if (res > 0)
      return -1;
    else
      return cent[u] + cent[v] - 2;
  }
}
int main() {
  memset(head, -1, sizeof(head));
  scanf("%d", &n);
  for (int i = 1; i < n; i++) {
    int u, v;
    scanf("%d%d", &u, &v);
    addedge(u, v);
    addedge(v, u);
    du[u]++;
    du[v]++;
  }
  int root = 1;
  for (int i = 1; i <= n; i++) {
    if (du[i] > 2) {
      root = i;
      break;
    }
  }
  dfs(root, 0, -1);
  int m;
  scanf("%d", &m);
  while (m--) {
    int f, u, v;
    scanf("%d", &f);
    if (f == 1) {
      scanf("%d", &u);
      add(from[u - 1], -1);
    } else if (f == 2) {
      scanf("%d", &u);
      add(from[u - 1], 1);
    } else {
      scanf("%d%d", &u, &v);
      if (u == v)
        printf("0\n");
      else {
        int x = 0;
        if (v == root) swap(u, v);
        if (u == root) {
          x += call(from[fa[v]]) - call(from[fa[v]] - (cent[v] - 2) - 1);
          if (x > 0)
            printf("-1\n");
          else
            printf("%d\n", cent[v] - 1);
        } else {
          printf("%d\n", fx(u, v));
        }
      }
    }
  }
  return 0;
}

solution_14:
#include <bits/stdc++.h>
using namespace std;
vector<int> g[100001], edgesid[100001], dfs_list, lca_tree, edgeslist, tree1,
    tree2;
int x, type, z, ans, i, n, u, v, first[100001], m, first1[100001],
    first2[100001], h[100001];
void dfs(int v, int p = -1, int H = 0) {
  h[v] = H;
  dfs_list.push_back(v);
  for (int w = 0; w < g[v].size(); w++)
    if (h[g[v][w]] == -1) {
      edgeslist.push_back(edgesid[v][w]);
      dfs(g[v][w], v, H + 1);
      edgeslist.push_back(edgesid[v][w]);
      dfs_list.push_back(v);
    }
}
void build_lca_tree(int v, int l, int r) {
  if (l == r)
    lca_tree[v] = dfs_list[l];
  else {
    int m = (l + r) >> 1;
    build_lca_tree(v + v, l, m);
    build_lca_tree(v + v + 1, m + 1, r);
    int lt = lca_tree[v + v], rt = lca_tree[v + v + 1];
    lca_tree[v] = ((h[lt] < h[rt]) ? lt : rt);
  }
}
void prepare_lca() {
  lca_tree.assign(dfs_list.size() * 4, -1);
  build_lca_tree(1, 0, dfs_list.size() - 1);
  int i, v;
  for (i = 1; i <= n; i++) first[i] = -1;
  for (i = 0; i < dfs_list.size(); i++) {
    v = dfs_list[i];
    if (first[v] == -1) first[v] = i;
  }
}
void query_prepare() {
  int i, j;
  for (i = 1; i < n; i++) first1[i] = first2[i] = -1;
  for (i = 0; i < edgeslist.size(); i++) {
    j = edgeslist[i];
    if (first1[j] == -1)
      first1[j] = i;
    else
      first2[j] = i;
  }
  tree1.assign(edgeslist.size() * 4, 0);
  tree2.assign(edgeslist.size() * 4, 0);
}
int lca_query(int v, int tl, int tr, int l, int r) {
  if ((tl == l) && (tr == r)) return lca_tree[v];
  int tm = (tl + tr) >> 1;
  if (r <= tm) return lca_query(v + v, tl, tm, l, r);
  if (l > tm) return lca_query(v + v + 1, tm + 1, tr, l, r);
  int lt = lca_query(v + v, tl, tm, l, tm);
  int rt = lca_query(v + v + 1, tm + 1, tr, tm + 1, r);
  return ((h[lt] < h[rt]) ? lt : rt);
}
int calc_lca(int a, int b) {
  if (first[a] > first[b]) swap(a, b);
  return lca_query(1, 0, dfs_list.size() - 1, first[a], first[b]);
}
int sum_query(const vector<int>& tree, int v, int tl, int tr, int l, int r) {
  if ((l > r) || (tl > tr)) return 0;
  if ((tl == l) && (tr == r)) return tree[v];
  int tm = (tl + tr) >> 1;
  if (r <= tm) return sum_query(tree, v + v, tl, tm, l, r);
  if (l > tm) return sum_query(tree, v + v + 1, tm + 1, tr, l, r);
  int X = sum_query(tree, v + v, tl, tm, l, tm);
  int Y = sum_query(tree, v + v + 1, tm + 1, tr, tm + 1, r);
  return (X + Y);
}
int color_count(int v1, int v2) {
  int X =
      sum_query(tree1, 1, 0, edgeslist.size() - 1, first[v1], first[v2] - 1);
  int Y =
      sum_query(tree2, 1, 0, edgeslist.size() - 1, first[v1], first[v2] - 1);
  return (X - Y);
}
void edgestree_update(vector<int>& tree, int v, int tl, int tr, int p, int c) {
  if (tl == tr) {
    tree[v] = c;
    return;
  }
  int tm = (tl + tr) >> 1;
  if (p <= tm)
    edgestree_update(tree, v + v, tl, tm, p, c);
  else
    edgestree_update(tree, v + v + 1, tm + 1, tr, p, c);
  tree[v] = tree[v + v] + tree[v + v + 1];
}
int main() {
  scanf("%d", &n);
  for (i = 1; i < n; i++) {
    scanf("%d%d", &u, &v);
    g[u].push_back(v);
    g[v].push_back(u);
    edgesid[u].push_back(i);
    edgesid[v].push_back(i);
  }
  for (i = 1; i <= n; i++) h[i] = -1;
  edgeslist.clear();
  dfs_list.clear();
  dfs(1);
  prepare_lca();
  query_prepare();
  for (scanf("%d", &m); m; m--) {
    scanf("%d", &type);
    if (type == 3) {
      scanf("%d%d", &u, &v);
      z = calc_lca(u, v);
      ans = color_count(z, u) + color_count(z, v);
      if (ans == 0)
        ans = h[u] + h[v] - 2 * h[z];
      else
        ans = -1;
      printf("%d\n", ans);
    }
    if (type == 1) {
      scanf("%d", &x);
      edgestree_update(tree1, 1, 0, edgeslist.size() - 1, first1[x], 0);
      edgestree_update(tree2, 1, 0, edgeslist.size() - 1, first2[x], 0);
    }
    if (type == 2) {
      scanf("%d", &x);
      edgestree_update(tree1, 1, 0, edgeslist.size() - 1, first1[x], 1);
      edgestree_update(tree2, 1, 0, edgeslist.size() - 1, first2[x], 1);
    }
  }
  return 0;
}

solution_15:
#include <bits/stdc++.h>
using namespace std;
const double EPS = 1e-9;
const double PI = 3.14159265359;
vector<long long> primes;
void GeneratingPrimes(int top) {
  vector<bool> p(top + 1, 1);
  p[0] = p[1] = 0;
  for (int i = 2; i <= sqrt(top); i++) {
    if (p[i]) {
      for (int j = i * i; j <= top; j += i) {
        p[j] = 0;
      }
    }
  }
  for (int i = 0; i < top + 1; i++)
    if (p[i]) primes.push_back(i);
}
long long gcd(long long a, long long b) { return (b == 0) ? a : gcd(b, a % b); }
long long lcm(long long a, long long b) { return (a * b) / gcd(a, b); }
void EXTgcd(long long a, long long b, long long& x0, long long& y0) {
  if (b == 0) {
    x0 = 1, y0 = 0;
    return;
  }
  EXTgcd(b, a % b, x0, y0);
  long long x1 = y0;
  long long y1 = x0 - (a / b) * (y0);
  y1 = y1;
  x0 = x1;
  y0 = y1;
}
long long power(long long n, long long p, long long mod) {
  if (!p) return 1;
  long long ans = 1;
  while (p > 1) {
    if (p & 1) ans = (ans * n) % mod;
    n = (n * n) % mod;
    p /= 2;
  }
  return (ans * n) % mod;
}
double dist(double a, double b, double x, double y) {
  return sqrt(pow(a - x, 2) + pow(b - y, 2));
}
double dist3(double a, double b, double c, double x, double y, double z) {
  return sqrt(pow(a - x, 2) + pow(b - y, 2) + pow(c - z, 2));
}
int xadd[9] = {1, -1, 0, 1, -1, 0, 1, -1, 0};
int yadd[9] = {1, -1, 0, -1, 0, 1, 0, 1, -1};
int xx[4] = {0, 1, 0, -1};
int yy[4] = {1, 0, -1, 0};
long long const N = 1e5 + 10;
long long const INF = 1e18;
long long const mod = 998244353;
int n, q, h[N], dsuPar[N], root = 0, curT = 1;
set<int> afterWhite[N];
map<int, pair<int, int> > eIdx;
vector<int> e[N];
int F(int x) {
  if (x == dsuPar[x]) return x;
  dsuPar[x] = F(dsuPar[x]);
  return dsuPar[x];
}
void U(int x, int y) {
  x = F(x), y = F(y);
  dsuPar[x] = y;
}
void dfs(int idx, int par = -1) {
  if (~par) h[idx] = h[par] + 1;
  for (int to : e[idx])
    if (to != par) {
      if (idx != root) U(to, idx);
      dfs(to, idx);
    }
}
int main() {
  cin >> n;
  for (int i = 0; i < n + 5; i++) dsuPar[i] = i;
  for (int i = 0; i < n - 1; i++) {
    int x, y;
    scanf("%d", &x), scanf("%d", &y);
    eIdx[i + 1] = make_pair(x, y);
    e[x].push_back(y);
    e[y].push_back(x);
  }
  for (int i = 1; i <= n; i++)
    if (e[i].size() > e[root].size()) root = i;
  dfs(root);
  cin >> q;
  while (q--) {
    int type, u, v;
    scanf("%d", &type);
    if (type == 1) {
      int idx, par;
      scanf("%d", &idx);
      u = eIdx[idx].first, v = eIdx[idx].second;
      if (h[u] > h[v]) swap(u, v);
      par = F(v);
      afterWhite[par].erase(h[v]);
    } else if (type == 2) {
      int idx, par;
      scanf("%d", &idx);
      u = eIdx[idx].first, v = eIdx[idx].second;
      if (h[u] > h[v]) swap(u, v);
      par = F(v);
      afterWhite[par].insert(h[v]);
    } else {
      scanf("%d", &u), scanf("%d", &v);
      if (u == v) {
        printf("%d\n", 0);
        continue;
      }
      if (h[u] > h[v]) swap(u, v);
      int parU = F(u), parV = F(v);
      if (parU == parV) {
        auto it = afterWhite[parU].upper_bound(h[u]);
        if (it == afterWhite[parU].end() || *it > h[v]) {
          printf("%d\n", h[v] - h[u]);
        } else {
          printf("%d\n", -1);
        }
      } else {
        if (u == root) {
          auto it = afterWhite[parV].lower_bound(1);
          if (it == afterWhite[parV].end() || *it > h[v])
            printf("%d\n", h[v]);
          else
            printf("%d\n", -1);
        } else {
          auto it1 = afterWhite[parU].lower_bound(1);
          auto it2 = afterWhite[parV].lower_bound(1);
          if ((*it1 <= h[u] && it1 != afterWhite[parU].end()) ||
              *it2 <= h[v] && it2 != afterWhite[parV].end())
            printf("%d\n", -1);
          else
            printf("%d\n", h[u] + h[v]);
        }
      }
    }
  }
  return 0;
}

solution_16:
#include <bits/stdc++.h>
using namespace std;
int posInBase[100005];
int baseArray[100005];
int edgeEnd[100005];
int chainIdx[100005];
int chainHead[100005];
int subsize[100005];
int tree[3 * 100005];
int L[100005];
int An[100005][20];
int dis[100005];
int pos, chainNo;
vector<int> edge[100005], edgeIdx[100005];
void dfs(int f, int u, int d) {
  An[u][0] = f;
  L[u] = d;
  subsize[u] = 1;
  for (int i = 0; i < edge[u].size(); i++) {
    int v = edge[u][i];
    int edgeNo = edgeIdx[u][i];
    if (v != f) {
      edgeEnd[edgeNo] = v;
      dfs(u, v, d + 1);
      subsize[u] += subsize[v];
    }
  }
}
void HLD(int f, int curNode) {
  if (chainHead[chainNo] == -1) {
    chainHead[chainNo] = curNode;
  }
  ++pos;
  chainIdx[curNode] = chainNo;
  posInBase[curNode] = pos;
  baseArray[pos] = 1;
  int sc = -1, maxsize = -1;
  for (int i = 0; i < edge[curNode].size(); i++) {
    int v = edge[curNode][i];
    if (v != f and maxsize < subsize[v]) {
      maxsize = subsize[v];
      sc = v;
    }
  }
  if (sc != -1) {
    HLD(curNode, sc);
  }
  for (int i = 0; i < edge[curNode].size(); i++) {
    int v = edge[curNode][i];
    if (sc != v and f != v) {
      ++chainNo;
      HLD(curNode, v);
    }
  }
}
void sparsetable(int n) {
  for (int j = 1; (1 << j) < n; j++) {
    for (int i = 0; i < n; i++) {
      if (An[i][j - 1] != -1) {
        An[i][j] = An[An[i][j - 1]][j - 1];
      }
    }
  }
}
int LCA(int p, int q) {
  if (L[p] < L[q]) swap(p, q);
  int log = 1;
  while (1) {
    int next = log + 1;
    if ((1 << next) > L[p]) break;
    log++;
  }
  for (int i = log; i >= 0; i--) {
    if (L[p] - (1 << i) >= L[q]) {
      p = An[p][i];
    }
  }
  if (p == q) return p;
  for (int i = log; i >= 0; i--) {
    if (An[p][i] != -1 and An[p][i] != An[q][i]) {
      p = An[p][i];
      q = An[q][i];
    }
  }
  return An[p][0];
}
void Make_tree(int node, int s, int e) {
  if (s == e) {
    tree[node] = baseArray[s];
    return;
  }
  int mid = (s + e) / 2;
  int left = node << 1;
  int right = left + 1;
  Make_tree(left, s, mid);
  Make_tree(right, mid + 1, e);
  tree[node] = tree[left] + tree[right];
}
void Update(int node, int s, int e, int i, int color) {
  if (s > i or e < i) return;
  if (s == e and s == i) {
    tree[node] = color;
    return;
  }
  int mid = (s + e) / 2;
  int left = node << 1;
  int right = left + 1;
  Update(left, s, mid, i, color);
  Update(right, mid + 1, e, i, color);
  tree[node] = tree[left] + tree[right];
}
int query_tree(int node, int s, int e, int i, int j) {
  if (s > j or e < i) return 0;
  if (s >= i and e <= j) return tree[node];
  int mid = (s + e) / 2;
  int left = node << 1;
  int right = left + 1;
  int a = query_tree(left, s, mid, i, j);
  int b = query_tree(right, mid + 1, e, i, j);
  return a + b;
}
int query_up(int lca, int u) {
  int uchain = chainIdx[u];
  int vchain = chainIdx[lca];
  int sum = 0;
  Update(1, 1, pos, posInBase[lca], 0);
  while (1) {
    if (uchain == vchain) {
      int ans = query_tree(1, 1, pos, posInBase[lca], posInBase[u]);
      sum += ans;
      break;
    } else {
      int head = chainHead[uchain];
      int ans = query_tree(1, 1, pos, posInBase[head], posInBase[u]);
      sum += ans;
      u = An[head][0];
      uchain = chainIdx[u];
    }
  }
  return sum;
}
int query(int u, int v) {
  int lca = LCA(u, v);
  int aa = query_tree(1, 1, pos, posInBase[lca], posInBase[lca]);
  int ans = query_up(lca, u);
  int temp = query_up(lca, v);
  Update(1, 1, pos, posInBase[lca], aa);
  if ((L[u] + L[v] - 2 * L[lca]) != (ans + temp))
    return -1;
  else
    return ans + temp;
}
int main() {
  int n;
  while (scanf("%d", &n) != EOF) {
    for (int i = 0; i <= n; i++) {
      edge[i].clear();
      chainHead[i] = -1;
      edgeIdx[i].clear();
    }
    int u, v;
    for (int i = 1; i < n; i++) {
      scanf("%d%d", &u, &v);
      u--, v--;
      edge[u].push_back(v);
      edge[v].push_back(u);
      edgeIdx[u].push_back(i);
      edgeIdx[v].push_back(i);
    }
    memset(An, -1, sizeof(An));
    pos = 0;
    chainNo = 1;
    dfs(-1, 0, 0);
    HLD(-1, 0);
    Make_tree(1, 1, pos);
    sparsetable(n);
    int q;
    scanf("%d", &q);
    int flag;
    for (int i = 0; i < q; i++) {
      scanf("%d", &flag);
      if (flag == 1) {
        scanf("%d", &u);
        Update(1, 1, pos, posInBase[edgeEnd[u]], 1);
      } else if (flag == 2) {
        scanf("%d", &u);
        Update(1, 1, pos, posInBase[edgeEnd[u]], 0);
      } else {
        scanf("%d%d", &u, &v);
        u--, v--;
        int ans = query(u, v);
        printf("%d\n", ans);
      }
    }
  }
}

solution_17:
#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 10;
int n, m;
struct node {
  int x, y;
} ed[maxn];
int beg[maxn], nex[maxn << 1], to[maxn << 1], e;
int sz[maxn], dep[maxn], f[maxn][20], son[maxn];
int id[maxn], num[maxn], top[maxn], cnt;
int tr[maxn << 2];
inline int read() {
  int x = 0, f = 1;
  char c = getchar();
  while (c < '0' || c > '9') {
    if (c == '-') f = -1;
    c = getchar();
  }
  while (c >= '0' && c <= '9') {
    x = (x << 1) + (x << 3) + c - '0';
    c = getchar();
  }
  return x * f;
}
inline void add(int x, int y) {
  e++;
  nex[e] = beg[x];
  beg[x] = e;
  to[e] = y;
}
inline void dfs1(int x, int fa) {
  sz[x] = 1;
  f[x][0] = fa;
  dep[x] = dep[fa] + 1;
  for (int i = 1; i <= 19; i++) f[x][i] = f[f[x][i - 1]][i - 1];
  for (int i = beg[x]; i; i = nex[i]) {
    int t = to[i];
    if (t == fa) continue;
    dfs1(t, x);
    sz[x] += sz[t];
    if (sz[t] > sz[son[x]]) son[x] = t;
  }
}
inline int lca(int x, int y) {
  if (dep[x] < dep[y]) swap(x, y);
  for (int i = 19; i >= 0; i--)
    if (dep[x] - (1 << i) >= dep[y]) x = f[x][i];
  if (x == y) return x;
  for (int i = 19; i >= 0; i--)
    if (f[x][i] != f[y][i]) {
      x = f[x][i];
      y = f[y][i];
    }
  return f[x][0];
}
inline void dfs2(int x, int topc) {
  id[x] = ++cnt;
  num[cnt] = (x != 1);
  top[x] = topc;
  if (!son[x]) return;
  dfs2(son[x], topc);
  for (int i = beg[x]; i; i = nex[i]) {
    int t = to[i];
    if (t == son[x] || t == f[x][0]) continue;
    dfs2(t, t);
  }
}
inline void build(int h, int l, int r) {
  if (l == r) {
    tr[h] = num[l];
    return;
  }
  int mid = (l + r) >> 1;
  build(h << 1, l, mid);
  build(h << 1 | 1, mid + 1, r);
  tr[h] = tr[h << 1] + tr[h << 1 | 1];
}
inline void update(int h, int l, int r, int x, int y) {
  if (l == r) {
    tr[h] = y;
    return;
  }
  int mid = (l + r) >> 1;
  if (mid >= x)
    update(h << 1, l, mid, x, y);
  else
    update(h << 1 | 1, mid + 1, r, x, y);
  tr[h] = tr[h << 1] + tr[h << 1 | 1];
}
inline int query(int h, int l, int r, int x, int y) {
  if (l > y || r < x) return 0;
  if (l >= x && r <= y) return tr[h];
  int mid = (l + r) >> 1;
  return query(h << 1, l, mid, x, y) + query(h << 1 | 1, mid + 1, r, x, y);
}
inline int qc(int x, int y) {
  int ans = 0;
  while (top[x] != top[y]) {
    if (dep[top[x]] < dep[top[y]]) swap(x, y);
    ans += query(1, 1, n, id[top[x]], id[x]);
    x = f[top[x]][0];
  }
  if (x == y) return ans;
  if (dep[x] > dep[y]) swap(x, y);
  ans += query(1, 1, n, id[x] + 1, id[y]);
  return ans;
}
int main() {
  n = read();
  int x, y, z;
  for (int i = 1; i < n; i++) {
    x = read(), y = read();
    ed[i] = (node){x, y};
    add(x, y), add(y, x);
  }
  dfs1(1, 0);
  dfs2(1, 1);
  build(1, 1, n);
  m = read();
  for (int i = 1; i <= m; i++) {
    x = read();
    if (x == 1) {
      y = read();
      update(1, 1, n, dep[ed[y].x] > dep[ed[y].y] ? id[ed[y].x] : id[ed[y].y],
             1);
    } else if (x == 2) {
      y = read();
      update(1, 1, n, dep[ed[y].x] > dep[ed[y].y] ? id[ed[y].x] : id[ed[y].y],
             0);
    } else {
      y = read(), z = read();
      printf("%d\n", qc(y, z) == (dep[y] + dep[z] - 2 * dep[lca(y, z)])
                         ? qc(y, z)
                         : -1);
    }
  }
  return 0;
}

