#include <bits/stdc++.h>
using namespace std;
template <typename T, typename U>
inline void smin(T &a, const U &b) {
  if (a > b) a = b;
}
template <typename T, typename U>
inline void smax(T &a, const U &b) {
  if (a < b) a = b;
}
template <class T>
inline void gn(T &first) {
  char c, sg = 0;
  while (c = getchar(), (c > '9' || c < '0') && c != '-')
    ;
  for ((c == '-' ? sg = 1, c = getchar() : 0), first = 0; c >= '0' && c <= '9';
       c = getchar())
    first = (first << 1) + (first << 3) + c - '0';
  if (sg) first = -first;
}
template <class T1, class T2>
inline void gn(T1 &x1, T2 &x2) {
  gn(x1), gn(x2);
}
template <class T1, class T2, class T3>
inline void gn(T1 &x1, T2 &x2, T3 &x3) {
  gn(x1, x2), gn(x3);
}
template <class T>
inline void print(T first) {
  if (first < 0) {
    putchar('-');
    return print(-first);
  }
  if (first < 10) {
    putchar('0' + first);
    return;
  }
  print(first / 10);
  putchar(first % 10 + '0');
}
template <class T>
inline void println(T first) {
  print(first);
  putchar('\n');
}
template <class T>
inline void printsp(T first) {
  print(first);
  putchar(' ');
}
template <class T1, class T2>
inline void print(T1 x1, T2 x2) {
  printsp(x1), println(x2);
}
template <class T1, class T2, class T3>
inline void print(T1 x1, T2 x2, T3 x3) {
  printsp(x1), printsp(x2), println(x3);
}
int power(int a, int b, int m, int ans = 1) {
  for (; b; b >>= 1, a = (long long)a * a % m)
    if (b & 1) ans = (long long)ans * a % m;
  return ans;
}
bool rev[200010];
int pa[200010], son[200010][2], val[200010];
int sum[200010], sz[200010];
void push_up(int first) {
  int L = son[first][0], R = son[first][1];
  sum[first] = sum[L] + sum[R] + val[first];
  sz[first] = sz[L] + sz[R] + 1;
}
void push_down(int first) {
  int L = son[first][0], R = son[first][1];
  if (rev[first]) {
    swap(son[first][0], son[first][1]);
    rev[L] ^= 1;
    rev[R] ^= 1;
    rev[first] = 0;
  }
}
bool isroot(int first) {
  return son[pa[first]][0] != first && son[pa[first]][1] != first;
}
void down(int first) {
  if (!isroot(first)) down(pa[first]);
  push_down(first);
}
void rot(int first, int d) {
  int second = pa[first], z = pa[second];
  son[second][!d] = son[first][d];
  pa[son[first][d]] = second;
  pa[first] = pa[second];
  if (son[z][0] == second)
    son[z][0] = first;
  else if (son[z][1] == second)
    son[z][1] = first;
  pa[second] = first;
  son[first][d] = second;
  push_up(second);
}
void splay(int first) {
  down(first);
  while (!isroot(first)) {
    if (isroot(pa[first]))
      rot(first, son[pa[first]][0] == first);
    else {
      int second = pa[first], z = pa[second];
      int d = (son[z][0] == second);
      son[second][d] == first ? rot(first, !d) : rot(second, d);
      rot(first, d);
    }
  }
  push_up(first);
}
void access(int first) {
  for (int second = 0; first; first = pa[first]) {
    splay(first);
    son[first][1] = second;
    push_up(second = first);
  }
}
void make_root(int first) {
  access(first);
  splay(first);
  rev[first] ^= 1;
}
void link(int first, int second) {
  make_root(first);
  splay(first);
  pa[first] = second;
}
pair<int, int> p[200010 >> 1];
int main() {
  int n;
  gn(n);
  for (int i = 1; i < n; i++) {
    gn(p[i].first, p[i].second);
    int u = p[i].first, v = p[i].second;
    link(u, n + i);
    link(v, n + i);
  }
  int m;
  gn(m);
  while (m--) {
    int t, first, second;
    gn(t);
    if (t == 1) {
      gn(first);
      first += n;
      splay(first);
      val[first] = 0;
      sum[first]--;
    }
    if (t == 2) {
      gn(first);
      first += n;
      splay(first);
      val[first] = 1;
      sum[first]++;
    }
    if (t == 3) {
      gn(first, second);
      make_root(first);
      access(second);
      splay(second);
      int size = sz[second] >> 1;
      if (sum[second])
        puts("-1");
      else
        println(size);
    }
  }
}

solution_19:
#include <bits/stdc++.h>
using namespace std;
const int maxn = 120000;
struct node {
  int d, a, b;
  node *next;
} * lin[maxn], ss[maxn];
int f[maxn], w[maxn], d[maxn], own[maxn];
int s[maxn], m[maxn];
int L;
void ins(int a, int b) {
  node *p = new node;
  p->d = b;
  p->next = lin[a];
  lin[a] = p;
}
void build(int t, int fa) {
  node *p = lin[t];
  f[t] = fa;
  if (fa == -1)
    d[t] = 0;
  else
    d[t] = d[fa] + 1;
  while (p != NULL) {
    if (p->d != fa) {
      if (++s[own[t]] < L) own[p->d] = own[t];
      build(p->d, t);
    }
    p = p->next;
  }
}
void dfs(int t, int fa) {
  node *p = lin[t];
  if (fa != -1)
    s[t] = s[fa] + w[t], m[t] = min(w[t], m[fa]);
  else
    s[t] = w[t], m[t] = w[t];
  while (p != NULL) {
    if (p->d != fa && own[p->d] == own[t]) {
      dfs(p->d, t);
    }
    p = p->next;
  }
}
void calc(int a, int b, int &M, int &S) {
  S = 0;
  M = 2;
  while (a != b) {
    if (own[a] == own[b]) {
      if (d[a] < d[b]) swap(a, b);
      M = min(w[a], M);
      S += w[a];
      a = f[a];
    } else {
      if (d[own[a]] < d[own[b]]) swap(a, b);
      M = min(m[a], M);
      S += s[a];
      a = f[own[a]];
    }
  }
}
int main() {
  int n;
  scanf("%d", &n);
  L = int(sqrt(n)) / 2 * 1;
  for (int i = 1; i <= n; i++) lin[i] = NULL, own[i] = i;
  for (int i = 1; i <= n - 1; i++) {
    int a, b;
