    ins(ss[i].a, ss[i].b);
    ins(ss[i].b, ss[i].a);
  }
  memset(s, 0, sizeof(s));
  for (int i = 1; i <= n; i++) w[i] = 1;
  build(rand() % n + 1, -1);
  for (int i = 1; i <= n; i++)
    if (own[i] == i) dfs(i, -1);
  int r;
