#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e6 + 10;
const int inf = 1 << 29;
int n, x;
int l[maxn], r[maxn];
bool canl[maxn], canr[maxn];
vector<int> pos[maxn];
int main() {
  scanf("%d%d", &n, &x);
  int tmp;
  for (int i = 1; i <= n; i++) {
    scanf("%d", &tmp);
    pos[tmp].push_back(i);
  }
  memset(canl, false, sizeof(canl));
  memset(canr, false, sizeof(canr));
  int p = -1;
  for (int i = 0; i <= x; i++) {
    if (pos[i].empty()) {
      canr[i + 1] = true;
      r[i + 1] = p;
      continue;
    }
    if (pos[i][0] > p) {
      canr[i + 1] = true;
      r[i + 1] = p = pos[i].back();
    } else
      break;
  }
  p = inf;
  for (int i = x + 1; i >= 1; i--) {
    if (pos[i].empty()) {
      canl[i - 1] = true;
      l[i - 1] = p;
      continue;
    }
    if (pos[i].back() <= p) {
      canl[i - 1] = true;
      l[i - 1] = p = pos[i][0];
    } else
      break;
  }
  long long ans = 0;
  int pp = 0;
  for (int i = 1; i <= x && canr[i]; i++) {
    while (pp < x && (pp < i || !canl[pp] || l[pp] < r[i])) pp++;
    ans += (x - pp + 1);
  }
  printf("%lld\n", ans);
  return 0;
}

solution_3:
#include <bits/stdc++.h>
using namespace std;
int a[1000005], pre[1000005], suf[1000005], n, x, Min = 1000000007, Max;
int lst[1000005], fst[1000005], lst2[1000005];
bool check(int l, int r) {
  if (pre[l - 1] && suf[r + 1] && lst[l - 1] <= fst[r + 1]) return true;
  return false;
}
int main() {
  scanf("%d%d", &n, &x);
  bool flg = true;
  for (int i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
    if (a[i] < a[i - 1]) flg = false;
    if (fst[a[i]] == 0) fst[a[i]] = i;
    lst[a[i]] = i;
    lst2[a[i]] = i;
    Min = min(Min, a[i]);
    Max = max(Max, a[i]);
  }
  for (int i = 1; i <= x; i++)
    if (fst[i] == 0) fst[i] = n + 1;
  if (flg) return !printf("%lld", 1LL * x * (x + 1) / 2);
  for (int i = 0; i <= Min; i++) pre[i] = true;
  for (int i = Max + 1; i <= x + 1; i++) suf[i] = true, fst[i] = n;
  for (int i = 1; i <= x; i++)
    if (pre[i - 1] == true && fst[i] >= lst[i - 1])
      pre[i] = true, lst[i] = max(lst[i], lst[i - 1]);
  for (int i = x; i >= 1; i--)
    if (suf[i + 1] == true && lst2[i] <= fst[i + 1])
      suf[i] = true, fst[i] = min(fst[i], fst[i + 1]);
  long long ans = 0;
  for (int i = 1; i <= x; i++) {
    if (check(i, x) == false) break;
    if (check(i, i) == true) {
      ans += x - i + 1;
      continue;
    }
    int l = i, r = x;
    while (l < r - 1) {
      int mid = (l + r) >> 1;
      if (check(i, mid))
        r = mid;
      else
        l = mid;
    }
    ans += x - r + 1;
  }
  printf("%lld", ans);
}

solution_4:
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.Charset;
import java.util.*;

public class CFContest {
    public static void main(String[] args) throws Exception {
        boolean local = System.getProperty("ONLINE_JUDGE") == null;
        boolean async = false;

        Charset charset = Charset.forName("ascii");

        FastIO io = local ? new FastIO(new FileInputStream("D:\\DATABASE\\TESTCASE\\Code.in"), System.out, charset) : new FastIO(System.in, System.out, charset);
        Task task = new Task(io, new Debug(local));

        if (async) {
            Thread t = new Thread(null, task, "dalt", 1 << 27);
            t.setPriority(Thread.MAX_PRIORITY);
            t.start();
            t.join();
        } else {
            task.run();
        }

        if (local) {
            io.cache.append("\n\n--memory -- \n" + ((Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory()) >> 20) + "M");
        }

        io.flush();
    }

    public static class Task implements Runnable {
        final FastIO io;
        final Debug debug;
        int inf = (int) 1e8;
        int mod = (int) 1e9 + 7;

        public int mod(int val) {
            val %= mod;
            if (val < 0) {
                val += mod;
            }
            return val;
        }

        public int mod(long val) {
            val %= mod;
            if (val < 0) {
                val += mod;
            }
            return (int) val;
        }

        int bitAt(int x, int i) {
            return (x >> i) & 1;
        }

        int bitAt(long x, int i) {
            return (int) ((x >> i) & 1);
        }

        public Task(FastIO io, Debug debug) {
            this.io = io;
            this.debug = debug;
        }

        @Override
        public void run() {
            solve();
        }

        public void solve() {
            int n = io.readInt();
            int x = io.readInt();
            int[] rIndex = new int[x + 1];
            int[] lIndex = new int[x + 1];

            int[] lMax = new int[n + 1];
            int[] rMin = new int[n + 1];
            Arrays.fill(rIndex, -1);
            Arrays.fill(lIndex, -1);
            int[] vals = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                vals[i] = io.readInt();
                rIndex[vals[i]] = i;
                if (lIndex[vals[i]] == -1) {
                    lIndex[vals[i]] = i;
                }
            }

            for (int i = 1; i <= n; i++) {
                lMax[i] = Math.max(lMax[i - 1], vals[i]);
            }
            rMin[n] = vals[n];
            for (int i = n - 1; i >= 1; i--) {
                rMin[i] = Math.min(rMin[i + 1], vals[i]);
            }

            int lMost = x;
            int rMost = 1;
            for (int i = 1; i <= x; i++) {
                if (lIndex[i] == -1) {
                    continue;
                }
                if (rMin[lIndex[i]] < i) {
                    lMost = Math.min(lMost, i - 1);
                    break;
                }
            }

            for(int i = x; i >= 1; i--)
            {
                if (lIndex[i] == -1) {
                    continue;
                }
                if (lMax[rIndex[i]] > i) {
                    rMost = Math.max(rMost, i + 1);
                    break;
                }
            }

            long total = 0;
            int max = rMost - 1;
            for (int i = 1; i <= lMost + 1; i++) {
                if (lIndex[i - 1] == -1) {
                    int notUntil = Math.max(max, i);
                    total += x - notUntil + 1;
                } else {
                    max = Math.max(max, lMax[rIndex[i - 1]]);
                    int notUntil = Math.max(max, i);
                    total += x - notUntil + 1;
                }
            }

            io.cache.append(total);
        }
    }

    public static class Node {
        Node p = this;
        int rank = 0;
        int size = 1;

        public Node find() {
            return p.p == p ? p : (p = p.find());
        }

        static void union(Node a, Node b) {
            a = a.find();
            b = b.find();
            if (a == b) {
                return;
            }
            if (a.rank == b.rank) {
                a.rank++;
            }
            if (a.rank > b.rank) {
                b.p = a;
                a.size += b.size;
            } else {
                a.p = b;
                b.size += a.size;
            }
        }
    }

    public static class FastIO {
        public final StringBuilder cache = new StringBuilder();
        private final InputStream is;
        private final OutputStream os;
        private final Charset charset;
        private StringBuilder defaultStringBuf = new StringBuilder(1 << 8);
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastIO(InputStream is, OutputStream os, Charset charset) {
            this.is = is;
            this.os = os;
            this.charset = charset;
        }

        public FastIO(InputStream is, OutputStream os) {
            this(is, os, Charset.forName("ascii"));
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public long readLong() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            long val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public double readDouble() {
            boolean sign = true;
            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+';
                next = read();
            }

            long val = 0;
            while (next >= '0' && next <= '9') {
                val = val * 10 + next - '0';
                next = read();
            }
            if (next != '.') {
                return sign ? val : -val;
            }
            next = read();
            long radix = 1;
            long point = 0;
            while (next >= '0' && next <= '9') {
                point = point * 10 + next - '0';
                radix = radix * 10;
                next = read();
            }
            double result = val + (double) point / radix;
            return sign ? result : -result;
        }

        public String readString(StringBuilder builder) {
            skipBlank();

            while (next > 32) {
                builder.append((char) next);
                next = read();
            }

            return builder.toString();
        }

        public String readString() {
            defaultStringBuf.setLength(0);
            return readString(defaultStringBuf);
        }

        public int readLine(char[] data, int offset) {
            int originalOffset = offset;
            while (next != -1 && next != '\n') {
                data[offset++] = (char) next;
                next = read();
            }
            return offset - originalOffset;
        }

        public int readString(char[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (char) next;
                next = read();
            }

            return offset - originalOffset;
        }

        public int readString(byte[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (byte) next;
                next = read();
            }

            return offset - originalOffset;
        }

        public char readChar() {
            skipBlank();
            char c = (char) next;
            next = read();
            return c;
        }

        public void flush() {
            try {
                os.write(cache.toString().getBytes(charset));
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public boolean hasMore() {
            skipBlank();
            return next != -1;
        }
    }

    public static class Debug {
        private boolean allowDebug;

        public Debug(boolean allowDebug) {
            this.allowDebug = allowDebug;
        }

        public void assertTrue(boolean flag) {
            if (!allowDebug) {
                return;
            }
            if (!flag) {
                fail();
            }
        }

        public void fail() {
            throw new RuntimeException();
        }

        public void assertFalse(boolean flag) {
            if (!allowDebug) {
                return;
            }
            if (flag) {
                fail();
            }
        }

        private void outputName(String name) {
            System.out.print(name + " = ");
        }

        public void debug(String name, int x) {
            if (!allowDebug) {
                return;
            }

            outputName(name);
            System.out.println("" + x);
        }

        public void debug(String name, long x) {
            if (!allowDebug) {
                return;
            }
            outputName(name);
            System.out.println("" + x);
        }

        public void debug(String name, double x) {
            if (!allowDebug) {
                return;
            }
            outputName(name);
            System.out.println("" + x);
        }

        public void debug(String name, int[] x) {
            if (!allowDebug) {
                return;
            }
            outputName(name);
            System.out.println(Arrays.toString(x));
        }

        public void debug(String name, long[] x) {
            if (!allowDebug) {
                return;
            }
            outputName(name);
            System.out.println(Arrays.toString(x));
        }

        public void debug(String name, double[] x) {
            if (!allowDebug) {
                return;
            }
            outputName(name);
            System.out.println(Arrays.toString(x));
        }

        public void debug(String name, Object x) {
            if (!allowDebug) {
                return;
            }
            outputName(name);
            System.out.println("" + x);
        }

        public void debug(String name, Object... x) {
            if (!allowDebug) {
                return;
            }
            outputName(name);
            System.out.println(Arrays.deepToString(x));
        }
    }

    public static class Randomized {
        static Random random = new Random(12345678);

        public static double nextDouble(double min, double max) {
            return random.nextDouble() * (max - min) + min;
        }

        public static void randomizedArray(int[] data, int from, int to) {
            to--;
            for (int i = from; i <= to; i++) {
                int s = nextInt(i, to);
                int tmp = data[i];
                data[i] = data[s];
                data[s] = tmp;
            }
        }

        public static void randomizedArray(long[] data, int from, int to) {
            to--;
            for (int i = from; i <= to; i++) {
                int s = nextInt(i, to);
                long tmp = data[i];
