public class Myclass {

	//static ArrayList a[]=new ArrayList[3000001];

	public static void main(String[] args) {

		InputReader in = new InputReader(System.in);
		PrintWriter pw = new PrintWriter(System.out);  	   
		int n=in.nextInt();
		long x=in.nextLong();
		int a[]=new int[n];
		pair p[]=new pair[n];
		int freq[]=new int[1000001];
		boolean chk=true;
		for(int i=0;i<n;i++) {
			a[i]=in.nextInt();
			p[i]=new pair(a[i],i);
			freq[a[i]]=Math.max(freq[a[i]], i);
		}
		Arrays.sort(p,new Comparator<pair>() {
			public int compare(pair p1,pair p2) {
				if(p1.x>p2.x) return -1;
				if(p1.x<p2.x) return 1;
				if(p1.y>p2.y) return -1;
				if(p1.x<p2.y) return 1;
				return 0;
			}
		});
		Segment s=new Segment(n,a);
		segment st=new segment(n,a);
		st.build(0, 0, n-1);
		s.build(0, 0, n-1);
		long end=0;
		for(int i=0;i<n;i++) {
			int val=s.query(0, 0, n-1, 0, p[i].y-1);
			if(val>=1)
			{
				end=p[i].x;
				chk=false;
				break;
			}
			s.update(0, 0, n-1, p[i].y, 1);
			st.update(0, 0, n-1, p[i].y, p[i].x);
			end=p[i].x;
		}
		if(chk) {
			pw.println((x*(x+1))/2);
			pw.flush();
			pw.close();
			System.exit(0);
		}
		s.build(0, 0, n-1);
		Arrays.sort(p,new Comparator<pair>() {
			public int compare(pair p1,pair p2) {
				if(p1.x<p2.x) return -1;
				if(p1.x>p2.x) return 1;
				if(p1.y<p2.y) return -1;
				if(p1.x>p2.y) return 1;
				return 0;
			}
		});
		long start=-1;
		for(int i=0;i<n;i++) {
			int val=s.query(0, 0, n-1, p[i].y+1, n-1);
			if(val>=1)
			{
				start=p[i].x;
				break;
			}
			s.update(0, 0, n-1, p[i].y, 1);
			start=p[i].x;
		}
		long ans=0L;
		for(int i=1;i<=start;i++) {
			ans+=(x-Math.max(i, end)+1);
			if(freq[i]!=0) {
				int val=st.query(0, 0, n-1, 0, freq[i]);
				end=Math.max(val, end);
			}
		}
		pw.println(ans);
		pw.flush();
		pw.close();


	}
	private static void debug(Object... o) {
	        System.out.println(Arrays.deepToString(o));
