solution_11:
#include <bits/stdc++.h>
using namespace std;
const int N = 1e6 + 5;
int n, x, a[N], pre[N], suf[N], mn[N], mx[N];
pair<int, int> seg[5 * N + 5];
void update(int node, int st, int en, int idx, pair<long long, long long> pr) {
  if (st == en) {
    seg[node] = pr;
  } else {
    int mid = (st + en) / 2;
    if (idx >= st && idx <= mid)
      update(2 * node, st, mid, idx, pr);
    else
      update(2 * node + 1, mid + 1, en, idx, pr);
    seg[node] = {min(seg[2 * node].first, seg[2 * node + 1].first),
                 max(seg[2 * node].second, seg[2 * node + 1].second)};
  }
}
pair<int, int> query(int node, int st, int en, int l, int r) {
  if (st > r || en < l) {
    return {1061109567, 0};
  }
  if (l <= st && en <= r) return seg[node];
  int mid = (st + en) / 2;
  pair<int, int> lf = query(2 * node, st, mid, l, r),
                 rt = query(2 * node + 1, mid + 1, en, l, r);
  return {min(lf.first, rt.first), max(lf.second, rt.second)};
}
bool check(int l, int r) {
  if (pre[l - 1] && suf[r + 1] &&
      query(1, 0, x + 1, 0, l - 1).second <=
          query(1, 0, x + 1, r + 1, x + 1).first)
    return 1;
  return 0;
}
void Put(int i) { update(1, 0, x + 1, i, {mn[i], mx[i]}); }
void Sheel(int i) { update(1, 0, x + 1, i, {1061109567, 0}); }
int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  cin >> n >> x;
  memset(mn, '?', sizeof(mn));
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
    mx[a[i]] = max(mx[a[i]], i);
    mn[a[i]] = min(mn[a[i]], i);
  }
  pre[0] = suf[x + 1] = 1;
  int mxx = 0;
  for (int i = 1; i <= x; i++) {
    if (mn[i] > mxx)
      pre[i] = 1;
    else
      break;
    mxx = max(mxx, mx[i]);
  }
  int mnn = 1e9;
  for (int i = x; i > 0; i--) {
    if (mx[i] < mnn)
      suf[i] = 1;
    else
      break;
    mnn = min(mnn, mn[i]);
  }
  int j = 1;
  long long ans = 0;
  Sheel(0);
  Sheel(x + 1);
  for (int i = 2; i <= x; i++) {
    Put(i);
  }
  for (int i = 1; i <= x; i++) {
    while (!check(i, j) && j <= x) {
      Sheel(j);
      j++;
    }
    ans += (x - j + 1);
    Put(i);
    j = max(j, i + 1);
  }
  cout << ans << '\n';
  return 0;
}

solution_12:
import java.lang.*;
import java.math.*;
import java.util.*;
import java.io.*;
public class Main {
class Node implements Comparable<Node>{
    int id;
    int x;
    public Node(int id,int x){
        this.id=id;
        this.x=x;
    }
    public int compareTo(Node c){
        int t=Integer.compare(this.x,c.x);
        if(t!=0) return t;
        return Integer.compare(this.id,c.id);

    }
}
    void solve() {
        int n=ni(),m=ni();
        Node p[]=new Node[n+1];
        for(int i=1;i<=n;i++) p[i]=new Node(i,ni());
        Arrays.sort(p,1,n+1);
        int i1=1,i2=n;
        for(int i=2;i<=n;i++){
            if(p[i-1].id<p[i].id){
                i1=i;
            }else break;
        }
        for(int i=n-1;i>=1;i--){
            if(p[i].id<p[i+1].id) i2=i;
            else break;
        }
        long ans=0;
        for(int L=1;L<=m;L++){
              int id1=0;
              int l=1,r=n;
              while(l<=r){
                  int mid=(l+r)>>1;
                  if(p[mid].x<L){
                      id1=mid;
                      l=mid+1;
                  }else r=mid-1;
              }
              if(id1>i1) break;
              int id2=n+1;
            int Rmin=L;
              if(id1==0){

                      if(i2-1>=1)
                          Rmin=Math.max(Rmin,p[i2-1].x);


              }
              else {
                  l=i2; r=n;
                  while (l <= r) {
                      int mid = (l + r) >> 1;
                      if (p[id1].id < p[mid].id) {
                          id2 = mid;
                          r = mid - 1;
                      } else l = mid + 1;
                  }

                  if(id2==n+1){
                        Rmin=Math.max(Rmin,p[n].x);
                  }else {
                      if(id2-1>=1){
                          Rmin=Math.max(Rmin,p[id2-1].x);
                      }

                  }
              }

         //     pw.println(L+" "+Rmin+" "+id1+" "+id2);

              ans+=m-Rmin+1;

        }
     //   for(int i=1;i<=n;i++) pw.print(p[i].id+" ");
        pw.println(ans);
    }

    long M =(long)1e9+7;

    InputStream is;
    PrintWriter pw;
    String INPUT = "";

    void run() throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        pw = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        pw.flush();
        if (!INPUT.isEmpty()) tr(System.currentTimeMillis() - s + "ms");


    }

    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    private byte[] inbuf = new byte[1024];
    public int lenbuf = 0, ptrbuf = 0;

    private int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b)) ;
        return b;
    }

    private double nd() {
        return Double.parseDouble(ns());
    }

    private char nc() {
        return (char) skip();
    }

    private String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) map[i] = ns(m);
        return map;
    }

    private int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = ni();
        return a;
    }

    private int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl() {
        long num = 0;
        int b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private boolean oj = System.getProperty("ONLINE_JUDGE") != null;

    private void tr(Object... o) {
        if (INPUT.length() > 0) System.out.println(Arrays.deepToString(o));
    }

}

