#include <bits/stdc++.h>
using namespace std;
int l[1000005], r[1000005], s[1000005];
int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  for (int i = 1; i <= n; i++) {
    int x;
    cin >> x;
    if (!l[x]) l[x] = i;
    r[x] = i;
  }
  int k = 1, rb = 0;
  while (k <= m && (!l[k] || rb < l[k])) {
    rb = max(rb, r[k]);
    k++;
  }
  if (k > m) {
    cout << 1LL * m * (m + 1) / 2 << endl;
    return 0;
  }
  l[m + 1] = n + 1;
  for (int i = 1; i <= k; i++)
    if (!r[i]) r[i] = r[i - 1];
  s[m + 1] = k;
  for (int i = m, lb = n + 1; i; i--) {
    if (l[i] && lb < r[i]) break;
    if (l[i]) {
      lb = min(lb, l[i]);
      s[i] = upper_bound(r + 1, r + k, l[i] - 1) - r;
    } else
      s[i] = s[i + 1];
  }
  long long ans = 0;
  for (int i = 1; i <= m + 1; i++) ans += s[i];
  cout << ans;
  return 0;
}

