}

solution_16:
#include <bits/stdc++.h>
using namespace std;
const int N = 1000000 + 77;
long long A;
int n, X, a[N], F[N << 2];
set<int> S;
void Build(int l = 1, int r = X + 1, int id = 1) {
  F[id] = N;
  if (r - l < 2) {
    F[id] = l;
    return;
  }
  int mid = ((l + r) >> 1);
  Build(l, mid, id << 1);
  Build(mid, r, id << 1 ^ 1);
}
void Update(int ql, int qr, int x, int l = 1, int r = X + 1, int id = 1) {
  if (qr <= l || r <= ql) return;
  if (ql <= l && r <= qr) {
    if (F[id] > x) F[id] = x;
    return;
  }
  int mid = ((l + r) >> 1);
  Update(ql, qr, x, l, mid, id << 1);
  Update(ql, qr, x, mid, r, id << 1 ^ 1);
}
void Get(int l = 1, int r = X + 1, int id = 1) {
  if (r - l < 2) {
    A += F[id];
    return;
  }
  int mid = ((l + r) >> 1);
  if (F[id << 1] > F[id]) F[id << 1] = F[id];
  if (F[id << 1 ^ 1] > F[id]) F[id << 1 ^ 1] = F[id];
  Get(l, mid, id << 1);
  Get(mid, r, id << 1 ^ 1);
}
int main() {
  scanf("%d %d", &n, &X);
  for (int i = 1; i <= n; ++i) scanf("%d", a + i);
  Build();
  int t = a[n];
  for (int i = n; i > 0; --i) {
    S.insert(a[i]);
    if (t >= a[i]) {
      t = a[i];
      continue;
    }
    Update(a[i], X + 1, a[i]);
    Update(1, a[i], t);
    auto it = S.lower_bound(a[i]);
    if (it != S.begin()) {
      --it;
      Update(1, *it, 0);
    }
  }
  Get();
  printf("%lld\n", A);
  return 0;
}

solution_17:
import java.util.*;
import java.io.*;
public class helloworld {
 static long fact[];
	static class Reader 
    { 
        final private int BUFFER_SIZE = 1 << 16; 
        private DataInputStream din; 
        private byte[] buffer; 
        private int bufferPointer, bytesRead; 

        public Reader() 
        { 
            din = new DataInputStream(System.in); 
            buffer = new byte[BUFFER_SIZE]; 
            bufferPointer = bytesRead = 0; 
        } 

        public Reader(String file_name) throws IOException 
        { 
            din = new DataInputStream(new FileInputStream(file_name)); 
            buffer = new byte[BUFFER_SIZE]; 
            bufferPointer = bytesRead = 0; 
        } 

        public String readLine() throws IOException 
        { 
            byte[] buf = new byte[64]; // line length 
            int cnt = 0, c; 
            while ((c = read()) != -1) 
            { 
                if (c == '\n') 
                    break; 
                buf[cnt++] = (byte) c; 
            } 
            return new String(buf, 0, cnt); 
        } 

        public int nextInt() throws IOException 
        { 
            int ret = 0; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do
            { 
                ret = ret * 10 + c - '0'; 
            }  while ((c = read()) >= '0' && c <= '9'); 

            if (neg) 
                return -ret; 
            return ret; 
        } 

        public long nextLong() throws IOException 
        { 
            long ret = 0; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 
            if (neg) 
                return -ret; 
            return ret; 
        } 

        public double nextDouble() throws IOException 
        { 
            double ret = 0, div = 1; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 

            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 

            if (c == '.') 
            { 
                while ((c = read()) >= '0' && c <= '9') 
                { 
                    ret += (c - '0') / (div *= 10); 
                } 
            } 

            if (neg) 
                return -ret; 
            return ret; 
        } 

        private void fillBuffer() throws IOException 
        { 
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE); 
            if (bytesRead == -1) 
                buffer[0] = -1; 
        } 

        private byte read() throws IOException 
        { 
            if (bufferPointer == bytesRead) 
                fillBuffer(); 
            return buffer[bufferPointer++]; 
        } 

        public void close() throws IOException 
        { 
            if (din == null) 
                return; 
            din.close(); 
        } 
    } 

	static int getSum(int index , int BITree[]) 
    { 
		index++;
        int  sum = 0; // Iniialize result 

        // index in BITree[] is 1 more than 
        // the index in arr[] 


        // Traverse ancestors of BITree[index] 
        while(index>0) 
        { 
            // Add current element of BITree  
            // to sum 
            sum += BITree[index]; 

            // Move index to parent node in  
            // getSum View 
            index -= index & (-index); 
        } 
        return sum; 
    } 

	static int getMid(int s, int e) 
    { 
        return s + (e - s) / 2; 
    } 

    /* 
    * A recursive function to get the sum  
    of values in given range of the array. 
    * The following are parameters for this function. 
    *  
    * st -> Pointer to segment tree 
    * node -> Index of current node in 
    *         the segment tree. 
    * ss & se -> Starting and ending indexes 
    *         of the segment represented 
    *         by current node, i.e., st[node] 
    * l & r -> Starting and ending indexes 
    *         of range query 
    */
    static int MaxUtil(int[] st, int ss, int se,  
                        int l, int r, int node)  
    { 

        // If segment of this node is completely 
        // part of given range, then return 
        // the max of segment 
        if (l <= ss && r >= se) 
            return st[node]; 

        // If segment of this node does not 
        // belong to given range 
        if (se < l || ss > r) 
            return -1; 

        // If segment of this node is partially 
        // the part of given range 
        int mid = getMid(ss, se); 

        return Math.max(MaxUtil(st, ss, mid, l, r, 2 * node + 1), 
                    MaxUtil(st, mid + 1, se, l, r, 2 * node + 2)); 
    } 

    /* 
    * A recursive function to update the  
    nodes which have the given index in their 
    * range. The following are parameters  
    st, ss and se are same as defined above 
    * index -> index of the element to be updated. 
    */
    static void updateValue(int arr[], int[] st, int ss, 
                    int se, int index, int value, int node) 
    { 
        if (index < ss || index > se) 
        { 
            System.out.println("Invalid Input"); 
            return; 
        } 

        if (ss == se) 
        { 

            // update value in array and in segment tree 
            arr[index] = value; 
            st[node] = value; 
        }  
        else
        { 
            int mid = getMid(ss, se); 

            if (index >= ss && index <= mid) 
                updateValue(arr, st, ss, mid, index, value, 2 * node + 1); 
            else
                updateValue(arr, st, mid + 1, se, index, value, 2 * node + 2); 

            st[node] = Math.max(st[2 * node + 1], st[2 * node + 2]); 
        } 
        return; 
    } 

    // Return max of elements in range from 
    // index l (query start) to r (query end). 
    static int getMax(int[] st, int n, int l, int r) 
    { 

        // Check for erroneous input values 
        if (l < 0 || r > n - 1 || l > r)  
        { 
            System.out.printf("Invalid Input\n"); 
            return -1; 
        } 

        return MaxUtil(st, 0, n - 1, l, r, 0); 
    } 

    // A recursive function that constructs Segment 
    // Tree for array[ss..se]. si is index of 
    // current node in segment tree st 
    static int constructSTUtil(int arr[], int ss, 
                        int se, int[] st, int si)  
    { 

        // If there is one element in array, store 
        // it in current node of segment tree and return 
        if (ss == se)  
        { 
            st[si] = arr[ss]; 
            return arr[ss]; 
        } 

        // If there are more than one elements, then 
        // recur for left and right subtrees and 
        // store the max of values in this node 
        int mid = getMid(ss, se); 

        st[si] = Math.max(constructSTUtil(arr, ss, mid, st, si * 2 + 1), 
                constructSTUtil(arr, mid + 1, se, st, si * 2 + 2)); 

        return st[si]; 
    } 

    /* 
    * Function to construct segment tree from 
    given array. This function allocates 
    * memory for segment tree. 
    */
    static int[] constructST(int arr[], int n) 
    { 

        // Height of segment tree 
        int x = (int) Math.ceil(Math.log(n) / Math.log(2)); 

        // Maximum size of segment tree 
        int max_size = 2 * (int) Math.pow(2, x) - 1; 

        // Allocate memory 
        int[] st = new int[max_size]; 

        // Fill the allocated memory st 
        constructSTUtil(arr, 0, n - 1, st, 0); 

        // Return the constructed segment tree 
        return st; 
    } 
    public static void updateBIT(int n, int index,  
                                        int val , int BITree[] ) 
    { 
        // index in BITree[] is 1 more than  
        // the index in arr[] 
        index++;
        // Traverse all ancestors and add 'val' 
        while(index <= n) 
        { 
        // Add 'val' to current node of BIT Tree 
        BITree[index] += val; 

        // Update index to that of parent  
        // in update View 
        index += index & (-index); 
        } 
    } 
    static long mod = 1000000007;
   static long pow(long a , long b , long c)
   {

	   if(b==0)
		   return 1;

	   long ans = pow(a,b/2,c);
	   if(b%2 == 0)
		   return ans*ans%c;

	   return ans*ans%c*a%c;
   }

   static long modInverse(long a , long b)
   {
	   return pow(a,b-2,mod);
   }


   static double d(int x1 , int y1 , int x2 , int y2)
   {
	   double d1 = x1-x2;
	   double d2 = y1-y2;

	   return Math.sqrt(d1*d1-d2*d2);
   }


static void dfs(int n , LinkedList<Integer> arr[]  , boolean visited[])
{
	visited[n] = true;
	for(Integer i : arr[n])
	{
		if(!visited[i])
		{
			dfs(i,arr,visited);
		}
	}
}
	public static void main(String[] args) throws IOException {
		Reader sc = new Reader();
	    int n = sc.nextInt();
	    int x = sc.nextInt();
	    int arr[] = new int[n];
	    int min[] = new int[x+2];
	    int max[] = new int[x+2];
	    for(int i = 0 ; i <= x+1 ; i++)
	    {
	    	min[i] = Integer.MAX_VALUE;
	    	max[i] = Integer.MIN_VALUE;
	    }

	    for(int i = 0 ; i < n ; i++)
	    {
	    	arr[i] = sc.nextInt();
	    	min[arr[i]] = Math.min(min[arr[i]] , i);
	    	max[arr[i]] = Math.max(max[arr[i]], i);
	    }
	    int pre[] = new int[x+2];
	    int post[] = new int[x+2];

	    int last = -1;
	    for(int i = 1 ; i <= x ; i++)
	    {
	    	if(min[i] == Integer.MAX_VALUE)
	    	{
	    		pre[i] = 1;
	    		continue;
	    	}
	    	if(min[i] > last)
	    	{
	    		pre[i] = 1;
	    		last = max[i];
	    	}

	    	else
	    		break;
	    }
	     last = n;
	    for(int i = x ; i >= 1 ; i--)
	    {
	    	if(max[i] == Integer.MIN_VALUE)
	    	{
	    		post[i] = 1;
	    		continue;
	    	}

	    	if(max[i] < last)
	    	{
	    		post[i] = 1;
	    		last = min[i];
	    	}

	    	else
	    		break;
	    }

	    for(int i = 1 ; i <= x ; i++)
	    {
	           max[i] = Math.max(max[i-1] , max[i]);
	    }

	    for(int i = x-1 ; i >= 0 ; i--)
	    {
	    	min[i] = Math.min(min[i+1], min[i]);
	    }
	    pre[0] = 1;
	    post[x+1] = 1;
	    int l = 1 , r = 1;
	    long ans = 0;
	    while(l <= x && r <= x)
	    {
	    	boolean sorted = false;
	    	if(pre[l-1] == 1 && post[r+1] == 1 && max[l-1] < min[r+1])
	    	sorted = true;

	    	if(!sorted)
	    	{
	    		r++;
	    	}

	    	else
	    	{

	    		while(true)
	    		{
	    		     sorted = false;
	    			if(pre[l-1] == 1 && post[r+1] == 1 && max[l-1] < min[r+1])
	    				sorted = true;

	    			if(sorted && l <= r)
	    			{
	    				//System.out.println(l + " " + r);
	    			ans += x-r+1;
	    			l++;
	    			}

	    			else
	    				break;
	    		}
	    		r++;
	    	}
	    }
	    System.out.println(ans);
	}
}

