import static java.lang.Math.min;
import static java.lang.Math.max;
import static java.lang.Math.abs;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class EatmoresTemplate {
    static int N;
    static int[] A;
    static final int MAX_A = (int) 1e7;

    static void solve() {
        N = scanInt();
        A = new int[N];
        Arrays.setAll(A, i -> scanInt());

        int[] maxDiv = new int[MAX_A + 1];
        Arrays.fill(maxDiv, -1);
        for (int i = 2; i <= MAX_A; i++) {
            if (maxDiv[i] == -1) {
                for (int j = i; j <= MAX_A; j += i) {
                    maxDiv[j] = i;
                }
            }
        }

        int[] d1 = new int[N];
        int[] d2 = new int[N];
        for (int i = 0; i < N; i++) {
            int tmp = A[i];
            while (tmp > 1 && tmp % maxDiv[A[i]] == 0) {
                tmp /= maxDiv[A[i]];
            }
            if (tmp == 1) {
                d1[i] = d2[i] = -1;
            } else {
                d1[i] = maxDiv[A[i]];
                d2[i] = tmp;
            }
        }

        for (int i = 0; i < N; i++) {
            out.print(d1[i] + " ");
        }
        out.println();
        for (int i = 0; i < N; i++) {
            out.print(d2[i] + " ");
        }
        out.println();
    }

    public static void main(String[] args) {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        int t = 1;
        // t = scanInt();
        for (int i = 1; i <= t; i++) {
            solve();
        }
        out.close();
    }

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;

    static int scanInt() {
        return Integer.parseInt(scanString());
    }

    static long scanLong() {
        return Long.parseLong(scanString());
    }

    static double scanDouble() {
        return Double.parseDouble(scanString());
    }

    static String scanString() {
        while (tok == null || !tok.hasMoreTokens()) {
            try {
                tok = new StringTokenizer(in.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tok.nextToken();
    }
}

