import java.util.Scanner;

public class twoDivisors {
	static int div[] = new int[10000001];

	static void findDiv() {
		for (int i = 2; i <= Math.sqrt(div.length); i++)
			if (div[i] == 0)
				for (int j = i * i; j < div.length; j = j + i)
					if (div[j] == 0)
						div[j] = i;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(), a[] = new int[n];
		findDiv();
		StringBuilder d1s = new StringBuilder(), d2s = new StringBuilder();
		for (int i = 0; i < n; i++)
			a[i] = sc.nextInt();
		for (int i = 0; i < n; i++) {
			int temp = div[a[i]];
			if (temp == 0 || Math.sqrt(temp) == a[i]) {
				d1s.append("-1 ");
				d2s.append("-1 ");
			} else {
				temp = a[i];
				while (temp > 0 && temp % div[a[i]] == 0) {
					temp /= div[a[i]];
				}
				int d1 = temp, d2 = a[i] / temp;
				if (d1 <= 1 || d2 <= 1) {
					d1s.append("-1 ");
					d2s.append("-1 ");
				} else {
					d1s.append(d1 + " ");
					d2s.append(d2 + " ");
				}
			}
		}
		System.out.print(d1s + "\n" + d2s);
		sc.close();
	}
}

