#include <bits/stdc++.h>
using namespace std;
const int N = 500005;
const int MAX = (int)1e7 + 5;
int n;
bitset<MAX> isPrime;
vector<int> primeList;
int ans1[N], ans2[N];
inline void Sieve() {
  isPrime.set();
  isPrime[0] = isPrime[1] = 0;
  for (int i = 2; i < MAX; i++) {
    if (isPrime[i]) {
      primeList.push_back(i);
      for (long long j = 1ll * i * i; j < MAX; j += i) {
        isPrime[j] = 0;
      }
    }
  }
}
int main() {
  Sieve();
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    ans1[i] = ans2[i] = -1;
    int x;
    scanf("%d", &x);
    if (!isPrime[x]) {
      int root = (int)sqrt(x);
      for (int j = 0; primeList[j] <= root; j++) {
        int p = primeList[j];
        if (x % p == 0) {
          ans1[i] = 1;
          while (x % p == 0) {
            ans1[i] *= p;
            x /= p;
          }
          if (x == 1) {
            ans1[i] = ans2[i] = -1;
          } else {
            ans2[i] = x;
          }
          break;
        }
      }
    }
  }
  for (int i = 0; i < n; i++) printf("%d%c", ans1[i], i == n - 1 ? '\n' : ' ');
  for (int i = 0; i < n; i++) printf("%d%c", ans2[i], i == n - 1 ? '\n' : ' ');
  return 0;
}

