#include <bits/stdc++.h>
using namespace std;
const int maxn = 5e5 + 5;
const int mod = 1e9 + 7;
int a[maxn], b[maxn], c[maxn], n;
bool vis[10005];
int prime[10005];
int xx = 0;
void oulasai(int n) {
  for (int i = 2; i <= n; i++) {
    if (!vis[i]) prime[xx++] = i;
    for (int j = 0; j < xx; j++) {
      if (i * prime[j] > n) break;
      vis[i * prime[j]] = true;
      if (i % prime[j] == 0) break;
    }
  }
}
int main() {
  ios::sync_with_stdio(false);
  int T = 1;
  oulasai(10000);
  while (T--) {
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i <= n; i++) {
      int x = 1, z = a[i];
      bool f = false;
      for (int k = 0; k < xx; k++) {
        int j = prime[k];
        if (j * j > a[i]) break;
        if (z % j != 0) continue;
        while (z % j == 0) {
          z /= j;
          x *= j;
        }
        if (x != a[i]) f = true;
        break;
      }
      if (f)
        b[i] = x, c[i] = a[i] / x;
      else
        b[i] = -1, c[i] = -1;
    }
    for (int i = 1; i <= n; i++) cout << b[i] << " ";
    cout << endl;
    for (int i = 1; i <= n; i++) cout << c[i] << " ";
    cout << endl;
  }
  return 0;
}

