import java.util.*;
import java.io.*;

public class I {

    private int[] minDiv;

    public I(FastScanner in, PrintWriter out) {

        minDiv = new int[(int)1e7 + 1];
        for (int i = 2; i < minDiv.length; i++)
            minDiv[i] = i;

        int bound = (int)Math.sqrt(minDiv.length - 1);
        for (int i = 2; i <= bound; i++) {
            if (minDiv[i] == i) {
                for (int j = i * i; j < minDiv.length; j += i) {
                    if (minDiv[j] == j) minDiv[j] = i;
                }
            }
        }

        int n = in.nextInt();
        List<String> d1 = new ArrayList<>(n);
        List<String> d2 = new ArrayList<>(n);

        for (int i = 0; i < n; i++) {
            int a = in.nextInt();
            List<Integer> f = getPrimeFactors(a);
            if (f.size() < 2) {
                d1.add("-1");
                d2.add("-1");
            } else {
                int p1 = f.get(0);
                int p2 = f.stream().reduce(1, (x, y) -> x * y) / p1;
                d1.add(String.valueOf(p1));
                d2.add(String.valueOf(p2));
                // if (gcd(p1 + p2, a) != 1) {
                    // out.printf("%d -- %d, %d%n", a, p1, p2);
                // }
            }
        }
        out.println(String.join(" ", d1));
        out.println(String.join(" ", d2));
    }

    private List<Integer> getPrimeFactors(int a) {
        List<Integer> res = new ArrayList<>();
        while (a > 1) {
            int f = minDiv[a];
            if (res.size() == 0 || res.get(res.size() - 1) != f)
                res.add(f);
            a /= f;
        }
        return res;
    }

    private int gcd(int a, int b) {
        if (a == 0) return b;
        return gcd(b % a, a);
    }

    // given integer s, find the smallest integer so that its digits
    // sums up to s. This integer cannot ends with 9.
    // greedy -- add as many 9 as possible. set last digit to 8
    private long build(int s) {
        if (s < 9) return s;
        long pow = 10;
        s -= 8;
        int m = s / 9; // number of 9s
        while (m-- > 0) pow *= 10;

        return s % 9 * pow + (pow - 10) + 8;
    }


    public static void main(String[] args) {
        PrintWriter out = new PrintWriter(System.out);
        // Scanner in = new Scanner(
                // new BufferedReader(new InputStreamReader(System.in)));
        FastScanner in = new FastScanner(System.in);

        I sol = new I(in, out);

        out.close();
    }
}


class FastScanner{
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner(InputStream stream)
    {
        this.stream = stream;
    }

    int read()
    {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars){
            curChar = 0;
            try{
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    boolean isSpaceChar(int c)
    {
        return c==' '||c=='\n'||c=='\r'||c=='\t'||c==-1;
    }

    boolean isEndline(int c)
    {
        return c=='\n'||c=='\r'||c==-1;
    }

    int nextInt()
    {
        return Integer.parseInt(next());
    }

    long nextLong()
    {
        return Long.parseLong(next());
    }

    double nextDouble()
    {
        return Double.parseDouble(next());
    }

    String next(){
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isSpaceChar(c));
        return res.toString();
    }

    String nextLine(){
        int c = read();
        while (isEndline(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do{
            res.appendCodePoint(c);
            c = read();
        }while(!isEndline(c));
        return res.toString();
    }
}

