#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1e9 + 7;
class Sieve {
  long long n_;
  vector<long long> sieve_, primes_;

 public:
  explicit Sieve(long long n = 1) : n_(n), sieve_(n + 1) {
    sieve_[0] = sieve_[1] = -1;
    for (long long i = 2; i <= n; ++i) {
      if (sieve_[i]) continue;
      primes_.push_back(i);
      sieve_[i] = i;
      for (long long j = i * i; j <= n; j += i) {
        if (!sieve_[j]) sieve_[j] = i;
      }
    }
  }
  bool isPrime(long long x) {
    assert(n_ * n_ >= x);
    if (n_ >= x) {
      return sieve_[x] == x;
    } else {
      for (const auto prime : primes_) {
        if (x % prime == 0) return false;
      }
      return true;
    }
  }
  vector<long long> getPrimes() { return primes_; }
  vector<pair<long long, int>> getPrimeFactorList(long long x) {
    assert(n_ * n_ >= x);
    vector<long long> factorList;
    for (int i = (int)primes_.size() - 1; i >= 0; i--) {
      if (n_ >= x) break;
      while (x % primes_[i] == 0) {
        x /= primes_[i];
        factorList.emplace_back(primes_[i]);
      }
    }
    if (isPrime(x)) {
      factorList.emplace_back(x);
      x /= x;
    }
    assert(n_ >= x);
    while (x != 1) {
      factorList.push_back(sieve_[x]);
      x /= sieve_[x];
    }
    if (factorList.empty()) return {};
    vector<pair<long long, int>> res(1, pair<long long, int>(factorList[0], 0));
    for (long long p : factorList) {
      if (res.back().first == p) {
        res.back().second++;
      } else {
        res.emplace_back(p, 1);
      }
    }
    return res;
  }
};
namespace lib {
long long gcd(long long a, long long b) {
  if (a < b) swap(a, b);
  long long r = a % b;
  while (r != 0) {
    a = b;
    b = r;
    r = a % b;
  }
  return b;
}
long long lcm(long long a, long long b) { return a * b / gcd(a, b); }
long long floor(long long a, long long b) {
  if (abs(a) % abs(b) == 0) return a / b;
  if ((a > 0 && b > 0) || (a < 0 && b < 0))
    return a / b;
  else
    return a / b - 1;
}
long long ceil(long long a, long long b) {
  if (abs(a) % abs(b) == 0) return a / b;
  if ((a > 0 && b > 0) || (a < 0 && b < 0))
    return a / b + 1;
  else
    return a / b;
}
}  // namespace lib
class DTwoDivisors {
 public:
  void solve(std::istream& in, std::ostream& out) {
    long long n;
    in >> n;
    Sieve sieve(1e7 + 1);
    vector<long long> a(n), d1(n, -1), d2(n, -1);
    for (long long i = (0); i < (n); i++) in >> a[i];
    for (long long i = (0); i < (n); i++) {
      auto list = sieve.getPrimeFactorList(a[i]);
      if (list.size() <= 1) continue;
      d1[i] = list.front().first;
      d2[i] = 1;
      for (long long j = (1); j < (list.size()); j++) d2[i] *= list[j].first;
    }
    for (long long i = (0); i < (n); i++)
      out << d1[i] << (i == n - 1 ? "\n" : " ");
    for (long long i = (0); i < (n); i++)
      out << d2[i] << (i == n - 1 ? "\n" : " ");
  }
};
signed main() {
  DTwoDivisors solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

