import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static PrintWriter out = new PrintWriter(System.out);
    static Reader in = new Reader();
    public static void main(String[] args) throws IOException {
        Main solver = new Main();
        solver.solve();
        out.flush();
        out.close();

    }

    static int INF = (int)1e9;
    static int maxn = (int)1e7+5;
    static int mod  = 998244353;
    static int n,m,q,k,t;

    void solve() throws IOException{

        int[] sieve = new int[maxn];
        for (int i = 0; i < maxn; i++) sieve[i] = -1;
        for (int i = 2; i < maxn; i++) {
            if (sieve[i] == -1) {
                for (int j = i; j < maxn; j+=i) {
                    if (sieve[j] == -1) sieve[j] = i;
                }
            }
        }

        n = in.nextInt();

        int[] arr = new int[n];
        for (int i = 0; i < n ; i++) arr[i] = in.nextInt();

        int[] a = new int[n];
        int[] b = new int[n];
        int tmp = 0, div = 0;
        for (int i = 0; i < n; i++) {
            div = sieve[arr[i]];
            tmp = 1;
            while (arr[i]%div == 0) {
                arr[i]/=div;
                tmp *= div;
            }

            if (arr[i] == 1) {
                a[i] = -1;
                b[i] = -1;
            } else {
                a[i] = tmp;
                b[i] = arr[i];
            }
        }

        for (int i = 0; i < n; i++) out.print(a[i]+" ");
        out.println();
        for (int i = 0; i < n; i++) out.print(b[i]+" ");
        out.println();
    }

    //<>

    static class Reader {

    private InputStream mIs;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public Reader() {
        this(System.in);
    }

    public Reader(InputStream is) {
        mIs = is;
    }

    public int read() {
        if (numChars == -1) {
            throw new InputMismatchException();

    }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = mIs.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    public String nextLine() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isEndOfLine(c));
        return res.toString();
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    double nextDouble()
    {
        return Double.parseDouble(next());
    }

    public long nextLong() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public boolean isEndOfLine(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }

    }
}

