#include <bits/stdc++.h>
using namespace std;
const long long int maxr = 1e7 + 5;
long long int spf[maxr];
void precompute() {
  for (long long int i = 0; i < maxr; i++) {
    spf[i] = i;
  }
  for (long long int i = 2; i < maxr; i++) {
    if (spf[i] == i) {
      for (long long int j = i; j < maxr; j += i) spf[j] = min(spf[j], i);
    }
  }
}
int32_t main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  ;
  long long int n;
  cin >> n;
