  vector<pair<long long int, long long int> > ans;
  for (long long int i = 0; i < n; i++) {
    long long int x;
    cin >> x;
    long long int xx = x;
    long long int s = spf[x];
    while (x % s == 0) x /= s;
    if (x == 1)
      ans.push_back({-1, -1});
    else
      ans.push_back({s, x});
  }
  for (auto x : ans) cout << x.first << " ";
  cout << endl;
  for (auto x : ans) cout << x.second << " ";
  return 0;
}

