#include <bits/stdc++.h>
using namespace std;
template <class T = int>
using V = vector<T>;
template <class T = int>
using VV = V<V<T>>;
using ll = long long;
using ld = long double;
using pii = pair<int, int>;
using pll = pair<ll, ll>;
using pdd = pair<ld, ld>;
template <typename T>
struct PrimeFact {
  vector<T> spf;
  PrimeFact(T N) { init(N); }
  void init(T N) {
    spf.assign(N + 1, 0);
    for (T i = 0; i <= N; i++) spf[i] = i;
    for (T i = 2; i * i <= N; i++) {
      if (spf[i] == i) {
        for (T j = i * i; j <= N; j += i) {
          if (spf[j] == j) {
            spf[j] = i;
          }
        }
      }
    }
  }
  map<T, T> get(T n) {
    map<T, T> m;
    while (n != 1) {
      m[spf[n]]++;
      n /= spf[n];
    }
    return m;
  }
};
int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  V<int> a(n);
  for (int i = 0; i < (n); i++) cin >> a[i];
  PrimeFact<int> p(1e7 + 5);
  V<int> ans1(n), ans2(n);
  for (int i = 0; i < (n); i++) {
    auto ret = p.get(a[i]);
    V<int> v;
    for (auto x : ret) {
      v.push_back(x.first);
    }
    if (v.size() < 2)
      ans1[i] = -1, ans2[i] = -1;
    else {
      sort((v).begin(), (v).end());
      ans1[i] = v[0];
      ans2[i] = 1;
      for (int j = 1; j < v.size(); j++) ans2[i] *= v[j];
    }
  }
  for (int i = 0; i < (n); i++) cout << ans1[i] << ' ';
  cout << endl;
  for (int i = 0; i < (n); i++) cout << ans2[i] << ' ';
  cout << endl;
}

