#include <bits/stdc++.h>
using namespace std;
const int MAXN = 10000007;
bool isprime[MAXN];
vector<long long> prime;
long long SPF[MAXN];
void sieve(int n) {
  isprime[0] = isprime[1] = false;
  for (int i = 2, ggdem = n + 1; i < ggdem; ++i) {
    if (isprime[i]) prime.push_back(i), SPF[i] = i;
    for (int j = 0;
         j < ((int)prime.size()) && i * prime[j] <= n && prime[j] <= SPF[i];
         j++) {
      isprime[i * prime[j]] = false;
      SPF[i * prime[j]] = prime[j];
    }
  }
}
int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);
  long long n;
  cin >> n;
  long long a[n];
  for (int i = 0, ggdem = n; i < ggdem; ++i) cin >> a[i];
  memset((isprime), (true), sizeof(isprime));
  sieve(MAXN);
  vector<pair<long long, long long>> res;
  for (int i = 0, ggdem = n; i < ggdem; ++i) {
    vector<long long> p;
    long long val = a[i];
    while (val > 1) {
      long long s = SPF[val];
      p.push_back(s);
      while (val % s == 0) val /= s;
    }
    long long maxi = 1;
    val = a[i];
    while (val % p[0] == 0) maxi *= p[0], val /= p[0];
    if (val != 1)
      res.push_back({maxi, val});
    else
      res.push_back({-1, -1});
  }
  for (int i = 0, ggdem = n; i < ggdem; ++i) cout << res[i].first << " ";
  cout << "\n";
  for (int i = 0, ggdem = n; i < ggdem; ++i) cout << res[i].second << " ";
  cout << "\n";
  return 0;
}

