    ans[i][1] = -1;
    long long int q = 1;
    long long int temp = prime[a];
    if (temp != 1) {
      while (a % temp == 0) {
        a = a / temp;
        q = q * temp;
      }
      if (a != 1) {
        ans[i][0] = q;
        ans[i][1] = a;
      }
    }
