int qn[100004];
int main() {
  int q;
  scanf("%d", &q);
  int i;
  for (i = 1; i <= q; i++) {
    scanf("%d", &qn[i]);
  }
  for (i = 1; i <= q; i++) {
    int n = qn[i];
    int l = 0;
    int r = n - 1;
    long long int ans = 0;
    while (l <= r) {
      long long m1 = (l + (r - l) / 3);
      long long m2 = (r - (r - l) / 3);
      long long val1, val2;
      if ((m1 + 1) * 1LL * m1 > 2 * 1LL * (n - m1 - 1))
        val1 = 2 * (n - m1 - 1);
      else
        val1 = n - m1 - 1 + (1LL * (m1 + 1) * m1) / 2;
      if ((m2 + 1) * 1LL * m2 > 2 * 1LL * (n - m2 - 1))
        val2 = 2 * (n - m2 - 1);
      else
        val2 = n - m2 - 1 + (1LL * (m2 + 1) * m2) / 2;
      if (val1 < val2) {
        ans = max(ans, val2);
        l = m1 + 1;
      } else {
        ans = max(ans, val1);
        r = m2 - 1;
      }
    }
    printf("%I64d\n", ans);
  }
  return 0;
}

