#include <bits/stdc++.h>
using namespace std;
void read(long long &x) {
  x = 0;
  char c = getchar();
  int f = 1;
  while (c < '0' || c > '9') {
    if (c == '-') f = -f;
    c = getchar();
  }
  while (c >= '0' && c <= '9') {
    x = (x << 3) + (x << 1) + c - '0';
    c = getchar();
  }
  x *= f;
  return;
}
long long maxt(long long a, long long b) { return a > b ? a : b; }
long long mint(long long a, long long b) { return a < b ? a : b; }
void write(long long x) {
  if (x < 0) {
    putchar('-');
    x = -x;
  }
  if (x < 10) {
    putchar('0' + x);
    return;
  }
  write(x / 10);
  putchar(x % 10 + '0');
  return;
}
long long q, n;
long long check(long long k) { return n - k + mint(n - k, (k - 1) * k >> 1); }
int main() {
  read(q);
  while (q--) {
    read(n);
    long long l = 1, r = n;
    while (l < r - 1) {
      long long mid1 = l + (r - l) / 3;
      long long mid2 = r - (r - l) / 3;
      long long a = check(mid1), b = check(mid2);
      if (a <= b) l = mid1 + 1;
      if (a >= b) r = mid2 - 1;
    }
    printf("%lld\n", maxt(check(l), check(l + 1)));
  }
}

