void doit() {
  long long n = gi();
  long long ans = n - 1;
  long long lo = 0, hi = n, md;
  while (lo + 1 < hi) {
    md = (lo + hi) / 2;
    long long nb = n - md;
    long long v = (md * (md - 1)) / 2;
    if (nb >= v)
      lo = md;
    else
      hi = md;
  }
  for (long long x = max(3LL, lo - 5); x < min(lo + 5, n); x++) {
    long long v = (x * (x - 1)) / 2;
    long long nb = n - x;
    if (v > nb) v = nb;
    domax(ans, nb + v);
  }
  cout << ans << endl;
}
