#include <bits/stdc++.h>
using namespace std;
bool isOk(long long n, long long E) {
  long long k = (E + 1) / 2;
  long long rem = n - k;
  long long remE = E - k;
  return remE <= rem * (rem - 1) / 2 && remE >= rem - 1 && rem >= 0 &&
         remE >= 0;
}
long long ternarySearch(long long n) {
  if (n == 1) return 0;
  long long lo = n - 1, hi = n * (n + 1) / 2;
  while (hi > lo + 1) {
    long long mid = (hi + lo) >> 1;
    if (isOk(n, mid)) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  if (isOk(n, lo + 1))
    return lo + 1;
  else if (isOk(n, lo))
    return lo;
  else
    return lo - 1;
}
int main() {
  int n;
