import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.PrintStream;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

/*
 public class _818F {

 }

 */

public class _818F
{
	public void solve() throws FileNotFoundException
	{
		InputStream inputStream = System.in;

		InputHelper inputHelper = new InputHelper(inputStream);

		PrintStream out = System.out;

		// actual solution
		int q = inputHelper.readInteger();

		while (q-- > 0)
		{
			long n = inputHelper.readInteger();

			long lo = n - 1;
			long hi = 2 * n;

			long ans = n - 1;
			while (lo <= hi)
			{
				long mid = (lo + hi) / 2;

				long b = (mid + 1) / 2;

				if (b + 1 > n)
				{
					hi = mid - 1;
				}
				else
				{
					long rn = n - b;

					long mxep = (rn * (rn - 1)) / 2;

					if (mxep >= mid - b)
					{
						ans = Math.max(ans, mid);
						lo = mid + 1;
					}
					else
					{
						hi = mid - 1;
					}
				}
			}

			System.out.println(ans);
		}

		// end here
	}

	public static void main(String[] args) throws FileNotFoundException
	{
		(new _818F()).solve();
	}

	class InputHelper
	{
		StringTokenizer tokenizer = null;
		private BufferedReader bufferedReader;

		public InputHelper(InputStream inputStream)
		{
			InputStreamReader inputStreamReader = new InputStreamReader(
					inputStream);
			bufferedReader = new BufferedReader(inputStreamReader, 16384);
		}

		public String read()
		{
			while (tokenizer == null || !tokenizer.hasMoreTokens())
			{
				try
				{
					String line = bufferedReader.readLine();
					if (line == null)
					{
						return null;
					}
					tokenizer = new StringTokenizer(line);
				}
				catch (IOException e)
				{
					e.printStackTrace();
				}
			}

			return tokenizer.nextToken();
		}

		public Integer readInteger()
		{
			return Integer.parseInt(read());
		}

		public Long readLong()
		{
			return Long.parseLong(read());
		}
	}
}

