      {
         BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
         StringTokenizer st = new StringTokenizer(infile.readLine());
         int T = Integer.parseInt(st.nextToken());
         StringBuilder sb = new StringBuilder();
         int[] lol = new int[5];
         lol[2] = 1;
         lol[3] = 2;
         lol[4] = 3;
         while(T-->0)
         {
            long N = Long.parseLong(infile.readLine());
            if(N <= 4)
            {
               sb.append(lol[(int)N]+"\n");
               continue;
            }
            long low = 2;
            long high = N;
            while(low+3 <= high)
            {
               long lmid = low+(high-low)/3;
               long rmid = high-(high-low)/3;
               if(edges(N, lmid) <= edges(N, rmid))
                  low = lmid;
               else
                  high = rmid;
            }
            long res = edges(N, low);
            for(long i=low+1; i <= high; i++)
               res = Math.max(res, edges(N, i));
            sb.append(res+"\n");
         }
         System.out.print(sb);
      }
      public static long edges(long N, long edges)
      {
         long left = N-edges;
         left += Math.min(left, edges*(edges-1)/2);
         return left;
      }
   }

