import java.io.*;
import java.util.*;

import static java.lang.Math.*;

public class D {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        char[] s = in.next().toCharArray();
        int n = s.length;
        int lis[] = new int[n];
        int a[] = new int[n], inf = (int) 1e9;
        for (int i = 0, zero = 0, max = 0; i < n; i++) {
            a[i] = inf;
            if (s[i] == '0') {
                lis[i] = zero + 1;
                max = max(max, lis[i]);
                a[i] = max - lis[i];
                zero++;
            } else {
                lis[i] = max + 1;
                max = max(max, lis[i]);
            }
        }
        SegTree segTree = new SegTree(n);
        segTree.build(a);
        char t[] = new char[n];
        for (int i = 0, zero = 0; i < n; i++) {
            if (s[i] == '0') {
                t[i] = '0';
                zero++;
            } else {
                if (zero + 1 == lis[i] && segTree.query(i, n - 1) > 0) {
                    zero++;
                    t[i] = '0';
                    segTree.update(i + 1, n - 1, -1);
                } else {
                    t[i] = '1';
                }
            }
        }

        pw.println(t);

        pw.close();
    }

    static void debug(Object... obj) {
        System.err.println(Arrays.deepToString(obj));
    }

    static class SegTree {
        int n, seg[], lazy[], arr[], inf = (int) 1e8;

        SegTree(int N) {
            n = N;
            seg = new int[4 * n];
            lazy = new int[4 * n];
        }

        void build(int a[]) {
            arr = a;
            build(1, 1, n);
        }

        void build(int p, int s, int e) {
            if (s == e) {
                seg[p] = arr[s - 1];
                return;
            }
            if (s > e) return;
            int m = (s + e) / 2, l = 2 * p, r = 2 * p + 1;
            build(l, s, m);
            build(r, m + 1, e);
            seg[p] = min(seg[l], seg[r]);
        }

        void pushDown(int p, int l, int r) {
            if (lazy[p] == 0) return;
            lazy[l] += lazy[p];
            seg[l] += lazy[p];
            lazy[r] += lazy[p];
            seg[r] += lazy[p];
            lazy[p] = 0;
        }

        void update(int l, int r, int val) {
            l++;
            r++;
            update(1, 1, n, l, r, val);
        }

        void update(int p, int s, int e, int a, int b, int val) {
            if (s >= a && e <= b) {
                seg[p] += val;
                lazy[p] += val;
                return;
            }
            if (s > b || s > e || e < a) return;
            int m = (s + e) / 2, l = 2 * p, r = 2 * p + 1;
            pushDown(p, l, r);
            update(l, s, m, a, b, val);
            update(r, m + 1, e, a, b, val);
            seg[p] = min(seg[l], seg[r]);
        }

        int query(int l, int r) {
            l++;
            r++;
            return query(1, 1, n, l, r);
        }

        int query(int p, int s, int e, int a, int b) {
            if (s >= a && e <= b) {
                return seg[p];
            }
            if (s > e || s > b || e < a) return inf;
            int m = (s + e) / 2, l = 2 * p, r = 2 * p + 1;
            pushDown(p, l, r);
            return min(query(l, s, m, a, b), query(r, m + 1, e, a, b));
        }
    }
}

