public class d {
    public static void main(String[] args) {
        FS in = new FS(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String s = in.next();
        ArrayDeque<Integer> q = new ArrayDeque<>();
        boolean[] isFixed = new boolean[s.length()];
        for(int i = 0; i < s.length(); i++) {
            if(s.charAt(i) == '1') q.addLast(i);
            else if(!q.isEmpty()) {
                isFixed[i] = true;
                isFixed[q.pollLast()] = true;
            }
        }
        StringBuilder str = new StringBuilder();
        for(int i = 0; i < s.length(); i++) if(isFixed[i]) str.append(s.charAt(i)); else str.append(0);
        out.println(str);
        out.close();
    }

    static class FS {

        BufferedReader in;
        StringTokenizer token;

        public FS(InputStream str) {
            in = new BufferedReader(new InputStreamReader(str));
        }

        public String next() {
            if (token == null || !token.hasMoreElements()) {
                try {
                    token = new StringTokenizer(in.readLine());
                } catch (IOException ex) {
                }
                return next();
            }
            return token.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

