import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.PrintStream;
import java.util.Arrays;
import java.util.Scanner;

public class CF_1024D2 {
    public static void main(String[] args) {
        Scanner in = new Scanner(new BufferedInputStream(System.in));
        PrintStream out = new PrintStream(new BufferedOutputStream(System.out));

        String s = in.next();
        int n = s.length();
        int[] zcounts = new int[n];
        int[] dp = new int[n];

        dp[0] = 1;
        zcounts[0] = s.charAt(0) == '0' ? 1 : 0;

        for (int i = 1; i < n; i++) {
            zcounts[i] = s.charAt(i) == '0' ? 1 : 0;
            zcounts[i] += zcounts[i - 1];

            if (s.charAt(i) == '1') {
                dp[i] = dp[i - 1] + 1;
            } else {
                dp[i] = Math.max(zcounts[i], dp[i - 1]);
            }
        }

        int[] ocounts = new int[n];
        int[] dpe = new int[n];

        dpe[n - 1] = 1;
        ocounts[n - 1] = s.charAt(n - 1) == '1' ? 1 : 0;

        for (int i = n - 1 - 1; i >= 0; i--) {
            ocounts[i] = s.charAt(i) == '1' ? 1 : 0;
            ocounts[i] += ocounts[i + 1];

            if (s.charAt(i) == '0') {
                dpe[i] = dpe[i + 1] + 1;
            } else {
                dpe[i] = Math.max(ocounts[i], dpe[i + 1]);
            }
        }

        int extra = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') {
                out.print(0);
                continue;
            }

            int ret = zcounts[i] + extra + 1 + (i == n - 1 ? 0 : dpe[i + 1]);
            ret = Math.max(ret, (i == 0 ? 0 : dp[i - 1]) + ocounts[i] - 1);

            if (ret == dp[n - 1]) {
                extra++;
                out.print(0);
            }
            else out.print(1);
        }

        out.close();
        in.close();
    }
}

