import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Diff {

	int key, value;

	Diff(int key, int value) {
		this.key = key;
		this.value = value;
	}

	@Override
	public String toString() {
		// TODO Auto-generated method stub
		return "key:" + this.key + "value:" + this.value;
	}

	public static void main(String... args) throws Exception {
		Diff diff;
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		char s[] = br.readLine().toCharArray();
		int ans[] = new int[s.length];
		boolean in1 = false, in0 = false,f1=false;
		ArrayList<Diff> al = new ArrayList<Diff>();

		int no0 = 0, no1 = 0;
		int j = 0;
		for (int i = 0; i < s.length; i++) {
			al.add(new Diff(i, s[i] - 48));
		}
		for (int i = 0; i < al.size();) {
			diff = al.get(i);
			if (diff.value == 1) {
				for (j = i; j < al.size(); j++) {
					diff = al.get(j);
					if (no0 > no1) {
						no0--;
						j--;
						break;
					}
					if (in0 && diff.value == 1) {
						break;
					} else if (diff.value == 1) {
						in1 = true;
						no1++;
					} else {
						in1 = false;
						in0 = true;
						no0++;
					}
				}
//				System.out.println(j);
				if(no0>no1){
					no0=no1;
				}
				for (int k = j-1; k >=i+no1-no0; k--) {
					diff=al.get(k);
					ans[diff.key]=diff.value;
					al.remove(k);
				}
				if(no0==0){
					f1 = true;
				}
				in1 = false;
				in0 = false;
//				System.out.println("no0:" + no0 + "no1:" + no1);
				no0 = 0;
				no1 = 0;
			}
			if(i<al.size()&&al.get(i).value==0){
				i++;
			}
			if(f1){
				break;
			}
		}
		for (int i = 0; i < ans.length; i++) {
			System.out.print(ans[i]);
		}
	}
}

