  for (int i = 1; i <= n; i++) {
    if (s[i] == '0')
      f[i] = max(f[i - 1], zero[i]);
    else
      f[i] = f[i - 1] + 1;
  }
  for (int i = n; i >= 1; i--) {
    if (s[i] == '1')
      g[i] = max(g[i + 1], one[i]);
    else
      g[i] = g[i + 1] + 1;
  }
  int temp = f[n];
  int sum = 0;
  for (int i = 1; i <= n; i++) {
    zero[i] += sum;
    if (t[i] == '1') {
      int mx = max(f[i - 1] + one[i + 1], zero[i - 1] + 1 + g[i + 1]);
      if (mx == temp) {
        t[i] = '0';
        sum++;
        zero[i]++;
      }
    }
  }
  cout << t + 1 << endl;
  return 0;
}

