#include <bits/stdc++.h>
namespace solution {
using namespace std;
const int SIZE = 101;
int n, m, k;
int A[SIZE];
class Solution {
 private:
  void init() {}
  bool input() {
    if (!(cin >> n >> m >> k)) return false;
    for (int i = 0; i < n; ++i) {
      cin >> A[i];
    }
    return true;
  }
  int solve() {
    int sockets = k;
    if (sockets >= m) return 0;
    sort(A, A + n, greater<int>());
    for (int i = 0; i < n; ++i) {
      sockets--;
      if (sockets < 0) return -1;
      sockets += A[i];
      if (sockets >= m) return i + 1;
    }
    return -1;
  }

 public:
  int run() {
    while (init(), input()) {
      cout << solve() << endl;
    }
    return 0;
  }
};
}  // namespace solution
int main() {
  using namespace solution;
  Solution s;
  return s.run();
}

