public class Sockets {
	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] temp = br.readLine().split("\\s+");
		String[] supplyline = br.readLine().split("\\s+");
		int devices = Integer.parseInt(temp[1]);
		int sockets = Integer.parseInt(temp[2]);
		int supplyUsed = 0;
		ArrayList<Integer> f = new ArrayList<Integer>();
		for (int i=0; i<supplyline.length; i++) {
			f.add(Integer.parseInt(supplyline[i]));
		}
		Collections.sort(f);
		while (sockets<devices) {
			if (f.size()==0||sockets==0) {
				supplyUsed=-1;
				break;
			}
			sockets--;
			sockets+=f.get(f.size()-1);
			f.remove(f.size()-1);
			supplyUsed++;
		}
		System.out.println(supplyUsed);
	}
}

