import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.Comparator;

// could not submit,, question was lost
public final class COffeeBreakCF {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String st[] = br.readLine().split(" ");
        int n = Integer.parseInt(st[0]);
        int m = Integer.parseInt(st[1]);
        int d = Integer.parseInt(st[2]);
        Pair arr[] = new Pair[n];
        String s[] = br.readLine().split(" ");
        for (int i = 0; i < n; i++) {
            int x = Integer.parseInt(s[i]);
            arr[i] = new Pair(x, i);
        }
        Arrays.sort(arr, new Comparator<Pair>() {
            @Override
            public int compare(Pair a, Pair b) {
                if (a.first < b.first) {
                    return -1;
                } else if (a.first > b.first) {
                    return 1;
                } else
                    return 0;
            }
        });
        int ans = Integer.MAX_VALUE;
        int left = 1, right = n;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (helper(arr, mid, d)) {
                ans = mid;
                right = mid - 1;
            } else
                left = mid + 1;
        }
        System.out.println(ans);
        int out[] = new int[n];
        int start = 0;
        for (int i = 0; i < arr.length; i++) {
            int index = arr[i].second;
            out[index] = (start + 1);
            start = (start + 1) % ans;
        }
        for(int ele:out){
            System.out.print(ele+" ");
        }
        System.out.println();
    }

    private static boolean helper(Pair[] arr, int mid, int d) {
        int ans[] = new int[mid];
        int start = 0;
        for (int i = 0; i < mid; i++) {
            ans[start] = arr[i].first;
            start = (start + 1) % mid;
        }
        for (int i = mid; i < arr.length; i++) {
            if (arr[i].first - ans[start] > d) {
                ans[start] = arr[i].first;
                start = (start + 1) % mid;
            } else
                return false;
        }
        return true;
    }

}
class Pair {
    int first;
    int second;
    public Pair(int first,int second){
        this.first=first;
        this.second=second;
    }
}

