solution_6:
import java.util.*;
import java.io.*;
import java.lang.reflect.Array;
import java.math.BigInteger;

public class C {
	FastScanner in;
	PrintWriter out;
	boolean systemIO = true;

	public class Pause implements Comparable<Pause>{
		int time;
		int number;

		public Pause(int time, int number) {
			this.time = time;
			this.number = number;
		}

		@Override
		public int compareTo(Pause o) {
			if (this.time != o.time) {
				return this.time - o.time;
			}
			return this.number - o.number;
		}
	}

	public void solve() {
		int n = in.nextInt();
		int m = in.nextInt();
		int d = in.nextInt();
		TreeSet<Pause> set = new TreeSet<>();
		for (int i = 0; i < n; i++) {
			set.add(new Pause(in.nextInt(), i));
		}
		int[] ans = new int[n];
		int day = 0;
		while (!set.isEmpty()) {
			day++;
			Pause th = set.pollFirst();
			ans[th.number] = day;
			Pause next = set.higher(new Pause(th.time + d, n));
			while (next != null) {
				set.remove(next);
				th = next;
				ans[th.number] = day;
				next = set.higher(new Pause(th.time + d, n));
			}
		}
		out.println(day);
		for (int i = 0; i < ans.length; i++) {
			out.print(ans[i] + " ");
		}
	}

	public void run() {
		try {
			if (systemIO) {
				in = new FastScanner(System.in);
				out = new PrintWriter(System.out);
			} else {
				in = new FastScanner(new File("input.txt"));
				out = new PrintWriter(new File("output.txt"));
			}
			solve();

			out.close();
		} catch (IOException e) {
			e.printStackTrace();
		}
	}

	class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		FastScanner(File f) {
			try {
				br = new BufferedReader(new FileReader(f));
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		FastScanner(InputStream f) {
			br = new BufferedReader(new InputStreamReader(f));
		}

		String nextLine() {
			try {
				return br.readLine();
