int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  long long int n, m, d;
  cin >> n >> m >> d;
  long long int a[n];
  map<long long int, long long int> make_pair;
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    make_pair[a[i]] = i;
  }
  long long int prev = 0;
  long long int c = 1;
  int b[n + 1];
  while (make_pair.size() > 0) {
    if (prev > m) {
      prev = 0;
      c++;
    }
    auto it = make_pair.lower_bound(prev);
    int k = it->second;
    if (it == make_pair.end()) {
      prev += m;
      continue;
    }
    b[k] = c;
    prev = it->first + d + 1;
    make_pair.erase(it->first);
  }
  cout << c << "\n";
  for (int i = 0; i < n; i++) cout << b[i] << " ";
  cout << "\n";
  return 0;
}

