import java.util.*;
import java.io.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        int m=sc.nextInt();
        int d=sc.nextInt();
        int a[]=new int[n];
        TreeSet<Integer> hs=new TreeSet<>();
        Map<Integer,Integer> hm=new HashMap<>();
        for(int i=0;i<n;i++){
        a[i]=sc.nextInt();
        hs.add(a[i]);
        hm.put(a[i],i);
        }
        int count=0;
        int ans[]=new int[n];
        while(hs.size()!=0) {
            count++;
            int start=hs.first();
            int ind=hm.get(start);
            ans[ind]=count;
            hs.remove(start);
            while(true) {
                Integer next=hs.higher(start+d);
                if(next==null)
                break;
                else {
                    start=next;
                    ind=hm.get(start);
                   ans[ind]=count;
                   hs.remove(start);
                }
            }
        }
        System.out.println(count);
        for(int e:ans)
        System.out.print(e+" ");
        System.out.println();
    }
}

