import java.util.*;

public class C1041C{
	public static void main(String[] args){
		Scanner in = new Scanner(System.in);
		int n = in.nextInt(), m = in.nextInt(), d = in.nextInt();
		node[] a = new node[n];
		for(int i=0;i<n;i++)a[i] = new node(in.nextInt(),i);
		Arrays.sort(a,(x,y)->x.d-y.d);
		Queue<node> q = new LinkedList<>();
		int[] ans = new int[n];
		q.add(a[0]);
		int k = 2;
		ans[a[0].i] = 1;
		for(int i=1;i<n;i++){
			node x = q.peek();
			if(a[i].d-x.d>=d+1){
				ans[a[i].i] = ans[x.i];
				q.poll();
			}
			else{
				ans[a[i].i] = k;
				k++;
			}
			q.add(a[i]);
		}
		System.out.println(k-1);
		for(int i=0;i<n;i++)
			System.out.print(ans[i]+" ");
	}
}
class node{
	int d,i;
	public node(int x,int y){
		this.d = x;
		this.i = y;
	}
}
