import java.io.*;
import java.util.*;

public class Main {
    static OutWriter out;
    static InReader in;
    static int mod = (int) (1e9) + 7;
    static int d;


    public static void main(String args[]) throws IOException {
        in = new InReader();
        out = new OutWriter();
        int n = in.nextInt();
        int length = in.nextInt();
        d = in.nextInt();
        Pair all[] = new Pair[n];
        for (int i = 0; i < n; i++) {
            all[i] = new Pair(i, in.nextInt());
        }
        Arrays.sort(all);
        int count = 1;
        all[0].day = 1;
        TreeSet<Pair> S = new TreeSet<>();

        S.add(all[0]);
        for (int i = 1; i < n; i++) {
            Pair curr = all[i];
            curr.val-=(d);
            Pair to = S.lower(curr);
            if (to==null) {
                count++;
                curr.val+=(d);
                curr.day = count;
                S.add(curr);
            } else {
                curr.day=to.day;
                curr.val+=(d);
                S.remove(to);
                S.add(curr);
            }
        }
        int ans[] = new int[n];
        for (int i = 0; i < n; i++) {
            ans[all[i].number] = all[i].day;
        }
        out.println(count);
        for (int i = 0; i < n; i++) {
            out.prints(ans[i]);
        }


        out.close();
    }

    static class Pair implements Comparable<Pair> {
        int number;
        int val;
        int day;

        Pair(int number, int val) {
            this.val = val;
            this.number = number;
        }

        @Override
        public int compareTo(Pair o) {
            if(val - o.val != 0){
                return val-o.val;
            }else {
                if(number-o.number!=0){
                    return -1;
                }else {
                    return 0;
                }
            }
        }
    }

    static class Vertex implements Comparable<Vertex> {
        int number;
        int deg;

        Vertex(int number, int deg) {
            this.number = number;
            this.deg = deg;
        }

        @Override
        public int compareTo(Vertex o) {
            if (deg != o.deg) {
                return deg - o.deg;
            } else {
                return number - o.number;
            }
        }
    }



   /* static class Vertex {
        int number = -1;
        int depth = 0;
        boolean used2 = false;
        boolean used = false;
        long value = 0;
        ArrayList<Edge> to = new ArrayList();


    }*/


    static class Edge {
        int to;
        int from;

        Edge(int from, int to) {
            this.from = from;
            this.to = to;
        }
    }

    static class InReader {
        BufferedReader in;

        InReader(String name) throws IOException {
            in = new BufferedReader(new FileReader(name));
        }

        InReader() {
            in = new BufferedReader(new InputStreamReader(System.in));
        }

        StringTokenizer token = new StringTokenizer("");

        void update() throws IOException {
            if (!token.hasMoreTokens()) {
                String a = in.readLine();
                if (a != null) {
                    token = new StringTokenizer(a);
                }
            }
        }

        int nextInt() throws IOException {
            update();
            return Integer.parseInt(token.nextToken());
        }

        long nextLong() throws IOException {
            update();
            return Long.parseLong(token.nextToken());
        }

        double nextDouble() throws IOException {
            update();
            return Double.parseDouble(token.nextToken());
        }

        boolean hasNext() throws IOException {
            update();
            return token.hasMoreTokens();
        }

        String next() throws IOException {
            update();
            return token.nextToken();
        }
    }

    static class OutWriter {
        PrintWriter out;

        OutWriter() {
            out = new PrintWriter(System.out);
        }

        OutWriter(String name) throws IOException {
            out = new PrintWriter(new FileWriter(name));
        }

        StringBuilder cout = new StringBuilder();

        <T> void print(T a) {
            cout.append(a);
        }

        <T> void println(T a) {
            cout.append(a);
            cout.append('\n');
        }

        <T> void prints(T a) {
            cout.append(a);
            cout.append(' ');
        }

        void close() {
            out.print(cout.toString());
            out.close();
        }
    }
}

solution_15:
import java.util.*;
import java.lang.*;
import java.math.*;
import java.io.*;
import static java.lang.Math.*;

/* spar5h */

public class cf3 implements Runnable{    

	static class pair {

		int i; long w;

		pair(int i, long w) {
			this.i = i; this.w = w;
		}
	}

	static class comp implements Comparator<pair> {

		public int compare(pair x, pair y) {

			if(x.w < y.w)
				return -1;

			if(x.w > y.w)
				return 1;

			return 0;
		}
	}

	public void run() {

		InputReader s = new InputReader(System.in);
		PrintWriter w = new PrintWriter(System.out);

		int n = s.nextInt();

		long m = s.nextLong(), d = s.nextLong() + 1;

		ArrayList<pair> a = new ArrayList<pair>();

		for(int i = 0; i < n; i++)
			a.add(new pair(i, s.nextLong()));

		Collections.sort(a, new comp());

		int[] color = new int[n + 1];

		PriorityQueue<pair> pq = new PriorityQueue<pair>(new comp()); 

		int count = 0;

		for(int i = 0; i < n; i++) {

			if(pq.isEmpty() || a.get(i).w - pq.peek().w < d) {
				count++; color[a.get(i).i] = count; pq.add(new pair(count, a.get(i).w)); continue;
			}

			color[a.get(i).i] = pq.peek().i;
			pq.poll();
			pq.add(new pair(color[a.get(i).i], a.get(i).w));
		}

		w.println(count);

		for(int i = 0; i < n; i++)
			w.print(color[i] + " ");

		w.println();

		w.close();
	}

	static class InputReader {

		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;
		private SpaceCharFilter filter;

		public InputReader(InputStream stream)
		{
			this.stream = stream;
		}

		public int read()
		{
			if (numChars==-1) 
				throw new InputMismatchException();

			if (curChar >= numChars)
			{
				curChar = 0;
				try 
				{
					numChars = stream.read(buf);
				}
				catch (IOException e)
				{
					throw new InputMismatchException();
				}

				if(numChars <= 0)				
					return -1;
			}
			return buf[curChar++];
		}

		public String nextLine()
		{
			BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
			String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
		}
		public int nextInt()
		{
			int c = read();

			while(isSpaceChar(c)) 
				c = read();

			int sgn = 1;

			if (c == '-') 
			{
				sgn = -1;
				c = read();
			}

			int res = 0;
			do 
			{
				if(c<'0'||c>'9') 
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			}
			while (!isSpaceChar(c)); 

			return res * sgn;
		}

		public long nextLong() 
		{
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') 
			{
				sgn = -1;
				c = read();
			}
			long res = 0;

			do 
			{
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			}
			while (!isSpaceChar(c));
				return res * sgn;
		}

		public double nextDouble() 
		{
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') 
			{
				sgn = -1;
				c = read();
			}
			double res = 0;
			while (!isSpaceChar(c) && c != '.') 
			{
				if (c == 'e' || c == 'E')
					return res * Math.pow(10, nextInt());
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			}
			if (c == '.') 
			{
				c = read();
				double m = 1;
				while (!isSpaceChar(c)) 
				{
					if (c == 'e' || c == 'E')
						return res * Math.pow(10, nextInt());
					if (c < '0' || c > '9')
						throw new InputMismatchException();
					m /= 10;
					res += (c - '0') * m;
					c = read();
				}
			}
			return res * sgn;
		}

		public String readString() 
		{
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do 
			{
				res.appendCodePoint(c);
				c = read();
			} 
			while (!isSpaceChar(c));

			return res.toString();
		}

		public boolean isSpaceChar(int c) 
		{
			if (filter != null)
				return filter.isSpaceChar(c);
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		public String next() 
		{
			return readString();
		}

		public interface SpaceCharFilter 
		{
			public boolean isSpaceChar(int ch);
		}
	}

	public static void main(String args[]) throws Exception
	{
		new Thread(null, new cf3(),"cf3",1<<26).start();
	}
}

