import java.io.*; import java.util.*;
public class coffeebreak {

	public static void main(String[] args) throws IOException{

		//BufferedReader br = new BufferedReader(new FileReader("./src/coffeebreak.in"));
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		StringTokenizer st = new StringTokenizer(br.readLine());
		int numBreaks = Integer.parseInt(st.nextToken());
		int dayLen = Integer.parseInt(st.nextToken());
		int minGap = Integer.parseInt(st.nextToken());

		TreeMap<Integer, Integer> breaks = new TreeMap<Integer, Integer>();
		st = new StringTokenizer(br.readLine());

		for(int i=0; i<numBreaks; i++){
			breaks.put(Integer.parseInt(st.nextToken()), i);
		}

		//format answer a little more
		int[] answers = new int[numBreaks];

		int at = 1; //first minute
		int pastDays = 1; 
		while(!breaks.isEmpty()){//while the set is not zero
			Object possFl = breaks.ceilingKey(at); //find the lowest
			if(possFl == null){ //too big
				at = 1; //from beginning
				pastDays++; //a new day starts
				int rm = breaks.firstKey();
				int rmi = breaks.get(rm);
				breaks.remove(rm);
				answers[rmi] = pastDays; 
				possFl = rm;

			}
			else{
				answers[breaks.get(possFl)] = (int)pastDays;
				breaks.remove(possFl);
			}
			at = (int)possFl + minGap + 1; //update any jumps
		}

		//System.out.println(Arrays.toString(answers));
		System.out.println(pastDays);
		for(int i=0; i<numBreaks-1; i++)
			System.out.print(answers[i]+" ");
		System.out.println(answers[answers.length-1]);



		//so here you want 


		br.close();

	}

	public static class Break implements Comparable<Break>{
		int ind, val;
		public Break(int index, int value){
			ind = index;
			val = value;
		}

		public int compareTo(Break o){
			return (int)(Math.signum(val - o.val));
		}

		public String toString(){
			return "VAL: "+val+" IND: "+ind;
		}

	}

}

