import java.util.*;
import java.io.*;

public class Main
{
	public static void main(String[] args)
	{
		FastReader reader = new FastReader();
		PrintWriter writer = new PrintWriter(System.out);

		int n = reader.nextInt();
		long m = reader.nextLong();
		long d = reader.nextLong();

		TreeMap<Long, Integer> map = new TreeMap<>();
		TreeSet<Long> set = new TreeSet<>(); 

		long[] array = new long[n];
		int[] num = new int[n];

		for (int i=0; i<n; i++)
		{
			array[i] = reader.nextLong();
			set.add(array[i]);
			map.put(array[i], i);
		}

		int day=0;

		while (!set.isEmpty())
		{
			Long f = set.first();
			day++;

			while (f != null)
			{
				set.remove(f);
				num[map.get(f)] = day;
				f = set.higher(f+d);
			}
		}

		writer.println(day);
		for (int i : num)
			writer.print(i + " ");

		writer.close();
	}

	static class FastReader
	{
		BufferedReader br;
		StringTokenizer st;

		public FastReader()
		{
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next()
		{
			while (st == null || !st.hasMoreElements())
			{
				try
				{
					st = new StringTokenizer(br.readLine());
				}
				catch (IOException e)
				{
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt()
		{
			return Integer.parseInt(next());
		}

		long nextLong()
		{
			return Long.parseLong(next());
		}

		double nextDouble()
		{
			return Double.parseDouble(next());
		}

		String nextLine()
		{
			String str = "";
			try
			{
				str = br.readLine();
			}
			catch (IOException e)
			{
				e.printStackTrace();
			}
			return str;
		}
	}
}

