import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.TreeSet;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CCoffeeBreak solver = new CCoffeeBreak();
        solver.solve(1, in, out);
        out.close();
    }

    static class CCoffeeBreak {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt(), d = in.nextInt();
            TreeSet<pair> t = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                t.add(new pair(in.nextInt(), i));
            }
            int ans[] = new int[n];
            int tm = 0, cd = 1;
            while (!t.isEmpty()) {
                if (tm == 0) {
                    pair c = t.first();
                    ans[c.ind] = cd;
                    tm = c.v + d + 1;
                    t.remove(c);
                    continue;
                }
                if (tm > m) {
                    tm = 0;
                    cd++;
                } else {
                    pair c = t.ceiling(new pair(tm, 0));
                    if (c == null) {
                        tm = 0;
                        cd++;
                    } else {
                        ans[c.ind] = cd;
                        tm = c.v + d + 1;
                        t.remove(c);
                    }
                }
            }
            out.println(cd);
            for (int c : ans) {
                out.print(c + " ");
            }
        }

        class pair implements Comparable<pair> {
            int v;
            int ind;

            pair(int vv, int iind) {
                v = vv;
                ind = iind;
            }


            public int compareTo(pair pair) {
                if (this.v == pair.v) {
                    return Integer.compare(this.ind, pair.ind);
                }
                return Integer.compare(this.v, pair.v);
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}
